def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    walls = [(r, c) for r, row in enumerate(grid) for c, cell in enumerate(row) if cell == '#']
    stack = [(start, [start])]
    seen = set([start])

    while stack:
        (x, y), path = stack.pop()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and (nx, ny) not in walls and (nx, ny) not in seen:
                if (nx, ny) == goal:
                    return path + [(nx, ny)]
                seen.add((nx, ny))
                stack.append(((nx, ny), path + [(nx, ny)]))

    return []

