from collections import deque

def is_valid(grid, row, col):
    """Check if cell is inside grid and is not a wall."""
    return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] != '#'

def get_neighbours(grid, row, col):
    """Get all 4 orthogonal neighbours of a cell."""
    neighbours = []
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        r, c = row + dr, col + dc
        if is_valid(grid, r, c):
            neighbours.append((r, c))
    return neighbours

def solve(grid, start, goal):
    """Find a path between start and goal in the grid."""
    rows, cols = len(grid), len(grid[0])

    # If start or goal is a wall or equals, handle special cases
    if (start == goal and grid[start[0]][start[1]] == '.') or start == goal:
        return [start] if grid[start[0]][start[1]] != '#' else []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # Create queue and set of visited cells
    queue = deque([(start, [start])])
    visited = set([start])

    # Bfs: explore all neighbours of a cell before moving to the next cell
    while queue:
        (cell, path) = queue.popleft()
        if cell == goal:
            return path
        for neighbour in get_neighbours(grid, *cell):
            if neighbour not in visited:
                queue.append((neighbour, path + [neighbour]))
                visited.add(neighbour)

    return []

