from collections import deque

def find_valid_neighbours(grid, row, col):
    """Finds all valid neighbours (up, down, left, right) for a given cell."""
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    neighbours = []
    for dr, dc in directions:
        r, c = row + dr, col + dc
        if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.':
            neighbours.append((r, c))
    return neighbours

def solve(grid, start, goal):
    """Finds a path between two cells of a grid."""
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    visited = set()
    queue = deque([start])

    while queue:
        r, c = queue.popleft()
        if (r, c) == goal:
            path = [(r, c)]
            while (r, c) != start:
                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    r_prev, c_prev = path[-1][0] + dr, path[-1][1] + dc
                    if 0 <= r_prev < len(grid) and 0 <= c_prev < len(grid[0]) and (r_prev, c_prev) not in visited:
                        path.append((r_prev, c_prev))
                        break
            return path

        visited.add((r, c))
        for neighbour in find_valid_neighbours(grid, r, c):
            queue.append(neighbour)

    return []

