def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]   # right, left, down, up
    moved = {(start[0], start[1])}

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols and grid[x][y] == '.'

    def find_path(x, y, path):
        if (x, y) == goal:
            return path + [(x, y)]
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and (nx, ny) not in moved:
                moved.add((nx, ny))
                result = find_path(nx, ny, path + [(x, y)])
                if result:
                    return result
                moved.remove((nx, ny))
        return None

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    elif start == goal:
        return path_from_path([start], start)
    else:
        return path_from_path(find_path(start[0], start[1], [start]), goal)


