def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    possible_moves = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def is_valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.'

    def find_path(cell):
        queue = [cell]
        visited = set([cell])
        path = {}
        path[cell] = [cell]
        while queue:
            c = queue.pop(0)
            if c == goal:
                return get_path(path)
            for move in possible_moves:
                new_row, new_col = c[0] + move[0], c[1] + move[1]
                if is_valid(new_row, new_col) and (new_row, new_col) not in visited:
                    queue.append((new_row, new_col))
                    visited.add((new_row, new_col))
                    path[(new_row, new_col)] = path[c] + [(new_row, new_col)]
        return []

    def get_path(path):
        start_path = path.get(start, [])
        goal_path = path.get(goal, [])
        if start_path and goal_path:
            return [cell for cell in zip(start_path, goal_path) if cell[0] == cell[1]]
        return []

