    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    while queue:
        x, y = queue.popleft()
        if (x, y) == goal:
            path = [(x, y)]
            while (x, y) != start:
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '.' and visited[nx][ny]:
                        x, y = nx, ny
                        path.append((x, y))
                        break
            return path
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '.' and not visited[nx][ny]:
                queue.append((nx, ny))
