import heapq

def solve(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    queue = [(0, s)]
    distance = [float('inf')] * n
    distance[s] = 0

    while queue:
        d, u = heapq.heappop(queue)
        if u == t:
            return d
        if d > distance[u]:
            continue
        for v, w in graph[u]:
            ndist = d + w
            if ndist < distance[v]:
                distance[v] = ndist
                heapq.heappush(queue, (ndist, v))

    return -1

