def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    visited = set([start])
    queue = deque([start])

    def valid(row, col):
        'Check if row and col are a valid cell in the grid.'
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.'

    def neighbors(pos):
        '_yield the 4 orthogonal neighbours of pos'
        r, c = pos
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            yield (r + dr, c + dc)

    def find_path(pos):
        'Dfs and find any path to goal, marking visited visited.'
        if pos == goal:
            return [pos]
        visited.add(pos)
        path = None
