import heapq

def solve(n, edges, s, t):
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    dist = [sys.maxsize] * n
    dist[s] = 0
    queue = [(0, s)]

    while queue:
        curr_dist, curr_node = heapq.heappop(queue)
        if curr_dist > dist[curr_node]:
            continue
        for neighbor, weight in adj[curr_node]:
            alt_dist = curr_dist + weight
            if alt_dist < dist[neighbor]:
                dist[neighbor] = alt_dist
                heapq.heappush(queue, (alt_dist, neighbor))

    return dist[t] if dist[t] != sys.maxsize else -1

