def solve(grid, start, goal):
    if not 0 <= start[0] < len(grid) or not 0 <= start[1] < len(grid[0]) or grid[start[0]][start[1]] == '#':
        return []
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if not js_equals(grid, start, goal):
        frontier, came_from = [(start, [start])], {}
        while frontier:
            (current_pos, path) = frontier.pop(0)
            for next_pos in get_neighbors(grid, current_pos):
                if next_pos == goal and grid[next_pos[0]][next_pos[1]] == '.':
                    return path + [goal]
                if grid[next_pos[0]][next_pos[1]] == '.' and next_pos not in came_from:
                    frontier.append((next_pos, path + [next_pos]))
                    came_from[next_pos] = current_pos
        return []
    return []

def js_equals(grid, start, goal):
    return start == goal and not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '.')

def get_neighbors(grid, cell):
    neighbors = []
    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        x, y = cell[0] + dx, cell[1] + dy
        if 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '.':
            neighbors.append((x, y))
    return neighbors

