    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((w, v))

    distances = [float('inf')] * n
    distances[s] = 0

    pq = [(0, s)]
    seen = {s}

    while pq:
        d, u = heapq.heappop(pq)
        if u == t:
            return d
        if d > distances[u]:
            continue
        for w, v in graph[u]:
            if v not in seen:
                seen.add(v)
