import heapq

def dijkstra(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((w, v))
    dist = [float('inf')] * n
    dist[s] = 0
    queue = [(0, s)]
    while queue:
        d, u = heapq.heappop(queue)
        if d > dist[u]:
            continue
        for w, v in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(queue, (dist[v], v))
    return dist[t] if dist[t] != float('inf') else -1

def solve(n, edges, s, t):
    if s == t:
        return 0
    weights = [row[0] for row in edges]
    if any(w == 0 for w in weights):
        graph = [0] * n
        degs = [0] * n
        for u, _, _ in edges:
            graph[u] += 1
            degs[u] += 1
        if degs[t] == 0:
            return -1
        ugraph = [0] * n
        for v, _, _ in edges:
            ugraph[v] += 1
        queue = [(s, 0)]
        while queue:
            u, d = queue.pop(0)
            if u == t:
                return d
            for _, v in enumerate(graph):
                if v > 0:
                    graph[u] -= 1
                    graph[u] = 0
                    queue.append((u, d))
                    u = v
                    degs[u] -= 1
                    graph[u] += 1
                    break
            for _, v in enumerate(graph):
                if graph[v] == 0 and degs[v] == 0 and u != v:
                    queue.append((v, d + 1))
    return dijkstra(n, edges, s, t)

