def solve(n: int, edges: List[Tuple[int, int, int]], s: int, t: int) -> int:
    g = [[] for _ in range(n)]
    for u, v, w in edges:
        g[u].append((v, w))

    if s == t:
        return 0

    dist = [float('inf')] * n
    dist[s] = 0

    pq = [(0, s)]
    vis = set()
    while pq:
        d, u = heapq.heappop(pq)
        if u in vis:
            continue
        vis.add(u)
        for v, w in g[u]:
            if d + w < dist[v]:
                dist[v] = d + w
                heapq.heappush(pq, (dist[v], v))

    return dist[t] if dist[t] != float('inf') else -1

