            if curr_node == t:
                return curr_dist
            if curr_dist > distance[curr_node]:
                continue
            for u, v, w in edges:
                if u == curr_node:
                    if dist := distance[curr_node] + w < distance[v]:
                        distance[v] = dist
                        heapq.heappush(pq, (dist, v))
        return -1

    return dijkstra()
