    extended_graph = {}
    for u in graph:
        extended_graph[u] = {}
        for v, weight in graph[u].items():
            for v_next, weight_next in graph.get(v, {}).items():
                extended_graph[u][v_next] = weight + weight_next
    return extended_graph

def dijkstra(graph, s):
    queue = [(0, s)]
    distances = {u: None for u in graph}
    distances[s] = 0
    while queue:
        current_distance, current_node = heapq.heappop(queue)
        if current_distance > distances[current_node]:
            continue
        for neighbor, distance in graph[current_node].items():
            old_distance = distances.get(neighbor)
            new_distance = current_distance + distance
            if old_distance is None or old_distance > new_distance:
                distances[neighbor] = new_distance
                heapq.heappush(queue, (new_distance, neighbor))
    return distances

def solve(n, edges, s, t):
