from heapq import heappop, heappush
from collections import deque

def dijkstra(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    distance = [float('inf')] * n
    distance[s] = 0
    priority_queue = [(0, s)]

    while priority_queue:
        num, u = heappop(priority_queue)
        for v, w in graph[u]:
            if distance[v] > distance[u] + w:
                distance[v] = distance[u] + w
                heappush(priority_queue, (num + w, v))

    return distance[t] if distance[t] != float('inf') else -1

def bellman_ford(n, edges, s, t):
    distance = [float('inf')] * n
    distance[s] = 0
    for _ in range(n - 1):
        for u, v, w in edges:
            if distance[u] != float('inf') and distance[u] + w < distance[v]:
                distance[v] = distance[u] + w

    for u, v, w in edges:
        if distance[u] != float('inf') and distance[u] + w < distance[v]:
            return -1

    return distance[t] if distance[t] != float('inf') else -1

def solve(n, edges, s, t):
    result_dijkstra = dijkstra(n, edges, s, t)
    result_bellman_ford = bellman_ford(n, edges, s, t)

    return result_dijkstra if result_dijkstra != -1 else result_bellman_ford

def BFS(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    distance = [0] * n
    queue = deque((s,))

    while queue:
        u = queue.popleft()
        distance[u] = 0
        for v, _ in graph[u]:
            if (distance[u] + 1 < distance[v]) or (distance[v] == -1):
                distance[v] = distance[u] + 1
                queue.append(v)

    return distance[t] if distance[t] != -1 else -1

