import heapq

def solve(n, edges, s, t):
    edges.sort(key=lambda x: x[2])
    def dfs(u, visited):
        if u == t:
            return 0
        visited[u] = True
        for v, w in edges:
            if v == u and not visited[v]:
                adj_val = dfs(v, visited)
                if adj_val != -1:
                    return adj_val + w
        visited[u] = False
        return -1

    adj = [None] * n
    for u, v, w in edges:
        adj[u] = [(v, w)] if adj[u] is None else adj[u] + [(v, w)]

    tries = 0
    for u, _, _ in edges:
        tries += 1
        visited = [False] * n
        if dfs(u, visited) != -1:
            return tries

    distances = [float('inf')] * n
    distances[s] = 0
    queue = [(0, s)]
    seen_edges = set()

    while queue:
        dist, u = heapq.heappop(queue)
        if dist > distances[u]:
            continue
        for v, w in adj[u]:
            key = (u, v)
            if key in seen_edges:
                continue
            seen_edges.add(key)
            if dist + w < distances[v]:
                distances[v] = dist + w
                heapq.heappush(queue, (distances[v], v))

    return distances[t]

    visited = [False] * n
    return dfs(s, visited)

