        if dfs(u, visited) != -1:
            return tries

    distances = [float('inf')] * n
    distances[s] = 0
    queue = [(0, s)]
    seen_edges = set()

    while queue:
        dist, u = heapq.heappop(queue)
        if dist > distances[u]:
            continue
        for v, w in adj[u]:
            key = (u, v)
            if key in seen_edges:
                continue
            seen_edges.add(key)
            if dist + w < distances[v]:
                distances[v] = dist + w
                heapq.heappush(queue, (distances[v], v))

    return distances[t]

    visited = [False] * n
    return dfs(s, visited)
