        prev = [None] * n
        dist[s] = 0
        pq = [(0, s)]

        while pq:
            d, u = heappop(pq)
            if u == t: break
            if d > dist[u]: continue
            for v, w in graph[u]:
                if d + w < dist[v]:
                    dist[v] = d + w
                    prev[v] = u
                    heappush(pq, (dist[v], v))

