from collections import deque

def solve(grid, start, goal):
    if (
        start in ((row, col) for row, line in enumerate(grid) for col, cell in enumerate(line) if cell == "#")
        or start == goal
        or abs(start[0] - goal[0]) + abs(start[1] - goal[1]) < 1
    ):
        return [start] if start == goal and grid[start[0]][start[1]] == "." else []

    rows, cols = (len(grid), len(grid[0]))
    queue = deque([start])
    visited = set([start])
    directions = {1: (0, -1), 2: (0, 1), 3: (-1, 0), 4: (1, 0)}

    while queue:
        (row, col), path = queue.popleft(), [start]

