from typing import List, Tuple

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    def is_valid(row: int, col: int) -> bool:
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def dfs(current: Tuple[int, int], visited: set, path: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
        path.append(current)
        if current == goal:
            return path
        visited.add(current)
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            row, col = current[0] + dr, current[1] + dc
            if is_valid(row, col) and (row, col) not in visited:
                result = dfs((row, col), visited.copy(), path.copy())
                if result:
                    return result
        visited.remove(current)
        path.pop()
        return []

    if grid[start[0]][start[1]] == '#':
        return []
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    return dfs(start, set(), []) if is_valid(start[0], start[1]) else []

