def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    max_rows, max_cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = [([start], False)]

    def valid(i, j):
        return 0 <= i < max_rows and 0 <= j < max_cols and grid[i][j] == '.'

    def dfs(stack):
        nonlocal queue
        path, _, visited = stack
        i, j = path[-1]

        if (i, j) == goal:
            return path + [goal]

        for di, dj in directions:
            new_i, new_j = i + di, j + dj

            if valid(new_i, new_j) and not visited.get((new_i, new_j)):
                queue.append(([path, new_i, new_j], False))
                visited[(new_i, new_j)] = True

        return dfs(stack)

    while queue:
        _, pop_visited = queue.pop(0)
        visited = {} if pop_visited else queue[-1][0][-1].visited
        visited[(queue[-1][0][-1][0], queue[-1][0][-1][1])] = True

        if queue:
            while queue and not queue[0][1]:
                queue.pop(0)

            path = dfs(queue[0])
            if path:
                return path

    return []

