def solve(grid, start, goal):
    N, M = len(grid), len(grid[0])

    def valid(r, c):
        return 0 <= r < N and 0 <= c < M and grid[r][c] == '.'

    def dfs(cell, path):
        if cell == goal:
            return [path + [cell]]

        if not valid(cell[0] - 1, cell[1]) or any(dfs((cell[0] - 1, cell[1]), path + [cell]) for _ in range(4)):
            return []

        if not valid(cell[0], cell[1] - 1) or any(dfs((cell[0], cell[1] - 1), path + [cell]) for _ in range(4)):
            return []

        if not valid(cell[0] + 1, cell[1]) or any(dfs((cell[0] + 1, cell[1]), path + [cell]) for _ in range(4)):
            return []

        if not valid(cell[0], cell[1] + 1) or any(dfs((cell[0], cell[1] + 1), path + [cell]) for _ in range(4)):
            return []

        path.append(cell)
        paths = dfs((cell[0] - 1, cell[1]), path)
        if paths:
            return paths

        paths = dfs((cell[0], cell[1] - 1), path)
        if paths:
            return paths

        paths = dfs((cell[0] + 1, cell[1]), path)
        if paths:
            return paths

        paths = dfs((cell[0], cell[1] + 1), path)
        if paths:
            return paths

        return []

    if start == goal and valid(start[0], start[1]):
        return [start]

    return dfs(start, [])

