def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def valid(point):
        return 0 <= point[0] < rows and 0 <= point[1] < cols and grid[point[0]][point[1]] == '.'

    visited = {(start, True), (start, False)}

    queue = deque([(start, [start], True)])

    while queue:
        (point, current_path, reached_goal), *queue = queue

        if grid[point[0]][point[1]] == ' ':
            grid[point[0]][point[1]] = '.'

        if reached_goal and point == goal:
            return current_path + [point]

        for direction in directions:
            new_point = (point[0] + direction[0], point[1] + direction[1])

            if valid(new_point) and (new_point, reached_goal) not in visited:
                visited.add((new_point, reached_goal))
                queue.append(((new_point, current_path + [new_point], reached_goal or new_point == goal)))

                if not reached_goal and new_point == goal:
                    return current_path + [new_point]

