def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    walls = set((r, c) for r in range(rows) for c in range(cols) if grid[r][c] == '#')
    if start in walls or goal in walls:
        return []

    free_neighbors = lambda r, c: [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]
    valid_moves = lambda r, c: [(nr, nc) for nr, nc in free_neighbors(r, c) if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in walls]

    def bfs(start, goal):
        queue = deque([(start, [start])])
        visited = set([start])
        while queue:
            (r, c), path = queue.popleft()
            if (r, c) == goal:
                return path
            for nr, nc in valid_moves(r, c):
                if (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append(((nr, nc), path + [(nr, nc)]))

