       goal in [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == '#']:
        return []

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    start_region = list()
    for r, c in [(start[0] + i * 2, start[1] + j * 2) for i in range(-1, 2) for j in range(-1, 2)]:
        if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.':
            start_region.append((r, c))

    goal_region = list()
    for r, c in [(goal[0] + i * 2, goal[1] + j * 2) for i in range(-1, 2) for j in range(-1, 2)]:
        if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.':
            goal_region.append((r, c))

    def bfs(start, goal):
        queue = deque([(start, False)])
        visited = set()
        while queue:
            (node, back) = queue.popleft()
            if node == goal:
