from collections import deque

def solve(grid, start, goal):
    if not grid or start[0] < 0 or start[0] >= len(grid) or start[1] < 0 or start[1] >= len(grid[0]) or grid[start[0]][start[1]] == '#':
        return []
    if start == goal:
        return [start]

    visited = set([start])
    queue = deque([(start, [start])])

    while queue:
        (node, path) = queue.popleft()

        # find neighbour in BFS graph
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            x, y = node[0] + dx, node[1] + dy

            # find if neighbour is within the grid and not a wall
            if 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '.' and (x, y) not in visited:
                # perform the minimum handshake of BFS
                queue.append(((x, y), path + [(x, y)]))
                visited.add((x, y))

            # check if current node is its own goal and is free
            if node == goal and grid[node[0]][node[1]] == '.':
                return path

    return []

