from typing import List, Tuple

def is_valid(grid: List[str], r: int, c: int) -> bool:
    row_length = len(grid[0])
    return 0 <= r < len(grid) and 0 <= c < row_length and grid[r][c] != '#'

def adjacents(grid: List[str], r: int, c: int) -> List[Tuple[int, int]]:
    neighbors = [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]
    return [(r, c) for r, c in neighbors if is_valid(grid, r, c)]

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    max_depth = max(len(grid), len(grid[0])) + 2
    result = []
    for depth in range(1, max_depth):
        result_update = dfs(grid, start, goal, depth)
        if result_update: 
            return result_update
        result = result_update
    return result

def dfs(grid: List[str], current: Tuple[int, int], goal: Tuple[int, int], max_depth: int) -> List[Tuple[int, int]]:
    if max_depth <= 0: 
        return []
    if current == goal:
        return [current]
    visited = set([current])
    stack = [(current, [current])]
    while stack:
        (node, path) = stack.pop()
        for adjacent in adjacents(grid, *node):
            if adjacent not in visited:
                visited.add(adjacent)
                new_path = path + [adjacent]
                if adjacent == goal:
                    return new_path
                stack.append((adjacent, new_path))
    return []

