def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])
    end_depth = min(rows, cols) * 2
    visited = [[False for _ in range(cols)] for _ in range(rows)]

    for row in range(rows):
        for col in range(cols):
            if grid[row][col] == '#':
                grid[row] = grid[row][:col+1] + '.' + grid[row][col+1:]
                grid[row] = grid[row][:col] + '.' + grid[row][col+1:]

    def is_valid_move(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.'

    def dfs(row, col, depth, path):
        if (row, col) == goal:
            return path + [(row, col)]
        if depth == 0 or not is_valid_move(row, col):
            return None
        visited[row][col] = True
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_row, new_col = row + dr, col + dc
            new_path = dfs(new_row, new_col, depth - 1, path + [(row, col)])
            if new_path is not None:
                return new_path
        return None

    def iddfs():
        path = dfs(start[0], start[1], end_depth, [])
        for row in range(rows):
            for col in range(cols):
                if path is None:
                    return []
                if visited[row][col]:
                    path = dfs(start[0], start[1], end_depth - 1, [])
        return path

    return iddfs()

