def heuristic(a, b):
    """Manhattan distance heuristic."""
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def solve(grid, start, goal):
    """Iterative Deepening Depth-First Search.

    Args:
        grid (list): A 2D list of cells.
        start (tuple): Starting position (0-based indices).
        goal (tuple): Goal position (0-based indices).

    Returns:
        list: A list of (row, col) tuples representing the shortest path.
    """

    def dfs(grid, depth, start, goal):
        """Depth-First Search."""
        if depth == 0:
            return []
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            x, y = start[0] + dx, start[1] + dy
            if (0 <= x < len(grid) and 0 <= y < len(grid[0]) and
                    x != goal[0] or y != goal[1] and
                    grid[x][y] != '#' and (start == goal or x != start[0] or y != start[1])):
                path = [(x, y)] + dfs(grid, depth - 1, (x, y), goal)
                if path: return path
        return None

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]
    for depth in range(1, len(grid) + len(grid[0])):
        path = dfs(grid, depth, start, goal)
        if path:
            return path
    return [] if not any(cell == '.' for row in grid for cell in row) else None

def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    def is_valid(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] != '#'

    def neighbors(row, col):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            r, c = row + dr, col + dc
            if is_valid(r, c):
                yield (r, c)

    stack = [(start, [start])]
    while stack:
        (node, path) = stack.pop()
        if node == goal:
            return path
        for neighbor in neighbors(node[0], node[1]):
            if neighbor not in path:
                stack.append((neighbor, path + [neighbor]))

    return []

def iterative_deepening_dfs(grid, start, goal, max_depth=None):
    if max_depth is None:
        max_depth = len(grid) + len(grid[0])

    for depth in range(1, max_depth + 1):
        result = dfs(grid, start, goal, depth)
        if result:
            return result

    return []

def dfs(grid, start, goal, max_depth):
    if max_depth == 0 or (start == goal and (grid[start[0]][start[1]] == '.' or start == goal)):
        return [start] if start == goal and (grid[start[0]][start[1]] == '.' or start == goal) else []

    def is_valid(row, col, depth):
        return depth >= 1 and is_valid(row, col)

    def neighbors(row, col, depth):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            r, c = row + dr, col + dc
            if (depth >= 1 and is_valid(r, c, depth - 1)) and grid[r][c] != '#':
                yield (r, c)

    def ddfs(node, path, depth):
        if node == goal:
            return path + [node]
        for neighbor in neighbors(node[0], node[1], depth - 1):
