    """Get the neighbours of a cell."""
    neighbours = []
    for r, c in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        new_row, new_col = row + r, col + c
        if is_valid(grid, new_row, new_col):
            neighbours.append((new_row, new_col))
    return neighbours

def solve(grid, start, goal, max_depth=float('inf')):
    """Find a path between the start and goal cells using iterative deepening DFS."""
    stack = [(start, [start])]
    visited = set()
    while stack:
        (cell, path), depth = stack.pop()
        if cell == goal:
            return path
        if cell in visited or depth >= max_depth:
            continue
        visited.add(cell)
        for neighbour in get_neighbours(grid, *cell):
            stack.append(((neighbour, path + [neighbour]), depth + 1))
        max_depth -= 1
        if max_depth == 0:
            return []
    return []

