def solve(grid, start, goal):
    def heuristic(cell):
        return abs(cell[0] - goal[0]) + abs(cell[1] - goal[1])

    def in_grid(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0])

    def is_free(row, col):
        return in_grid(row, col) and grid[row][col] == '.'

    def neighbours(cell):
        return [(cell[0] - 1, cell[1]), (cell[0] + 1, cell[1]), 
                (cell[0], cell[1] - 1), (cell[0], cell[1] + 1)]

    def path_distance(path):
        total = 0
        for i in range(len(path) - 1):
            total += 1
        return total

    open_set = [(start, [start])]
    closed_set = set()

    while open_set:
        _, path = min(open_set, key=lambda x: (path_distance(x[1]), heuristic(x[0])))
        open_set.remove((_, path))
        if path[-1] == goal:
            return path
        cell = path[-1]
        closed_set.add(cell)
        for neighbour in neighbours(cell):
            if neighbour in closed_set:
                continue
            if not is_free(neighbour[0], neighbour[1]):
                continue
            new_path = path + [neighbour]
            open_set.append((neighbour, new_path))

    return []

