def manhattan_distance(cell, goal):
    """Heuristic function for A* search"""
    return abs(cell[0] - goal[0]) + abs(cell[1] - goal[1])

def is_valid(grid, row, col):
    """Check if a move is within the grid and not a wall"""
    return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

def neighbors(grid, cell):
    """Generate all 4 orthogonal neighbours of a cell"""
    neighbours = []
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        r, c = cell[0] + dr, cell[1] + dc
        if is_valid(grid, r, c):
            neighbours.append((r, c))
    return neighbours

def solve(grid, start, goal):
    """Find a path between two cells using A* search"""
    if start == goal or grid[start[0]][start[1]] == '#':
        return [start]

    if grid[goal[0]][goal[1]] == '#':
        return []

    open_set = [(start, [start])]
    closed_set = set()

    while open_set:
        _, path = min(open_set)
        cell = path[-1]
        open_set.remove((cell, path))

        if cell == goal:
            return path

        closed_set.add(cell)

        for neighbor in neighbors(grid, cell):
            if neighbor in closed_set:
                continue

            new_path = path + [neighbor]
            open_set.append((neighbor, new_path))

    return []

