from collections import deque

def solve(grid, start, goal):
    if start == goal and grid[start[0]][start[1]] != '#':
        return [start]

    rows, cols = len(grid), len(grid[0])
    walls = set((i, j) for i, row in enumerate(grid) for j, cell in enumerate(row) if cell == '#')
    visited = set()
    queue = deque([start])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
        x, y = queue.popleft()

        if (x, y) == goal:
            path = [(x, y)]
            while (x, y) != start:
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if (nx, ny) in path:
                        path.insert(0, (nx, ny))
                        x, y = nx, ny
            return path

        if (x, y) in visited:
            continue

        visited.add((x, y))

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if (0 <= nx < rows and 0 <= ny < cols and
                grid[nx][ny] == '.' and (nx, ny) not in visited and (nx, ny) not in walls):
                queue.append((nx, ny))

    return []

