    while open_set:
        _, f_score = min(open_set, key=lambda pos: g_score.get(pos, float('inf')) + heuristic(goal, pos))
        current = [p for p, f in open_set if (f_score, f) == (g_score.get(p, float('inf')) + heuristic(goal, p))][0]
        open_set.remove((current, f_score))
        if current == goal:
            path = [current]
            while came_from[current] is not None:
                current = came_from[current]
                path.insert(0, current)
            return path
        for neighbor in neighbors(grid, current):
            tentative_g_score = g_score[current] + 1
            if neighbor not in g_score or tentative_g_score < g_score[neighbor]:
                g_score[neighbor] = tentative_g_score
                priority = tentative_g_score + heuristic(goal, neighbor)
                open_set.append((neighbor, priority))
                came_from[neighbor] = current
    return []
