    prec = {}
    for row in range(len(grid)):
        for col in range(len(grid[0])):
            prec[row, col] = None

    # The cost of getting to each node.
    cost_so_far = {start: 0}

    # Nodes to be processed.
    nodes = [start]

    while nodes:
