from heapq import heappop, heappush

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    grid_info = [[float('inf') for _ in range(cols)] for _ in range(rows)]
    parent = [[None for _ in range(cols)] for _ in range(rows)]
    grid_info[start[0]][start[1]] = 1

    queue = [(1, start)]

    while queue:
        cost, (x, y) = heappop(queue)

        if (x, y) == goal:
            path = []
            while (x, y) is not None:
                path.append((x, y))
                x, y = parent[x][y]
            return path[::-1]

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != '#' and cost == 1:
