def successor(cell, grid):
    """Generate all neighbours of a cell"""
    neighbours = []
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        r, c = cell[0] + dr, cell[1] + dc
        if (0 <= r < len(grid)) and (0 <= c < len(grid[0])) and (grid[r][c] != '#'):
            neighbours.append((r, c))
    return neighbours

def heuristic(cell, goal):
    """Manhattan distance heuristic"""
    return abs(cell[0] - goal[0]) + abs(cell[1] - goal[1])

def solve(grid, start, goal):
    """Find a path between two cells using unit-weight Dijkstra"""
    if start == goal or grid[start[0]][start[1]] == '#':
        return [start]
    open_set = [(0, start)]
    came_from = {}
    cost_so_far = {start: 0}
    while open_set:
        _, current = min(open_set)
        open_set.remove((cost_so_far[current], current))
        if current == goal:
            path = []
            while current in came_from:
                path.append(current)
                current = came_from[current]
            path.append(start)
            path.reverse()
            return path
        for neighbour in successor(current, grid):
            new_cost = cost_so_far[current] + 1
            if neighbour not in cost_so_far or new_cost < cost_so_far[neighbour]:
                cost_so_far[neighbour] = new_cost
                priority = new_cost + heuristic(neighbour, goal)
                open_set.append((priority, neighbour))
                came_from[neighbour] = current
    return []
