            for u_, w in adj[v]:
                if distance[u_] > distance[v] + w:
                    distance[u_] = distance[v] + w
                    heapq.heappush(pq, (distance[u_], u_))
        return distance

    # Build adjacency list representation of the graph
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Run Dijkstra's algorithm from source to node t
    distance = relax(s, adj)
    if distance[t] < sys.maxsize:
        return distance[t]
    else:
        return -1

