import heapq

def solve(grid, start, goal):
    def valid(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] != '#'

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def astar(start, goal):
        open_list = [(0, start)]
        came_from = {}
        cost_so_far = {start: 0}
        heapq.heapify(open_list)

        while open_list:
            _, current = heapq.heappop(open_list)
            if current == goal:
                break
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                x, y = current[0] + dx, current[1] + dy
                if valid(x, y) and (x, y) not in cost_so_far or cost_so_far[current] + 1 < cost_so_far.get((x, y), float('inf')):
                    cost_so_far[(x, y)] = cost_so_far[current] + 1
                    priority = cost_so_far[(x, y)] + heuristic((x, y), goal)
                    heapq.heappush(open_list, (priority, (x, y)))
                    came_from[(x, y)] = current

        if goal not in cost_so_far:
            return []
        current = goal
        path = []
        while current != start:
            path.append(current)
            current = came_from[current]
        path.append(start)
        path.reverse()
        return path

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    for x, y in start + goal:
        if not valid(x, y):
            return []
    return astar(start, goal)

def test():
    assert solve(['.....', '.....', '.....'], (0, 0), (2, 2)) == [(0, 0), (1, 0), (2, 0), (2, 1), (2, 2)]
    assert solve(['.....', '.....', '..##'], (0, 0), (2, 1)) == []
    assert solve(['...#', '.....', '.....'], (0, 0), (2, 2)) == []
    assert solve(['.....', '.....', '.....'], (0, 0), (0, 0)) == [(0, 0)]
    print("All tests passed.")

test()

