def solve(grid, start, goal):
    """Finds a path between two cells of a grid using unit-weight Dijkstra."""

    def is_valid(cell):
        """Checks if a cell is within the grid boundaries and is a free cell."""
        return 0 <= cell[0] < len(grid) and 0 <= cell[1] < len(grid[0]) and grid[cell[0]][cell[1]] != '#'

    if start == goal or not is_valid(start) or not is_valid(goal):
        return [start] if start == goal and is_valid(start) else []

    rows, cols = len(grid), len(grid[0])
    distances = [[float('inf')] * cols for _ in range(rows)]
    previous = [[None] * cols for _ in range(rows)]
    set_dist = {elem[:] for elem in distances}

    distances[start[0]][start[1]] = 0

    while set_dist:
        curr_cell = min((distances[i][j] * (rows + cols) + i for i in range(rows) for j in range(cols)), key=lambda x: (x % (rows + cols)) if x != float('inf') else float('inf'))
        curr_dist, curr_row, curr_col = curr_cell % (rows + cols), curr_cell // (rows + cols), curr_cell % (rows + cols)

        if (curr_dist, curr_row, curr_col) == (float('inf'), goal[0], goal[1]):
            break
        if (curr_dist, curr_row, curr_col) == (float('inf'), start[0], start[1]):
            return []

        set_dist.discard(distances[curr_row][curr_col] * (rows + cols) + curr_row)

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            next_cell = (curr_row + dx, curr_col + dy)
            if is_valid(next_cell) and distances[next_cell[0]][next_cell[1]] > distances[curr_row][curr_col] + 1:
                distances[next_cell[0]][next_cell[1]] = distances[curr_row][curr_col] + 1
                previous[next_cell[0]][next_cell[1]] = (curr_row, curr_col)

    if distances[goal[0]][goal[1]] == float('inf'):
        return []

    path = [(goal[0], goal[1])]
    while path[-1] != start:
        path.append(previous[path[-1][0]][path[-1][1]])

    return path[::-1]

