def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])

    def is_valid_move(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def get_neighbours(cell):
        r, c = cell
        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid_move(nr, nc):
                yield (nr, nc)

    def binary_heap_insert(heap, element):
        heap.append(element)
        idx = len(heap) - 1
        parent_idx = (idx - 1) // 2
        while idx > 0 and heap[parent_idx][0] > element[0]:
            heap[parent_idx], heap[idx] = heap[idx], heap[parent_idx]
            idx = parent_idx
            parent_idx = (idx - 1) // 2

    def binary_heap_extract_min(heap):
        if len(heap) == 0:
            return None
        if len(heap) == 1:
            return heap.pop()
        min_element = heap[0]
        heap[0] = heap.pop()
        idx = 0
        while True:
            left Child_idx = 2 * idx + 1
            right_child_idx = 2 * idx + 2
            smallest = idx
            if left_child_idx < len(heap) and heap[left_child_idx][0] < heap[smallest][0]:
                smallest = left_child_idx
            if right_child_idx < len(heap) and heap[right_child_idx][0] < heap[smallest][0]:
                smallest = right_child_idx
            if smallest == idx:
                break
            heap[idx], heap[smallest] = heap[smallest], heap[idx]
            idx = smallest
        return min_element

    open_set = [(0, start)]
    g_scores = {start: 0}
    f_scores = {start: heuristic(start, goal)}
    came_from = {}

    while open_set:
        current = binary_heap_extract_min(open_set)
        path = reconstruct_path(came_from, current)
        if current == goal:
            return path

        for neighbour in get_neighbours(current):
            tentative_g_score = g_scores[current] + 1
            if neighbour not in g_scores or tentative_g_score < g_scores[neighbour]:
                came_from[neighbour] = current
                g_scores[neighbour] = tentative_g_score
                f_scores[neighbour] = tentative_g_score + heuristic(neighbour, goal)
                binary_heap_insert(open_set, (f_scores[neighbour], neighbour))

    return []

def heuristic(cell_a, cell_b):
    return abs(cell_a[0] - cell_b[0]) + abs(cell_a[1] - cell_b[1])

def reconstruct_path(came_from, current):
    total_path = [current]
    while current in came_from:
        current = came_from[current]
        total_path.insert(0, current)
