from typing import List, Tuple

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(row: int, col: int) -> bool:
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] != '#'

    def get_neighbours(row: int, col: int) -> List[Tuple[int, int]]:
        neighbours = []
        for dr, dc in directions:
            r, c = row + dr, col + dc
            if is_valid(r, c):
                neighbours.append((r, c))
        return neighbours

    def get_cost(row: int, col: int) -> int:
        return 1 if grid[row][col] != '.' else 0

    def update_frontier(frontier: List[Tuple[int, int]], cost: int, row: int, col: int) -> None:
        for fr, fc, priority in frontier[:]:
            if (fr, fc) == (row, col):
                frontier[frontier.index((fr, fc, priority))] = (row, col, cost)
                return
        frontier.append((row, col, cost))
        frontier.sort(key=lambda x: x[2])

    def reconstruct_path(
        came_from: List[List[Tuple[int, int]]], current: Tuple[int, int]
    ) -> List[Tuple[int, int]]:
        path = []
        while current in [pair for sublist in came_from for pair in sublist]:
            path.append(current)
            current = came_from[[pair for sublist in came_from for pair in sublist].index(current)][0]
        path.append(start)
        path.reverse()
        return path

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    if grid[start[0]][start[1]] == '#':
        return []

    frontier = [(start[0], start[1], 0)]
    came_from = [[] for _ in range(rows)]
    cost_so_far = {(start[0], start[1]): 0}

    while frontier:
        current = frontier.pop(0)
        if current == goal:
            return reconstruct_path(came_from, current)

        for neighbour in get_neighbours(*current):
            new_cost = cost_so_far[current] + get_cost(*neighbour)
            if neighbour not in cost_so_far or new_cost < cost_so_far[neighbour]:
                cost_so_far[neighbour] = new_cost
                came_from[neighbour[0]][neighbour[1]] = current
                update_frontier(frontier, new_cost, neighbour[0], neighbour[1])

    return []

