        if visited[u]:
            continue

        visited[u] = True
        for v, weight in edges:
            if v == u:
                continue
            if distance[u] + weight < distance[v]:
                distance[v] = distance[u] + weight
                if not visited[v]:
                    queue.append(v)

    return distance[t] if distance[t] != float('inf') else -1

def negate_edge(edge):
    return (edge[1], edge[0], -edge[2])
