import heapq

def binary_heap_delayed():
    def heapify_delayed(a, n, k, heapify_key):
        for i in range(k, 0, -1):
            sift_up(a, i, n, k, heapify_key)

    def sift_up(a, i, n, k, heapify_key):
        parent = (i - 1) // k
        if i < k:
            parent = 0
        while i > 0 and heapify_key(a[parent * k + k], a[i]) > 0:
            a[i], a[parent * k + k] = a[parent * k + k], a[i]
            i = parent
            parent = (i - 1) // k

    def heappush(a, item):
        a.append(item)
        sift_up(a, len(a) - 1, len(a), len(a) // 2, heapify_delayed.heapify_key)

    def heapify_key(node1, node2):
        result = 0
        if node1 is not None and node2 is not None:
            result = node1[0] - node2[0]
        return result

    def heappop(a):
        i = len(a) - 1
        result = a[0]
        a[0] = a[i]
        a.pop()
        sift_down(a, 0, len(a) // 2, heapify_key)
        return result

    def sift_down(a, start, k, heapify_key):
        i = start
        while True:
            child = 2 * i + 1
            if child >= len(a):
                break
            if child + 1 < len(a) and heapify_key(a[child], a[child + 1]) > 0:
                child += 1
            if heapify_key(a[i], a[child]) > 0:
                a[i], a[child] = a[child], a[i]
                i = child
            else:
                break
    heapq.heapify = heappush
    heapq.heappop = heappop
    heapq.heapify_delayed = heapify_delayed

class Graph:
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]

    def add_edge(self, u, v, w):
        self.adj[u].append((v, w))

def solve(n, edges, s, t):
    g = Graph(n)
    for u, v, w in edges:
        g.add_edge(u, v, w)

    def dijkstra():
        dist = [0 if i == s else sys.maxsize for i in range(n)]
        pq = [(0, s)]
        while pq:
            fd = heapq.heappop(pq)
            i = fd[1]
            vi = dist[i]
            if vi < fd[0]:
                continue
            for j, w in g.adj[i]:
                nd = vi + w
                if nd < dist[j]:
                    dist[j] = nd
                    heapq.heappush(pq, (nd, j))
        return dist[t]

    if s == t:
