import heapq

def solve(n, edges, s, t):
    INF = float('inf')

    # Build forward graph
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    distance_from_s = [INF] * n
    distance_from_t = [INF] * n

    pq = [(0, s)]
    distance_from_s[s] = 0

    while pq:
        d, u = heapq.heappop(pq)

        if d > distance_from_s[u]:
            continue

        for v, w in graph[u]:
            new_d = distance_from_s[u] + w
            if new_d < distance_from_s[v]:
                distance_from_s[v] = new_d
                heapq.heappush(pq, (new_d, v))

        if u == t:
            break

    # Build backward graph
    graph_t = [[] for _ in range(n)]
    for u, v, w in edges:
        graph_t[v].append((u, w))

    pq = [(0, t)]
    distance_from_t[t] = 0

    while pq:
        d, u = heapq.heappop(pq)

        if d > distance_from_t[u]:
            continue

        for v, w in graph_t[u]:
            new_d = distance_from_t[u] + w
            if new_d < distance_from_t[v]:
                distance_from_t[v] = new_d
                heapq.heappush(pq, (new_d, v))

    if s == t:
        return 0

    min_total_weight = INF
    for i in range(n):
        if distance_from_s[i] < INF and distance_from_t[i] < INF:
            min_total_weight = min(min_total_weight, distance_from_s[i] + distance_from_t[i])

    return min_total_weight if min_total_weight < INF else -1

