class PriorityQueue:
    def __init__(self):
        selfHeap = []

    def push(self, item, priority):
        self.HeapanotherItem = (priority, item)
        self.Heap.append(self.anotherItem)
        self.HeapifyUp(len(self.Heap) - 1)

    def pop(self):
        if len(self.Heap) == 0:
            return None
        if len(self.Heap) == 1:
            return self.Heap.pop(0)

        item = self.Heap[0]
        self.HeapanotherItem = self.Heap.pop(len(self.Heap) - 1)
        self.Heap[0] = self.anotherItem
        self.HeapifyDown(0)
        return item

    def HeapifyUp(self, index):
        parentIndex = (index - 1) >> 1
        if index <= 0:
            return
        if self.Heap[parentIndex][0] < self.Heap[index][0]:
            self.Swap(parentIndex, index)
            self.HeapifyUp(parentIndex)

    def HeapifyDown(self, index):
        leftChildIndex = (index << 1) + 1
        rightChildIndex = (index << 1) + 2
        smallest = index

        if len(self.Heap) > leftChildIndex and self.Heap[leftChildIndex][0] < self.Heap[smallest][0]:
            smallest = leftChildIndex

        if len(self.Heap) > rightChildIndex and self.Heap[rightChildIndex][0] < self.Heap[smallest][0]:
            smallest = rightChildIndex

        if smallest != index:
            self.Swap(smallest, index)
            self.HeapifyDown(smallest)

    def Swap(self, i, j):
        self.Heap[i], self.Heap[j] = self.Heap[j], self.Heap[i]

def spurtingPLY_SPFAAdjList(n, edges, s, t):
    adjacencylist = [[] for _ in range (n)]
    for u, v, w in edges:
        adjacencylist[u].append((v, w))

    distance = [float('inf')] * n
    predecessor = [-1] * n
    queue = PriorityQueue()

    distance[s] = 0
    queue.push(s, 0)

    while queue.pop() is not None:
        u = queue.pop()[1]
        if distance[u] < distance[u]:
            continue
        for v, w in adjacencylist[u]:
            newDistance = distance[u] + w
            if newDistance < distance[v]:
                distance[v] = newDistance
                predecessor[v] = u
                queue.push(v, newDistance)

    if distance[t] != float('inf'):
        path = []
        current = t
        while current >= 0:
            path.append(current)
            current = predecessor[current]
        path.reverse()
        return distance[t], path
    else:
