import heapq

def getOppositeNode(node, n):
    return node ^ (1 << n.bit_length() - 1)

class Graph:
    def __init__(self, n):
        self.n = n
        self.distances = [[1 << 30 for _ in range(n)] for _ in range(1 << n)]
        for i in range(n):
            self.distances[1 << i][i] = 0

    def addEdge(self, u, v, w):
        self.distances[1 << u][v] = min(self.distances[1 << u][v], w)
        self.distances[1 << v][u] = min(self.distances[1 << u][u], w + 1 << n.bit_length() - 1)

    def getDist(self, mask, node):
        return self.distances[mask][node]

    def updatePoint(self, mask, node, newMask, minDist):
        self.distances[newMask][node] = min(self.distances[newMask][node], minDist)

    def bidirectionalDijkstra(self, s, t):
        pq = []
        visited = [False] * (1 << self.n)
        visited[1 << s] = True
        heapq.heappush(pq, (0, 1 << s, s))
        while pq:
            d, mask, node = heapq.heappop(pq)
            if visited.get(getOppositeNode(mask, self.n) & mask, False):
                continue
            if not visited[mask]:
                visited[mask] = True

            if getOppositeNode(mask, self.n) & mask:
                for i in range(self.n):
                    if i != node and getOppositeNode(mask, self.n) & (1 << i):
                        self.updatePoint(mask, i, mask, self.distances[mask][i])
                        heapq.heappush(pq, (self.distances[mask][i], mask, i))

            if node == t:
                return d

            for neighbor, weight in enumerate(self.distances[mask]):
                if not visited[getOppositeNode(mask, self.n) | (1 << neighbor)]:
                    prevDist = self.getDist(getOppositeNode(mask, self.n) | (1 << neighbor), neighbor)
                    if d + weight < prevDist:
                        self.updatePoint(getOppositeNode(mask, self.n) | (1 << neighbor), node, getOppositeNode(mask, self.n) | (1 << neighbor), d + weight)
                        heapq.heappush(pq, (d + weight, getOppositeNode(mask, self.n) | (1 << neighbor), neighbor))

        return -1

def solve(n, edges, s, t):
    g = Graph(n)
    for u, v, w in edges:
        g.addEdge(u, v, w)
    return g.bidirectionalDijkstra(s, t)

