def solve(n, edges, s, t):
    # Create graph adjacency lists
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Dijkstra's algorithm for shortest path from s to all other nodes
    pq = [(0, s)]
    dists = [float('inf')] * n
    dists[s] = 0
    visited = set()
    while pq:
        d, u = heapq.heappop(pq)
        if u in visited:
            continue
        visited.add(u)
        for v, w in graph[u]:
            if d + w < dists[v]:
                dists[v] = d + w
                heapq.heappush(pq, (dists[v], v))

    # Dijkstra's algorithm for shortest path from t to all other nodes in reverse graph
    rgraph = [[] for _ in range(n)]
    for u, v, w in edges:
        rgraph[v].append((u, w))
    rpq = [(0, t)]
    rdist = [float('inf')] * n
    rdist[t] = 0
    rvisited = set()
    while rpq:
        d, u = heapq.heappop(rpq)
        if u in rvisited:
