        for v, w in rgraph[u]:
            if d + w < rdist[v]:
                rdist[v] = d + w
                heapq.heappush(rpq, (rdist[v], v))

    # Check if t can be reached from s through the shortest path found by either of the Dijkstra's algorithms
    return 0 if s == t else -1 if dists[t] == float('inf') or rdist[s] == float('inf') else min(dists[t], rdist[s])

