                    heapq.heappush(pq, (distance[v], v))
        return -1

    return dijkstra(s, t)

def bidirectional_dijkstra(n, edges, s, t):
    left_distance = float('inf')
    right_distance = 0
    leftQ = [(0, s)]  # (dist, node)
    rightQ = [(0, t)]
    nodes = [set() for _ in range(n)]

    s_left_dist = 0
    t_right_dist = 0

    while leftQ and rightQ:
        while leftQ and nodes[s].issuperset(map(lambda x: x[1], leftQ)):
            _, node = heapq.heappop(leftQ)
            nodes[s].add(node)
        while rightQ and nodes[t].issuperset(map(lambda x: x[1], rightQ)):
            _, node = heapq.heappop(rightQ)
            nodes[t].add(node)

        if leftQ:
            dist, node = leftQ[0]
            s_left_dist = dist
        if rightQ:
            dist, node = rightQ[0]
            t_right_dist = dist

        if s == t:
            return 0
        if s_left_dist + t_right_dist >= left_distance:
            break

        if leftQ:
            _, node = heapq.heappop(leftQ)
            for v, w in (graph := edges_to_graph(edges))[node]:
                if v not in nodes[s]:
                    left_distance = min(left_distance, s_left_dist + w)
                    heapq.heappush(leftQ, (s_left_dist + w, v))
                    nodes[s].add(v)

        if rightQ:
            _, node = heapq.heappop(rightQ)
            for v, w in graph[node]:
                if v not in nodes[t]:
                    right_distance = min(right_distance, t_right_dist + w)
                    heapq.heappush(rightQ, (t_right_dist + w, v))
                    nodes[t].add(v)

    return dijkstra(s, t)

def edges_to_graph(edges):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, -w)) #handle undirected edge
    return graph

