import heapq
from collections import defaultdict

def solve(n, edges, s, t):
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    queue = [(0, s, None)]
    distances = {i: float('inf') for i in range(n)}
    predecessors = {i: None for i in range(n)}
    distances[s] = 0

    while queue:
        (dist, current_node,_,) = heapq.heappop(queue)

        for neighbor, neighbor_dist in graph[current_node]:
            new_dist = dist + neighbor_dist
            if new_dist < distances[neighbor]:
                distances[neighbor] = new_dist
                predecessors[neighbor] = current_node
                heapq.heappush(queue, (new_dist, neighbor, None))

    if distances[t] == float('inf'):
        return -1
    elif s == t:
        return 0
    else:
        path = []
        current_node = t
        while current_node is not None:
            path.append(current_node)
            current_node = predecessors[current_node]
        path.reverse()
        return sum(graph[path[i]][0][1] for i in range(len(path)-1))

# Allow solve function to handle self-loops and parallel edges.
