    """Add single edge to the directed graph represented by list of edges."""
    edges.append((u,v, w))

def build_graph(n, edges):
    """Build directed weighted graph as a dictionary of adjacency lists."""
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
    return graph

