import heapq

def solve(n, edges, s, t):
    inf = float('inf')
    edges = [[] for _ in range(n)]
    in_weight = [inf] * n
    in_id = [-1] * n
    out_dist = [inf] * n
    out_id = [-1] * n
    out_next = [-1] * n
    out_prev = [0] * n

    for u, v, w in edges:
        if in_weight[v] == inf:
            in_weight[v] = out_dist[u] = w
            in_id[v] = u
            out_id[u] = v
            out_next[u] = v
        else:
            if w < out_dist[u] or (w == out_dist[u] and in_id[v] != u):
                out_dist[u] = w
                out_prev[u] = out_next[u]
                out_next[u] = v
                in_weight[v] = w

    for u in range(n):
        if in_weight[u] == inf or out_dist[u] >= inf:
            continue
        pq = [(in_weight[u], u)]
        dist = [inf] * n
        while pq:
            dial = heapq.heappop(pq)
            if dial[0] >= dist[dial[1]]:
                continue
            for next_v in range(n):
                next_u = out_prev[next_v]
                if out_dist[next_u] + dial[0] < dist[next_v] and next_u != out_next[next_u]:
                    dist[next_v] = out_dist[next_u] + dial[0]
                    if in_id[next_v] != next_u:
                        heapq.heappush(pq, (dist[next_v], next_v))
                    else:
                        heapq.heappush(pq, (dist[next_v], next_v))
        out_dist[u] = dist[t]
        if out_dist[u] >= inf:
            out_dist[u] = -1

    return out_dist[s]

