import heapq

def solve(n, edges, s, t):
    graph directions weights = ({}, {})  # dictionary of adjacency lists and reversed adjacency lists

    for u, v, w in edges:
        graph[u] = graph.get(u, []) + [(v, w)]
        directions[v][u] = w
        weights[w] = weights.get(w, [0, 0]) + [u, v]

    def dijkstra(graph, start, target):
        queue = [(0, start)]  # tuple (distance, node)
        dists = {start: 0}  # dictionary of shortest distances from start

        while queue:
            d, u = heapq.heappop(queue)
            if u == target:
                return d

            if d > dists.get(u, float('inf')):
                continue

            for v, w in graph.get(u, []):
                newd = d + w
                if newd < dists.get(v, float('inf')):
                    dists[v] = newd
                    heapq.heappush(queue, (newd, v))

        return None

    def find_edge(dists, w):
        for u, v in weights.get(w, ()):
            if u in dists and v in dists and dists[u] + w == dists[v]:
                return (u, v)
        return None

    orig_dist = dijkstra(graph, s, t)
    if orig_dist is not None:
        return orig_dist

    unweighted = {s: 0}  # dictionary of nodes representation as paths
    for i in range(n):
        new_unweighted = {}
        for u, dist in unweighted.items():
            for v, w in graph.get(u, []):
                new_dist = dist + w
                if new_dist in weights and find_edge(unweighted, new_dist) is not None:
                    return new_dist
                new_unweighted[v] = new_dist

        unweighted = new_unweighted

    return -1

