import sys
from heapq import heappop, heappush

def solve(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    distance, predecessor = dijkstra(graph, s, sys.maxsize), [-1]*n
    distance_reversed, predecessor_reversed = dijkstra(graph, t, sys.maxsize)

    for i in range(n):
        distance[i], distance_reversed[i] = min(distance[i], distance_reversed[i]), min(distance[i], distance_reversed[i])

    if distance[-1] == sys.maxsize:
        return -1

    queue = [(distance[t] + distance_reversed[t], t)]
    while queue:
        d, i = heappop(queue)
        if i == s:
            path_len = d - distance_reversed[i]
            current = i
            while current != s:
                path_len += graph[predecessor[current]][0][1]
                current = predecessor[current]
            return path_len
        for neibour, weight in graph[i]:
            if distance[i] + weight + distance_reversed[neibour] < distance_reversed[neibour]:
                distance_reversed[neibour] = distance[i] + weight
                heappush(queue, (distance_reversed[neibour], neibour))
                predecessor_reversed[neibour] = i

def dijkstra(graph, start, infinity):
    distance = [infinity] * len(graph)
    distance[start] = 0
    queue = [(0, start)]
    while queue:
        d, i = heappop(queue)
        if d != distance[i]:
            continue
        for neibour, weight in graph[i]:
            new_distance = d + weight
            if new_distance < distance[neibour]:
                distance[neibour] = new_distance
                heappush(queue, (new_distance, neibour))
    return distance

