def solve(n, edges, s, t):
    dist = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0

    for u, v, w in edges:
        dist[u][v] = min(dist[u][v], w)

    for k in range(n):
        for i in range(n):
            if dist[i][k] != float('inf') and dist[k][i] != float('inf'):
                dist[i][k] = min(dist[i][k], dist[i][k] + dist[k][i])

    path = [dist[s][t]]
    while path[-1] > 0 and t != s:
        u, v = None, None
        max_d = -1
        for i in range(n):
            for j in range(n):
                if dist[i][j] > max_d and 0 < dist[i][j] < float('inf'):
                    u, v, max_d = i, j, dist[i][j]
        path.append(max_d)
        dist[u][v] = float('inf')
        t = v

    return path[0] if path[-1] == 0 else -1 if path[-1] > float('inf') else 0
