import heapq

def solve(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    min_dist = [float('inf')] * n
    min_dist[s] = 0
    queue = [(0, s)]

    while queue:
        dist, u = heapq.heappop(queue)
        if u == t:
            return dist
        if dist > min_dist[u]:
            continue
        for v, w in graph[u]:
            new_dist = dist + w
            if new_dist < min_dist[v]:
                min_dist[v] = new_dist
                heapq.heappush(queue, (new_dist, v))

    return -1

