def solve(n, edges, s, t):
    g = defaultdict(dict)
    for u, v, w in edges:
        g[u][v] = w
    pq = [(0, s)]
    seen = {s: 0}
    while pq:
        length, u = heapq.heappop(pq)
        if u == t:
            return length
        if u in seen and length == seen[u]:
            for v, w in g[u].items():
                new_len = length + w
                if v not in seen or new_len < seen[v]:
                    seen[v] = new_len
                    heapq.heappush(pq, (new_len, v))
        else:
            for v, w in g[u].items():
                new_len = length + w
                seen[v] = new_len
                heapq.heappush(pq, (new_len, v))
    return -1

