def solve(n, edges, s, t):
    def in_range(u, v):
        return 0 <= u < n and 0 <= v < n

    distance = [float('inf')] * n
    distance[s] = 0

    queue = [(0, s)]

    while queue:
        d, u = heapq.heappop(queue)

        if u == t:
            return d

        if d > distance[u]:
            continue

        for i in range(len(edges)):
            e = edges[i]
            if in_range(e[0], e[1]) and in_range(e[1], u):
                v, w = e[1], e[2]
                if distance[v] > distance[u] + w:
                    distance[v] = distance[u] + w
                    heapq.heappush(queue, (distance[v], v))

    return -1

