import heapq

def solve(n, edges, s, t):
    def in_range(u, v):
        return 0 <= u < n and 0 <= v < n

    G = [[] for _ in range(n)]
    for u, v, w in edges:
        if in_range(u, v):
            G[u].append((v, w))

    del_k = [0] * n
    Q = [(0, s)]
    while Q:
        d, u = heapq.heappop(Q)
        if u == t:
            return d
        if d != del_k[u]:
            continue
        for v, w in G[u]:
            alt = d + w
            if alt < del_k[v]:
                del_k[v] = alt
                heapq.heappush(Q, (alt, v))

    return -1

