from heapq import heappop, heappush

def solve(n, edges, s, t):
    D, Q = [[float('inf')] * n for _ in range(2)], [(0, s)]
    D[0][s], D[1][s] = 0, 0
    while Q:
        w, u = heappop(Q)
        if w > D[(D[u] + [float('inf')])[1]][u]:
            continue
        for v, c in enumerate(D[0][u]):
            nw = w + c
            if nw < D[0][v]:
                D[0][v], D[1][v] = nw, D[1][v] + 1
                heappush(Q, (nw, v))
    return D[0][t] if D[0][t] != float('inf') else -1

