import heapq
from typing import List, Tuple

def solve(n: int, edges: List[Tuple[int, int, int]], s: int, t: int) -> int:
    INF = float('inf')

    # helper to construct the adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Dial's bucket-queue algorithm
    def dijkstra_bucketqueue(s: int, t: int) -> int:
        dist = [INF] * n
        prev = [None] * n
        dist[s] = 0
        heap = [(0, s)]
        while heap:
            d, u = heapq.heappop(heap)
            if u == t:
                break
            if d > dist[u]:
                continue  # relax an edge that was already relaxed
            for v, w in adj[u]:
                new_dist = dist[u] + w
                if new_dist < dist[v]:
                    dist[v] = new_dist
                    prev[v] = u
                    heapq.heappush(heap, (new_dist, v))
        if dist[t] == INF:
            return -1
        mincost = 0
        u = t
        while u is not None:
            mincost += w
