class Node:
    def __init__(self, id):
        self.id = id
        self.visited = False
        self.prev = None
        self.heap_idx = 0
        self.d = float('inf')

class DialHeap:
    def __init__(self):
        self.size = 0
        self.map = {}

    def insert(self, node):
        self.map[self.size] = node
        node.heap_idx = self.size
        self.size += 1
        self._heapify_up(self.size - 1)

    def get_min(self):
        return self.map[0] if self.size else None

    def extract_min(self):
        if self.size == 0:
            return None
        min_node = self.map[0]
        self.map[0] = self.map[self.size - 1]
        self.map.pop(self.size - 1)
        self.size -= 1
        self.map = {idx: node for idx, node in enumerate(self.map.values())}
        self._heapify_down(0)
        return min_node

    def _heapify_up(self, idx):
        parent_idx = (idx - 1) // 2
        while idx > 0 and self.map[idx].d < self.map[parent_idx].d:
            self.map[idx], self.map[parent_idx] = self.map[parent_idx], self.map[idx]
            idx = parent_idx
            parent_idx = (idx - 1) // 2

    def _heapify_down(self, idx):
        while True:
            child_idx = 2 * idx + 1
            if child_idx >= self.size:
                break
            if child_idx + 1 < self.size and self.map[child_idx + 1].d < self.map[child_idx].d:
                child_idx += 1
            if self.map[idx].d <= self.map[child_idx].d:
