def possible_moves(row, col, grid):
    """Returns valid moves from a cell, not touching walls."""
    moves = []
    for r, c in [(row-1, col), (row+1, col), (row, col-1), (row, col+1)]:
        if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.':
            moves.append((r, c))
    return moves

def solve(grid, start, goal):
    """Finds a path between two cells of a grid."""
    # Check goal and start
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if start in [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == '#'] or goal in [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == '#']:
        return []

    # Create will_try and reached collections
    will_try = [(start, [start])]
    reached = set([start])

    # Loop over will_try
    while will_try:
        curr, path = will_try.pop(0)
        # If we have reached goal, return path
        if curr == goal:
            return path
        # Try all possible moves
        for nxt in possible_moves(*curr, grid):
            if nxt not in reached:
                will_try.append((nxt, path + [nxt]))
                reached.add(nxt)
    # If we end up back in loop, no solution was found
    return []

