    rows, cols = len(grid), len(grid[0])
    directions = [(1, 0),  # right
                  (0, 1),  # down
                  (-1, 0), # left
                  (0, -1)] # up

    def get_neighbours(row, col):
        for dr, dc in directions:
            r, c = row + dr, col + dc
            if 0 <= r < rows and 0 <= c < cols and is_free(grid, r, c):
                yield (r, c)

    def is_free(grid, row, col):
        return grid[row][col] == '.'

    def attempt(row, col):
        if (row, col) == goal:
            return [(row, col)]
        seen = set((row, col))
        stack = [(row, col)]
        path = []
        while stack:
            x, y = stack.pop()
            if (x, y) in path:
                continue
            if (x, y) == goal:
                continue
            if is_free(grid, x, y):
                path.append((x, y))
                for nx, ny in get_neighbours(x, y):
                    if (nx, ny) not in seen:
                        stack.append((nx, ny))
                        seen.add((nx, ny))
        return path

    return attempt(*start) if is_free(grid, *start) else []
