from collections import deque

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    rowsOffset = [-1, 1, 0, 0]
    colsOffset = [0, 0, -1, 1]

    queue = deque([(start, [start])])
    visited = {start}

    while queue:
        (row, col), path = queue.popleft()

        for offset in range(4):
            newRow, newCol = row + rowsOffset[offset], col + colsOffset[offset]

            if (0 <= newRow < rows) and (0 <= newCol < cols) and \
               (grid[newRow][newCol] == '.') and ((newRow, newCol) not in visited) and \
               ((newRow, newCol) not in path or newPathLength(path + [(newRow, newCol)]) > newPathLength(path)):
                if (newRow, newCol) == goal:
                    return path + [(newRow, newCol)]
                queue.append((((newRow, newCol)), path + [(newRow, newCol)]))
                visited.add((newRow, newCol))

    return []

