def in_bounds(grid, row, col):
    return 0 <= row < len(grid) and 0 <= col < len(grid[0])

def is_valid(grid, row, col):
    return in_bounds(grid, row, col) and grid[row][col] != '#'

def neighbors(grid, row, col):
    return [
        (row - 1, col) if is_valid(grid, row - 1, col) else None,
        (row, col + 1) if is_valid(grid, row, col + 1) else None,
        (row + 1, col) if is_valid(grid, row + 1, col) else None,
        (row, col - 1) if is_valid(grid, row, col - 1) else None,
    ]

def solve(grid, start, goal):
    if not is_valid(grid, start[0], start[1]) or not is_valid(grid, goal[0], goal[1]):
        return []

    if start == goal and is_valid(grid, start[0], start[1]):
        return [start]

    frontier = [start]
    came_from = {start: None}

    while frontier:
        current = frontier.pop(0)

        if current == goal:
            path = []
            while current is not None:
                path.append(current)
                current = came_from.get(current)
            return path[::-1]

        for neighbor in neighbors(grid, *current):
            if neighbor not in came_from:
                frontier.append(neighbor)
                came_from[neighbor] = current
    return []

