    rows, cols = len(grid), len(grid[0])
    start, goal = (start[0], start[1]), (goal[0], goal[1])

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    def get_neighbours(cell, visited=None):
        if visited is None:
            visited = set()
        neighbours = []
        r, c = cell
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#' and cell not in visited:
                neighbours.append((nr, nc))
                visited.add(cell)
        return neighbours

    def bidirectional_bfs(start, goal, visited1=None, visited2=None):
        if visited1 is None:
            visited1 = set([start])
            queue1 = [start]
        if visited2 is None:
            visited2 = set([goal])
            queue2 = [goal]
        while True:
            level1 = queue1 if queue1 else queue2
            level2 = queue2 if queue1 else queue1
            for cell1 in level1:
                if cell1 in visited2:
                    return list(((cell1, c) for c in visited1 if c in visited2) | {cell1})
                for cell2 in get_neighbours(cell1, visited1 | visited2):
                    neighbour2 = tuple(b for a, b in zip(cell1, cell2))
                    if neighbour2 not in (visited1 | visited2):
                        queue2.append(neighbour2)
                        visited2.add(neighbour2)
            queue1, queue2 = queue2, queue1

    return bidirectional_bfs(start, goal) if start != goal else [start]

