def solve(grid, start, goal):
    def is_valid(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] != '#'

    def valid_path(path):
        for i in range(1, len(path)):
            if abs(path[i-1][0] - path[i][0]) + abs(path[i-1][1] - path[i][1]) != 1:
                return False
        return all(grid[row][col] == '.' for row, col in path)

    def dfs(row, col, visited, path):
        if (row, col) == goal and valid_path(path + [(row, col)]):
            return path + [(row, col)]
        visited.add((row, col))
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = row + dr, col + dc
            if is_valid(nr, nc) and (nr, nc) not in visited:
                result = dfs(nr, nc, visited, path + [(row, col)])
                if result:
                    return result
        return []

    return dfs(start[0], start[1], set(), [start]) if is_valid(start[0], start[1]) else []

