def solve(grid, start, goal):
    neut = '.'; wall = '#'

    def is_valid(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == neut

    def move(nxt, prv):
        dx = [1, -1, 0, 0]
        dy = [0, 0, 1, -1]
        for i in range(4):
            new_x, new_y = nxt[0] + dx[i], nxt[1] + dy[i]
            if is_valid(new_x, new_y) and (new_x, new_y) not in prv:
                yield new_x, new_y

    def is_goal(x, y, path):
        return path[-1] == (x, y) and (x, y) == goal

    def bfs1(start, goal):
        queue = deque([(start, [start])])
        seen = set([start])
        while queue:
            (node, path) = queue.popleft()
            if is_goal(node[0], node[1], path):
                return path
            for nxt in move(node, path):
                queue.append(((nxt[0], nxt[1]), path + [nxt]))

    def bfs2(goal, start):
        queue = deque([(goal, [goal])])
        seen = set([goal])
        while queue:
            (node, path) = queue.popleft()
            if is_goal(node[0], node[1], path[::-1]):
                return path[::-1]
            for nxt in move(node, path):
                queue.append(((nxt[0], nxt[1]), path + [nxt]))

