from heapq import heappop, heappush

def solve(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    distance = [float('inf')] * n
    distance[s] = 0

    pq = [(0, s)]

    while pq:
        d, u = heappop(pq)
        if d > distance[u]:
            continue
        for v, w in graph[u]:
            new_distance = distance[u] + w
            if new_distance < distance[v]:
                distance[v] = new_distance
                heappush(pq, (new_distance, v))

