from heapq import heappush, heappop

def solve(n, edges, s, t):
    E = [[] for _ in range(n)]
    for u, v, w in edges:
        E[u].append((v, w))
    inf = float('inf')
    dist = [inf] * n
    dist[s] = 0
    prev = [-1] * n
    for _ in range(n):
        changed = False
        pq = [(0, s)]
        while pq:
            d, u = heappop(pq)
            if dist[u] < d:
                continue
            for v, w in E[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    prev[v] = u
                    heappush(pq, (dist[v], v))
                    changed = True
            if not changed:
                break
    return dist[t] if dist[t] < inf else -1

