def solve(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((w, v))

    visited = [0] * n
    min_weight = [float('inf')] * n
    min_weight[s] = 0

    queue = [(0, s)]
    while queue:
        weight, node = heapq.heappop(queue)

        if visited[node] or weight > min_weight[node]:
            continue
        visited[node] = 1

        for cost, neighbor in graph[node]:
            if weight + cost < min_weight[neighbor]:
                min_weight[neighbor] = weight + cost
                heapq.heappush(queue, (min_weight[neighbor], neighbor))

    return min_weight[t] if min_weight[t] != float('inf') else -1

