        n = max(u for u, v, _ in edges) + 1
        p = list(range(n))
        for u, v, w in edges:
            if find(u, p) != find(v, p):
                p[find(v, p)] = find(u, p)
        return p

    tree = build_tree(edges)
    hierarchy = find(s, tree)
    pqueue = [(0, hierarchy, [hierarchy])]
