from collections import deque

def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#':
        raise ValueError("Start is a wall")
    if grid[goal[0]][goal[1]] == '#':
        raise ValueError("Goal is a wall")

    def is_valid(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[row]) and grid[row][col] != '#'

    queue = deque([(start, [start])])
    visited = set([start])
    walls = set((x, y) for i, row in enumerate(grid) for x, y in enumerate((i, j) for j in range(len(row))))

    while queue:
        (row, col), path = queue.popleft()
        if (row, col) == goal:
            return path

        for row_change, col_change in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_row, new_col = row + row_change, col + col_change
            if is_valid(new_row, new_col) and (new_row, new_col) not in visited:
                queue.append(((new_row, new_col), path + [(new_row, new_col)]))
                visited.add((new_row, new_col))

    return []

def links_cells(grid):
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if j + 1 < len(grid[i]) and grid[i][j + 1] == '.':
                grid[i] = grid[i][:j+1] + '#' + grid[i][j+1:]
            if i + 1 < len(grid) and grid[i+1][j] == '.':
                for k in range(len(grid[i])):
                    grid[i+1] = grid[i+1][:j] + '#' + grid[i+1][j+1]
                break
    return grid

def reverse(grid):
    return [row[::-1] for row in grid[::-1]]

def bidirectional_search(grid, start, goal):
    start_grid = links_cells(grid)
    goal_grid = links_cells(reverse(grid))
    start_queue = deque([(start, [start])])
    goal_queue = deque([(goal, [goal])])
    visited = set([start])
    visited_goal = set([goal])
    walls = set((x, y) for i, row in enumerate(start_grid) for x, y in enumerate((i, j) for j in range(len(row))))

    while start_queue and goal_queue:
        (row, col), path = start_queue.popleft()
        if path[-1] in visited_goal:
            return path[::-1]

        for row_change, col_change in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_row, new_col = row + row_change, col + col_change
            if is_valid(new_row, new_col, walls) and (new_row, new_col) not in visited:
                start_queue.append(((new_row, new_col), path + [(new_row, new_col)]))
                visited.add((new_row, new_col))

        if not start_queue:
            start_grid, goal_grid = goal_grid, start_grid
            start_queue, goal_queue = goal_queue, start_queue
            start, goal = goal, start
            visited, visited_goal = visited_goal, visited
            walls = set unzip((x, y) for i, row in enumerate(start_grid) for x, y in enumerate((i, j) for j in range(len(row))))

    return []

