from collections import deque

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    if start == goal:
        return [start]

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    def valid_move(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.'

    def get_valid_neighbors(row, col):
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        return [(row + dr, col + dc) for dr, dc in directions if valid_move(row + dr, col + dc)]

    q = deque([[start]])
    visited = set([start])
    while q:
        path = q.popleft()
        row, col = path[-1]
        if (row, col) == goal:
            return path
        for r, c in get_valid_neighbors(row, col):
            if (r, c) not in visited:
                visited.add((r, c))
                q.append(path + [(r, c)])
    return []

def iterative_deepening(grid, start, goal, max_depth=None):
    rows, cols = len(grid), len(grid[0])
    if start == goal:
        return [start]

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    max_depth = max_depth or (rows + cols - 2) * 2

    def valid_move(row, col, depth):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.' and depth > 0

    def get_valid_neighbors(row, col):
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        return [(row + dr, col + dc) for dr, dc in directions if valid_move(row + dr, col + dc, depth)]

    def dfs(row, col, depth):
        if (row, col) == goal:
            return [(row, col)]
        if depth == 0 or not valid_move(row, col, depth):
            return None
        for r, c in get_valid_neighbors(row, col):
            result = dfs(r, c, depth - 1)
            if result:
                return [(row, col)] + result
        return None

    best_path = None
    for depth in range(max_depth + 1):
        path = dfs(start[0], start[1], depth)
        if path and (best_path is None or len(path) < len(best_path)):
            best_path = path
    return best_path

