import heapq

def solve(n, edges, s, t):
    inf = float('inf')
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = [inf] * n
    dist[s] = 0
    used = [False] * n

    pq = [(0, s)]

    while pq:
        d, u = heapq.heappop(pq)
        if used[u]:
            continue
        used[u] = True
        for v, w in graph[u]:
            if dist[v] > d + w:
                dist[v] = d + w
                heapq.heappush(pq, (dist[v], v))

    return 0 if s == t else dist[t] if dist[t] != inf else -1

def solve_worker(grid, start, goal, came_from, current=()):
    current = ('.', *current)
    if current == start:
        path = []
        while current:
            path.append(current[1:])
            current = came_from.get(current)
        path.reverse()
        return path
    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        x, y = (current[0] + dx, current[1] + dy)
        if 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] != '#':
            yield from solve_worker(grid, start, goal, came_from, (grid[x][y], x, y))

