    rows, cols = len(grid), len(grid[0])
    if start in [(x, y) for x, row in enumerate(grid) for y, cell in enumerate(row) if cell == '#']:
        return []
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    grid_type = [[bool(cell != '#') for cell in row] for row in grid]
    start = (0 <= start[0] < rows and 0 <= start[1] < cols and grid_type[start[0]][start[1]], *start)
    goal = (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid_type[goal[0]][goal[1]], *goal)
    if not start or not goal:
        return []
    came_from = {}
    if goal in solve_worker(grid_type, start, goal, came_from):
        return ['({},{})'.format(*cell) for cell in solve_worker(grid_type, start, goal, came_from)]
    return []

