import heapq

def ancestor(u, prev):
    while u != -1:
        yield u
        u = prev[u]

def build_lifting(prev):
    lifting = [-1] * len(prev)
    for u in reversed(range(len(prev))):
        for v in ancestor(u, prev):
            if lifting[v] == -1:
                lifting[v] = u
    return lifting

def solve(n, edges, s, t):
    edges_index = {edge: i for i, edge in enumerate(edges)}
    graph = [None] * n
    for u, v, w in edges:
        if graph[u] is None:
            graph[u] = []
        graph[u].append((v, w))
    queue = []
    dist = [float('inf')] * n
    prev = [-1] * n
    dist[s] = 0
    heapq.heappush(queue, (0, s))
    while queue:
        du, u = heapq.heappop(queue)
        if du != dist[u]:
            continue
        for v, w in graph[u] or []:
            dw = dist[u] + w
            if dw < dist[v]:
                dist[v] = dw
                prev[v] = u
                heapq.heappush(queue, (dw, v))
    lifting = build_lifting(prev)
    if dist[t] >= float('inf'):
        return -1
    path_length = 0
    u = t
    while u != -1:
        path_length += 1
        for v in ancestor(u, lifting):
            for w, pw in graph[u] or []:
                if w == pw and w == lifting[v]:
                    path_length += 1
        u = lifting[u]
    return dist[t] + path_length - 1
