from heapq import heappop, heappush

def solve(n, edges, s, t):
    def add(u, v, w):
        if G[u][v] is None:
            G[u][v] = w
        else:
            G[u][v] = min(G[u][v], w)
        if G[v].get(u, None) is None or G[u][v] < G[v].get(u):
            G[v][u] = None

    def dijkstra(s, t, relaxed):
        visited = set()
        relapsed = False
        distance = [float('inf')] * n
        distance[s] = 0
        priority = [(0, s)]
        while priority:
            if relapsed:
                break
            u_dist, u = heappop(priority)
            if distance[u] < u_dist:
                continue
            visited.add(u)
            for v, w in G[u].items():
                if w is not None and v not in visited:
                    if w + distance[u] < distance[v]:
                        relapsed = True
                        relaxed.add((u, v))
                        distance[v] = w + distance[u]
                        if v in relaxed:
                            relaxed.remove(v)
                            relaxed.add((u, v))
                        heappush(priority, (distance[v], v))
            relaxed.add(u)
            while (u_dist, u) in relaxed:
                relapsed = True
                relaxed.remove((u_dist, u))
        if t not in visited:
            return -1
        return distance[t]

    G = [[None] * n for _ in range(n)]
    for u, v, w in edges:
        add(u, v, w)
    shortest = 0
    for u in range(n):
        G_alt = [G[u] for u in range(n)]
        shortest = max(shortest, dijkstra(u, t, set())+ dijkstra(s, u, set()))
    return shortest

