    distances = {u: None for u in range(len(grid))}
    for u in range(len(grid)):
        if distances[u] is None:
            queue = [(0, u)]
            visited = {u}
            distances[u] = 0
            while queue:
                d, u = heapq.heappop(queue)
                if u in parent:
