def build_graph(n, edges):
    """Create an adjacency list representation of a directed graph."""
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))
    return graph

def shortest_path1(graph, s):
    """Use BFS to find the shortest path length from each node to s."""
    distances = {}
    visited = set()
    queue = [(s, 0)]

    while queue:
        node, dist = queue.pop(0)
        if node in distances or node in visited:
            continue
        distances[node] = dist
        visited.add(node)
        for neighbor, weight in graph[node]:
            queue.append((neighbor, dist + weight))

    return distances

def solve(n, edges, s, t):
    """Return the length of the shortest path from node s to node t."""
    graph = build_graph(n, edges)
    distances = shortest_path1(graph, s)
    if t not in distances:
        return -1
    return distances.get(t, 0)

