import sys
import heapq

def solve(n, edges, s, t):
    distances = [-1] * n
    distances[s] = 0
    queue = [(0, s)]

    while queue:
        d, v = heapq.heappop(queue)
        if v == t:
            return d
        if d > distances[v]:
            continue
        for u, w in [(u, w) for u, v_, w in edges if v_ == v]:
            if distances[u] == -1 or distances[u] > distances[v] + w:
                distances[u] = distances[v] + w
                heapq.heappush(queue, (distances[u], u))

