    if 'edges' in E:
        return E['edges']
    elif 'incidence_matrix' in E and 'edge_weights' in E:
        I = E['incidence_matrix']
        W = E['edge_weights']
        return [(i, j, W[i]) for i in range(n) for j in range(n) if I[i][j] and I[i][j] == 1]
