        raise ValueError('Expected "edges", "incidence_matrix" and "edge_weights" keys')

def parse_input():
    n, E = sys.stdin.readline().split()
    E = eval(E)
    return int(n), extract_edges(int(n), E), int(E['source']), int(E['target'])

def main():
    n, edges, s, t = parse_input()
    print(solve(n, edges, s, t))

