    weights = [w for _, _, w in edges]

    visited = [False] * len(edges)
    used_edges = []
    used_nodes = [False] * n
    used_nodes[s] = True

    heap = [(0, s)]
    while len(heap) > 0:
        _, u = heapq.heappop(heap)
        used_nodes[u] = True
        for v, i, w in edges:
            if not used_nodes[v] and not visited[i]:
                visited[i] = True
                heapq.heappush(used_edges, (n - len(used_edges), w))
                heapq.heappush(heap, (w, v))
        edge = heapq.heappop(used_edges)
        if edge[1] < 0:
