    G = prim(n, edges, s)
    dis = bellman_ford2(t, G)
    return dis[s]

def bellman_ford2(s, G):
    dis = [float('inf')] * len(G)
    dis[s] = 0

    for _ in range(len(G) - 1):
        for u in range(len(G)):
