from heapq import heappop, heappush

def parent_edge(u, edges):
    """Find the parent edge of node u"""
    for u1, v, _ in edges:
        if u1 == u:
            return u1, v
    return None, None

def unroll_path(v, predecessor, edges):
    """Find the shortest path from s to v"""
    path = []
    while v is not None:
        u, _, w = parent_edge(v, edges)
        if predecessor[v] == v:
            path.append((u, w))
        v = predecessor[v]
    return path

def toposort(n, edges):
    """Topological sort of a directed graph"""
    rev_graph = [[] for _ in range(n)]
    indegree = [0] * n

    # Build reverse graph and indegree
    for u, v, _ in edges:
        rev_graph[v].append(u)
        indegree[u] += 1

    queue, predecessor = [i for i in range(n) if indegree[i] == 0], [-1] * n
    while queue:
        u = queue.pop(0)
        for v in rev_graph[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)
            predecessor[v] = u
    return predecessor

def solve(n, edges, s, t):
    """Shortest path in a directed weighted graph"""
    predecessor = toposort(n, edges)
    if predecessor[t] == -1:
        return -1

    min_distance = [float('inf')] * n
    min_distance[s] = 0

    heap = [(0, s)]
    while heap:
        dist, u = heappop(heap)
        if dist > min_distance[u]:
            continue
        for _, v, w in edges:
            if v == u:
                new_dist = dist + w
                if new_dist < min_distance[v]:
                    min_distance[v] = new_dist
                    heappush(heap, (new_dist, v))
    return min_distance[t]

