def dfs(s, t, n, edges, vis, dist):
    """Depth-first search to find the shortest path."""
    if s == t:
        return 0
    dist[s] = 0
    stack = [(s, -1)]
    while stack:
        u, prev = stack.pop()
        if u != s and prev == -1:
            dist[u] = float('inf')
        for v, w in edges:
            if v == u and vis[v] == 0:
                stack.append((v, u))
                vis[v] = 1
                dist[v] = dist[u] + w
                if v == t:
                    return dist[v]
                if dist[v] < float('inf'):
                    stack.append((v, u))
            if v == u and vis[v] == 1 and dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                stack.append((v, u))
    return -1

def solve(n, edges, s, t):
    """Floyd-Warshall with DFS to find the shortest path."""
    vis = [0] * n
    dist = [float('inf')] * n
    for u, v, w in edges:
        dist[u] = min(dist[u], w)
    ans = dfs(s, t, n, edges, vis, dist)
    for u, v, w in edges:
        if u == s:
            new_ans = float('inf')
            new_dist = [float('inf')] * n
            vis = [0] * n
            new_dist[s] = 0
            stack = [(s, -1)]
            while stack:
                u_new, prev_new = stack.pop()
                if u_new != s and prev_new == -1:
                    new_dist[u_new] = float('inf')
                for u, v_next, w_next in edges:
                    if v_next == u_new and vis[v_next] == 0:
                        stack.append((v_next, u_new))
                        vis[v_next] = 1
                        new_dist[v_next] = new_dist[u_new] + w_next
                        if v_next == t:
                            new_ans = min(new_ans, new_dist[v_next]+w)
