from collections import defaultdict

def earlier(a, b):
    if a < 0 or b < 0:
        raise ValueError
    return a < b

class DijkstraNode:
    def __init__(self, node, weight):
        self.node = node
        self.weight = weight

    def __lt__(self, other):
        return earlier(self.weight, other.weight)

def solve(n, edges, s, t):
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    distances = [float('inf')] * n
    distances[s] = 0

    q = [DijkstraNode(s, 0)]

    while q:
        node = q.pop()
        nearest = graph[node.node]
        for neighbor, weight in nearest:
            new_distance = node.weight + weight
            if distances[neighbor] > new_distance:
                distances[neighbor] = new_distance
                q.append(DijkstraNode(neighbor, new_distance))
                q.sort(reverse=True)

    return distances[t] if distances[t] < float('inf') else -1

