import heapq

def solve(n, edges, s, t):
    G = [[] for _ in range(n)]
    for u, v, w in edges:
        G[u].append((v, w))
    dist = [float('inf')] * n
    dist[s] = 0
    q = [(0, s)]
    while q:
        d, v = heapq.heappop(q)
        if d > dist[v]:
            continue
        for u, w in G[v]:
            if dist[u] > dist[v] + w:
                dist[u] = dist[v] + w
                heapq.heappush(q, (dist[u], u))
    return -1 if dist[t] == float('inf') else dist[t]

def bfs(n, edges, s, t):
    G = [[] for _ in range(n)]
    for u, v, w in edges:
        G[u].append((v, w))
    dist = [-1] * n
    dist[s] = 0
    q = [(0, s)]
    while q:
        d, v = q.pop(0)
        if d > dist[v]:
            continue
        for u, w in G[v]:
            if dist[u] < 0:
                dist[u] = d + 1
                q.append((dist[u], u))
    return dist

def detect_negative_cycle(n, edges):
    dist = bfs(n, edges, 0, 0)
    for i in range(n):
        if dist[i] != -1 and dist[i] - 1 != bfs(n, edges, i, i)[i]:
            return True
    return False

def solve_(n, edges, s, t):
    if detect_negative_cycle(n, edges):
        return -1
    return solve(n, edges, s, t)

