            continue
        for u, w in G[v]:
            if dist[u] < 0:
                dist[u] = d + 1
                q.append((dist[u], u))
    return dist

def detect_negative_cycle(n, edges):
    dist = bfs(n, edges, 0, 0)
    for i in range(n):
        if dist[i] != -1 and dist[i] - 1 != bfs(n, edges, i, i)[i]:
            return True
    return False

def solve_(n, edges, s, t):
    if detect_negative_cycle(n, edges):
        return -1
    return solve(n, edges, s, t)
