    distances = [float('inf')] * n
    distances[s] = 0

    for _ in range(n - 1):
        updates = False
        for u, v, w in edges:
            if distances[u] != float('inf') and distances[u] + w < distances[v]:
                distances[v] = distances[u] + w
                updates = True
        if not updates:
