            ret.append(topological_sort_helper(s, n, graph, visited))
    return ret

def topological_sort_helper(s, n, graph, visited):
    visited.add(s)
    stack = [(s, 0)]
    while stack:
        u, ind = stack.pop()
        for i in range(ind, len(graph[u])):
            v, _ = graph[u][i]
