from typing import List

def Bellman_Ford(n: int, edges: List[List[int]], s: int, t: int) -> int:
    dis = [10**9] * n
    dis[s] = 0

    for _ in range(n - 1):
        for u, v, w in edges:
            dis[v] = min(dis[v], dis[u] + w)

    for u, v, _ in edges:
        if dis[v] > dis[u] + 1:
            return -1

