    for u, v, _ in edges:
        if dis[v] > dis[u] + 1:
            return -1

    return dis[t] if dis[t] < 10**9 else -1

def solve(n: int, edges: List[List[int]], s: int, t: int) -> int:
    return Bellman_Ford(n, [[u, v, w] for u, v, w in edges], s, t)
