import sys
import heapq

def floyd_warshall(n, edges):
    d = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for u, v, w in edges:
        d[u][v] = min(d[u][v], w)
    for k in range(n):
        for i in range(n):
            for j in range(n):
                d[i][j] = min(d[i][j], d[i][k] + d[k][j])
    return d

def Bellman_Ford(n, edges, s):
    dist = [float('inf')] * n
    dist[s] = 0
    for _ in range(n - 1):
        u = [-1] * n  # last time we updated dist[j] with u[j]
        for uj, _, _ in edges:
            u[uj] = u[uj] if u[uj] != -1 else uj
        for uj, v, w in edges:
            if dist[uj] + w < dist[v] and u[v] == v:
                dist[v] = dist[uj] + w
    for uj, v, w in edges:
        if dist[uj] + w < dist[v] or dist[uj] == float('inf'):
            return -1
    return dist

def solve(n, edges, s, t):
    if s == t:
        return 0

    edges = sorted((w, u, v) for u, v, w in edges)
    d = floyd_warshall(n, edges)
    distance = Bellman_Ford(n, edges, s)
    if distance == -1 or distance[t] == float('inf'):
        return -1
    return distance[t]

