    adj_matrix = [[1000] * n for _ in range(n)]
    for u, v, w in edges:
        adj_matrix[u][v] = w
    return adj_matrix

def floyd_warshall(n: int, adj_matrix: List[List[int]]) -> List[List[int]]:
    for k in range(n):
        for i in range(n):
            for j in range(n):
                adj_matrix[i][j] = min(adj_matrix[i][j], adj_matrix[i][k] + adj_matrix[k][j])
    return adj_matrix

def solve(n: int, edges: List[Tuple[int, int, int]], s: int, t: int) -> int:
    adj_matrix = make_adj_matrix(n, edges)
    adj_matrix = floyd_warshall(n, adj_matrix)

    if t < n and adj_matrix[s][t] != 1000:
        return adj_matrix[s][t]
    else:
        return -1
