        add_edge(graph, u, v, w, end_points)
        add_edge(graph, v, v, 0, end_points)  # Virtual edge to the same node to get all edges

    # Initialize distances to infinity for all nodes except the source
    distances = {i: math.inf for i in range(n)}
    distances[s] = 0

