                continue
            distances[neighbor] = distances[current_node] + graph[current_node][neighbor][0]
            required_to_reach[neighbor] = current_node
            heappush(priority_queue, (distances[neighbor], neighbor))

    if distances[t] == math.inf:
        return -1
    return distances[t]

