    smallest = i
    left = 2 * i + 1
    right = 2 * i + 2
    if left < n and arr[i][0] > arr[left][0]:
        smallest = left
    if right < n and arr[smallest][0] > arr[right][0]:
        smallest = right
    if smallest != i:
        arr[i], arr[smallest] = arr[smallest], arr[i]
        heapify(arr, n, smallest)

