import heapq

def solve(n, edges, s, t):
    INF = float('inf')
    dist = [INF] * n
    dist[s] = 0
    pq = [(0, s)]

    while pq:
        d, u = heapq.heappop(pq)

        if u == t:
            return d

        if dist[u] < d:
            continue

        for v, w in edges:
            if v == u:
                heapq.heappush(pq, (d + w, v))
                dist[v] = min(dist[v], dist[u] + w)

    return -1

from itertools import combinations
def weight(edges):
    return (u + v + w) * 10000 + u*w + v

def compress(edges):
    from collections import defaultdict
    graph = defaultdict(list)
    distances = {}
    for u, v, w in edges:
        graph[u].append((v, w))
        distances[(u, v)] = w

    comp_nodes = sorted(set([u for u, v in distances]) + set([v for u, v in distances]))
    comp_edges = []
    for e in edges:
        ind = weight(e)
        np = (comp_nodes.index(e[0]), comp_nodes.index(e[1]))
        comp_edges.append((ind, np))

    return comp_nodes, comp_edges

def relax(uv, edges, P, d):
    if uv in P:
        return d[uv]

    u, v = uv
    d_uv = INF
    for g in edges:
        if u == g[0] and g[1] == v:
            d_uv = min(d_uv, d.get(g, INF) + g[2])

    if d_uv < INF:
        P.add(uv)

    return d_uv

