                    distance[next_node] = new_distance
                    heapq.heappush(queue, (new_distance, next_node))

        return distance[t] if distance[t] != float('inf') else -1

    graph = {node: {} for node in range(n)}
    for u, v, w in edges:
        graph[u][v] = w

    return distance(graph, s, t)

