            if distance[u] + w < distance[v]:
                distance[v] = distance[u] + w
                if v not in queue:
                    queue.append(v)

        if u == t:
            return distance[t]

        for v, _ in edges:
            if v == u:
                continue
            if distance[u] < distance[v]:
                queue.remove(v)

