from typing import List, Tuple

def stack_based_bellman_ford(n: int, edges: List[Tuple[int, int, int]], s: int, t: int) -> int:
    """
    Find the shortest path from node s to node t in a directed weighted graph.

    This function assumes that the graph does not have any edge with negative weight,
    as specified in the problem statement. However, it still has a time complexity of O(V * E),
    where V is the number of vertices and E is the number of edges.

    If there is a cycle with a negative weight, this function may not terminate.
    """

    # Initialize the distance array with infinity for all nodes except the source node
    distance = [float('inf')] * n
    distance[s] = 0

    # Process nodes in topological order
    def process(node: int) -> None:
        for u, v, w in edges:
            if distance[u] + w < distance[v]:
                distance[v] = distance[u] + w

    # Run Bellman-Ford algorithm for all nodes
    for _ in range(n):
        # Process nodes in the order they are first inserted into the distance arrays below, in case of a non-negativity constraint violation
        seen = set()
        for u, v, w in edges:
            if u not in seen:
                seen.add(u)
                if distance[v] > distance[u] + w:
                    distance[v] = distance[u] + w
                if u == v:
                    continue
            seen.add(v)

    # Check if the target node is reachable from the source node
    if distance[t] == float('inf'):
        return -1  # target node is unreachable
    else:
        return distance[t]


def extract_edges(ops: List[Tuple[int, Tuple[int, int], int]]) -> List[Tuple[int, int, int]]:
    """
    Convert a list of operations returned by #bfs_by_stack into edges for a directed graph.
    """

    return [(u, v, w) for u, ((v1, u2), w) in enumerate(ops) for v, w_v in ((v1, u2), (u2, v1)) 
            if v != u and (u2 == v or (u, v, w) not in org_edges)]


def ExtractEdgesToList(edges: List[Tuple[int, int, int]]) -> List[List[int]]:
    """
    Convert a list of edges for a directed graph into a sparse array.
    """
    edgesRHO = EditIdleListFilledAutoCapacity(100, 10)
    for u, v, w in edges:
        edgesRHO[u].append(v << 1 | 0)
        edgesRHO[v].append(u << 1 | 1)

    return edgesRHO


