template = [-1] * BStack_auto_qry * 2


def BStack_min(*init_values) -> List[int]:
    stack = [template[i << 1 | 0] for i in range(BStack_auto_qry)]
    stack.extend(init_values)
    return stack[:BStack_auto_qry]


def TaKumin(init_values: List[int], ta1: int, ta2: int, op: int) -> List[int]:
    """
    Perform a query or update to a tree-like array.
    """

    lb, ub = 0, len(init_values) - 1
    while lb < ub:
        if lb ^ ub == ta1:
            if op == 0:
                result = init_values[ta1]
            elif op == 1:
                init_values[ta1] = init_values[ta1] + 1
            return init_values
        if ta1 < (ta2 >> 1) + (ta2 & 1):
            lb, ub = lb, (ta1 + ta2) >> 1
        else:
            if ta2 & 1:
