from collections import defaultdict, deque
import sys

def find(X, par):
    while X != par[X]:
        X = par[X]
    return X

def merge(u, v, par, sz, edgeW):
    u_root = find(u, par)
    v_root = find(v, par)
    if u_root == v_root:
        return edgeW[u_root] + 1e8
    newW = edgeW[u_root] + edgeW[v_root]
    edgeW[v_root] = newW
    sz[v_root] += sz[u_root]
    par[u_root] = v_root
    return newW

def dfs(u, lst, par, edgeW, sz):
    if len(lst) == 1:
        return 0
    res = 1e8
    for v in lst:
        if v != u and par[v] == u:
            res = min(res, dfs(v, lst, par, edgeW, sz))
    for v in lst:
        if par[v] == u:
            edgeW[v] = merge(v, u, par, sz, edgeW)
    return min(res, edgeW[u])

def solve(n, edges, s, t):
    if s == t:
        return 0
    if not edges:
        return -1
    par = list(range(n))
    edgeW = [0] * n
    sz = [1] * n
    if s != t:
        for u, v, w in edges:
            u_root = find(u, par)
            v_root = find(v, par)
            if u_root != v_root:
                par[u_root] = v_root
                edgeW[v_root] = w
                sz[v_root] += sz[u_root]
    return dfs(t, range(n), par, edgeW, sz) if s != t else 0

