import heapq
import sys

def dist(v):
    return float('inf') if v < 0 or v >= n else dp[v]

def relax(u, v):
    global iteration
    old = dist(v)
    new = dist(u) + weight[u][v]
    if new < old:
        dist(v) = new
        parent[v] = u
        iteration += 1

def BellmanFord(n, edges, s, t):
    global dp, weight, parent, iteration
    dp = [dist(v) for v in range(n)]
    parent, weight = [-1 for v in range(n)], [[0 for v in range(n)] for _ in range(n)]
    for u, v, w in edges:
        weight[u][v] = w
    dp[s] = 0
    iteration = 0
    for _ in range(n - 1):
        for u, v, _ in edges:
            relax(u, v)
    for u, v, _ in edges:
        if dist(u) + weight[u][v] < dist(v):
            raise ValueError("Graph contains negative-weight cycle")
    min_dist = dist(t)
    return 0 if (s == t and min_dist == 0) else (-1 if min_dist == float('inf') else min_dist)

def solve(n, edges, s, t):
    if s == t:
        return 0
    if s > t:
        s, t = t, s
    edges = [(u, v ^ 1, w) if u > v else (u ^ 1, v, w) for u, v, w in edges]
    edge_accumulator = []
    edge_accumulator.append([1])
    size = len(edge_accumulator[0])
    for s in edge_accumulator[0]:
        edge_accumulator.clear()
        edge_accumulator.append([s])
        for u, v, _ in edges:
            if v == s:
                new = edge_accumulator[-1]
                new.append(u)
                edge_accumulator.append(new)
            elif u == s:
                new = edge_accumulator[-1]
                new.append(v)
                edge_accumulator.append(new)
        if s == t:
            break
    if s != t:
        return -1
    group_size = len(edge_accumulator[0])
    subtracts = [[0] * group_size for _ in range(n)]
    for i in range(group_size - 1, -1, -1):
        for id in range(group_size):
            subtracts[edge_accumulator[i][id]][edge_accumulator[i + 1][id]] = 1
            subtracts[edge_accumulator[i + 1][id]][edge_accumulator[i][id]] = 0
    edges = [(edge_accumulator[0][id], edge_accumulator[-1][id], w + sum(subtracts[id])) for id, (u, v, w) in enumerate(edges) if v == s]
    return BellmanFord(n, edges, 0 if s == 0 else n - 1, 0 if t == 0 else n - 1)

