import sys

def solve(n, edges, s, t):
    relabel_limit = 10000
    inf = sys.maxsize / 2

    class Node:
        def __init__(self, d, u):
            self.d = d
            self.u = u

    def build_graph(n, edges):
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
        return graph

    def initialize(graph, n):
        dist = [-inf] * n
        dist[s] = 0
        prev = [None] * n
        tree = [[] for _ in range(n)]
        heap = [Node(0, s)]
        relabel = [0] * n
        while heap:
            node = heap.pop(0)
            d = node.d
            u = node.u
            if d > dist[u]:
                continue
            for v, w in graph[u]:
                new_dist = dist[u] + w
                if new_dist < dist[v]:
                    dist[v] = new_dist
                    tree[v].clear()
                    tree[v].append(u)
                    prev[v] = u
                    heap.append(Node(new_dist, v))
                    relabel[v] = 0
        for i in range(n):
            if dist[i] == inf:
                tree[i].append(s)
        return dist, tree, relabel

    graph = build_graph(n, edges)
    dist, tree, relabel = initialize(graph, n)
    for cur in range(n):
        while relabel[cur] < relabel_limit:
            for v in range(n):
                if dist[v] == -inf or relabel[v] > relabel[cur]:
                    continue
                push = False
                for u in tree[v]:
                    if relabel[u] >= relabel[cur] + 1:
                        push = True
                        break
                if not push:
                    continue
                for u in tree[v]:
                    if relabel[u] == relabel[cur] + 1:
                        push = True
                        break
                if not push:
                    for u in tree[v]:
                        if relabel[u] == relabel[cur]:
                            push = True
                            break
                if not push:
                    continue
                relabel[v] += 1
                tree[v].clear()
                for u in range(n):
                    if relabel[u] > relabel[v]:
                        continue
                    for w in graph[u]:
                        v2, w = w
                        if relabel[v2] >= relabel[v] + 1:
                            continue
                        if w + dist[u] < dist[v2]:
                            dist[v2] = w + dist[u]
                            tree[v2].clear()
                            tree[v2].append(u)
                            tree[v2].append(v)
                            relabel[v2] = 0
                            heap.append(Node(w + dist[u], v2))
                            heap.sort(key=lambda x: x.d)
        if dist[t] == -inf:
            return -1
    return dist[t]

