import copy

def are_neighbours(node1, node2):
    """Check if two nodes are neighbours."""
    return abs(node1[0] - node2[0]) + abs(node1[1] - node2[1]) == 1

def is_valid(grid, node):
    """Check if a node is within the grid and is not a wall."""
    return (0 <= node[0] < len(grid)) and (0 <= node[1] < len(grid[0])) and grid[node[0]][node[1]] == '.'

def is_goal(grid, node, goal):
    """Check if a node is the goal."""
    return node == goal

def solve(grid, start, goal):
    """Find a path between two cells in a grid."""
    open_list = [(start, [start])]
    closed_list = {}

    while open_list:
        node, path = min(open_list)
        open_list.remove((node, path))
        closed_list[node] = path

        if is_goal(grid, node, goal):
            return path

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            x, y = node[0] + dx, node[1] + dy
            neighbour = (x, y)

            if is_valid(grid, neighbour) and neighbour not in closed_list:
                open_list.append((neighbour, copy.deepcopy(path + [neighbour])))

    return []

