    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    queue, path, visited = [(start, [start])], [], {(start[0], start[1])}

    while queue:
        pos, current_path = queue.pop(0)
        if pos == goal:
            return current_path
        row, col = pos
        for direction in directions:
            new_row, new_col = row + direction[0], col + direction[1]
            if (1 <= new_row <= rows) and (1 <= new_col <= cols) and (grid[new_row-1][new_col-1] == '.') and (not (new_row, new_col) in visited):
