    def is_valid(cell):
        return 0 <= cell[0] < len(grid) and 0 <= cell[1] < len(grid[0]) and grid[cell[0]][cell[1]] == '.'

    def get_neighbours(cell):
        neighbours = []
        dx = [-1, 1, 0, 0]
        dy = [0, 0, -1, 1]
        for i in range(4):
            x, y = cell[0] + dx[i], cell[1] + dy[i]
            if is_valid((x, y)):
                neighbours.append((x, y))
        return neighbours

    def reconstruct_path(came_from):
        current = goal
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.insert(0, current)
        return path

    if start == goal:
        return [start]

    open_set = {start}
    closed_set = set()
    came_from = {}
    cost_so_far = {start: 0}

    while open_set:
        current = min(open_set, key=lambda cell: (cost_so_far[cell], cell))
        if current == goal:
            return reconstruct_path(came_from)

        open_set.remove(current)
        closed_set.add(current)

        for neighbour in get_neighbours(current):
            new_cost = cost_so_far[current] + 1

            if neighbour in cost_so_far and new_cost >= cost_so_far[neighbour]:
                continue

            cost_so_far[neighbour] = new_cost
            came_from[neighbour] = current
            open_set.add(neighbour)

