    while queue:
        (row, col), path, discovered_goal = queue.pop(0)

        if (row, col) == goal:
            if discovered_goal:
                return path
            else:
                queue.extend([(goal, path + [goal], True)] if not discovered_goal else [])

        for dr, dc in dirs:
            r, c = row + dr, col + dc

            if 0 <= r < rows and 0 <= c < cols and grid[r][c] != '#' and (r, c) not in visited:
                queue.append(((r, c), path + [(r, c)], discovered_goal))
