        if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] != '#':
            yield r, c

def solve(grid, start, goal):
    snake = deque()
    visited = set()

    def is_valid_path(current):
        return start <= current < goal and (current not in visited or tuple(reversed(current)) in visited)

    snake.append(start)
    visited.add(start)

    while snake:
        current = snake.popleft()
        if current == goal:
            path = [current]
            while path[-1] != start:
                next_cell = tuple(reversed(next((n for n in snake if current in (n, tuple(reversed(n)))))))
                path.append(next_cell)
                current = next_cell
            return list(reversed(path))

        for neighbour in find_neighbours(grid, *current):
            if is_valid_path(neighbour):
                snake.append(neighbour)
                visited.add(neighbour)

    return []

