                if is_valid(nr, nc) and (nr, nc) not in path:
                    path.append((nr, nc))
                    if (nr, nc) == goal:
                        return True
                    successors.append((nr, nc))
        return False

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    queue = [start]
    path = [start]
    while queue:
        if queue_successors(queue):
            return path
        q = queue[:]
        queue = []
        for row, col in q:
            for dr, dc in neighbors:
                nr, nc = row + dr, col + dc
                if is_valid(nr, nc) and (nr, nc) not in path:
                    queue.append((nr, nc))
                    path.append((nr, nc))
        path.pop()

    return []
