def solve(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    pq = [(0, s)]
    visited = [0] * n
    distance = [sys.maxsize] * n

    while pq:
        d, u = heapq.heappop(pq)
        if visited[u]:
            continue
        visited[u] = 1
        distance[u] = d
        for v, w in graph[u]:
            if not visited[v]:
                heapq.heappush(pq, (d + w, v))

    return distance[t] if distance[t] != sys.maxsize else -1

def solve(n, edges, s, t):
    def relax(graph, d):
        for u in range(n):
            for v, w in graph[u]:
                d[v] = min(d[v], d[u] + w)

    def min_dist(graph):
        d = [float('inf')] * n
        d[s] = 0
        for _ in range(n - 1):
            relax(graph, d)
        relax(graph, d)
        return d

    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    if s == t:
        return 0

    d = min_dist(graph)
    return int(d[t]) if d[t] != float('inf') else -1

