    for u, v, w in edges:
        G.add_edge(u, v, w)

    def DFS(u, visited, dist):
        if u == t:
            return dist
        if u in visited:
            return -1
        visited.add(u)
        for v, w in G.g[u]:
            if DFS(v, visited, dist + w) != -1:
                return dist + w
        visited.remove(u)
        return -1

