import sys

def dfs(node, visited, dp, edges, parent, n):
    visited[node] = True
    dp[node] = float('inf')
    for u, v, w in edges:
        if (u, v) == (parent[node], node):
            continue
        if u != node and not visited[u] and v == node:
            parent[u] = node
            dp[node] = min(dp[node], dp[u] + w)
            dfs(u, visited, dp, edges, parent, n)
        elif u == node and not visited[v]:
            parent[v] = node
            dfs(v, visited, dp, edges, parent, n)
    visited[node] = False

def solve(n, edges, s, t):
    dp = [0] * n
    parent = [-1] * n
    visited = [False] * n
    if s == t:
        return 0
    edges.sort(key=lambda x: x[2])
    for i in range(len(edges)):
        if edges[i][1] == t and edges[i][0] == s:
            return edges[i][2]
    dfs(s, visited, dp, edges, parent, n)
    if dp[t] == float('inf'):
        return -1
    return dp[t]

