from collections import deque

def gauge(node, distance):
    return distance[node] < float('inf') and distance[node] == min(dist for (n, dist) in distance if n == node)

def relax(u, v, distance):
    if not gauge(u, distance) or v not in distance: return
    if gauge(v, distance):
        distance[v] = min(distance[u] + 1, distance[v])
    else:
        distance[u] = min(distance[u], distance[v] + 1)

def solve(n, edges, s, t):
