    def soak(graph, s):
        visited = [0] * n
        order = []
        stack = [(0, s)]
        while stack:
            if visited[s] == 0:
                visited[s] = 1
                order.append(s)
            dist, s = heappop(stack)
            if visited[s] == 1:
                for i in range(len(graph[s])):
                    u, v = graph[s][i][:2]
                    if visited[u] == 0:
                        heappush(stack, (dist + graph[s][i][2], u))
        return order

    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))
    s = s
    t = t
    order = soak(graph, s)
    dp = [float('inf')] * n
    dp[s] = 0
    for i in range(len(order)):
        v = order[i]
        if dp[v] < float('inf'):
            for u, w in graph[v]:
                if dp[u] > dp[v] + w:
                    dp[u] = dp[v] + w
    return dp[t] if dp[t] < float('inf') else -1
