def get_registry(n):
    return [1e16] * n

def relax(graph, dist, s, u, v, w):
    if dist[u] + w < dist[v]:
        dist[v] = dist[u] + w

def solve(n, edges, s, t):
    graph = [[] for _ in range(n)]
    dist = get_registry(n)

    for u, v, w in edges:
        graph[u].append((v, w))

    dist[s] = 0

    priority = [(i, 0) for i in range(n)]

    while priority:
        _, d = min(priority)
        priority.remove(min(priority))

        for j, dd in priority[:]:
            priority.remove((j, dd))
            if dd < d:
                priority.insert(0, (j, dd))

        for v, w in graph[priority.pop()[0]]:
            relax(graph, dist, s, priority.pop()[0], v, w)

    return int(dist[t]) if dist[t] < 1e16 else -1

