def dfs(graph: List[List[Tuple[int, int]]], s: int, t: int) -> int:
    seen = [False] * len(graph)
    weights_sum = [99_999] * len(graph)
    stack = [(s, 0)]

    while stack:
        node, weight_sum = stack.pop()
        seen[node] = True
        if node == t:
            return weight_sum
        for neighbor, weight in graph[node]:
            if not seen[neighbor]:
                weights_sum[neighbor] = min(weights_sum[neighbor], weight_sum + weight)
                stack.append((neighbor, weights_sum[neighbor]))

    return -1

def remove_parallel_edge(graph: List[List[Tuple[int, int]]], u: int, v: int, w: int) -> None:
    for i in range(len(graph[u])):
        if graph[u][i][0] == v and graph[u][i][1] == w:
            graph[u].pop(i)
            break

def solve(n: int, edges: List[Tuple[int, int, int]], s: int, t: int) -> int:
