def dfs(n, adj, s, t, memo):
    if s == t:
        return 0
    if s in memo:
        return memo[s]
    longest = 0
    for u, v, w in adj[s]:
        longest = max(longest, dfs(n, adj, v, t, memo) + w)
    memo[s] = longest if longest >= 0 else float('inf')
    return memo[s]

def topsort(n, edges):
    graph = [[] for _ in range(n)]
    in_degree = [0] * n
    for u, v, _ in edges:
        graph[u].append((v, None))
        in_degree[v] += 1
    queue = [i for i in range(n) if in_degree[i] == 0]
    while queue:
        u = queue.pop(0)
        for v, _ in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)
    return [i for i in range(n) if in_degree[i] > 0]

def solve(n, edges, s, t):
    if s == t:
        return 0
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
    topo = topsort(n, edges)
    if t not in topo:
        return -1
    if s in topo:
        to_remove = s
    else:
        to_remove = t
    for i in range(len(topo) - 1, -1, -1):
        u, v = topo[i], topo[i + 1] if i < len(topo) - 1 else float('inf')
        if v != to_remove:
            for du, dw in adj[u]:
                adj[du].append((v, dw))
            adj[u].clear()
    memo = {}
    ans = dfs(n, adj, to_remove, t, memo)
    return ans if ans != float('inf') else -1

