def solve(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for (u, v, w) in edges:
        graph[u].append((v, w))

    pq = [(0, s)]
    seen = {s: 0}

    while pq:
        (weight, u) = heapq.heappop(pq)
        if u == t:
            return weight
        if weight > seen.get(u, weight):
