def build_graph(n, edges):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))
    return graph

def heuristic(u, v):
    return 0  # No heuristic used in this solution

def astar(n, graph, s, t):
    pq = [(0, s)]
    seen = {s}
    came_from = {s: None}
    cost_so_far = {s: 0}

    while pq:
        _, current = heapq.heappop(pq)
        if current == t:
            break
        for neighbor, weight in graph[current]:
            new_cost = cost_so_far[current] + weight
            if neighbor not in seen or new_cost < cost_so_far[neighbor]:
                seen.add(neighbor)
                came_from[neighbor] = current
                cost_so_far[neighbor] = new_cost
                priority = new_cost + heuristic(current, t)
                heapq.heappush(pq, (priority, neighbor))

    if t not in seen:
        return -1
    return cost_so_far[t]

def solve(n, edges, s, t):
    graph = build_graph(n, edges)
    return astar(n, graph, s, t)

