class Heap:
    def __init__(self, n):
        self.c = n
        self.h = [float('inf')] * (2 * n)
        self.w = [0] * (2 * n)
        self.sz = 0

    def ins(self, x, y):
        self.h[self.sz] = x
        self.w[self.sz] = y
        self.sz += 1
        self.pz(self.sz - 1)

    def pz(self, x):
        if x:
            if x > 1:
                if self.h[self.c[x // 2]] > self.h[x]:
                    self.h[self.c[x // 2]], self.h[x] = self.h[x], self.h[self.c[x // 2]]
                    self.w[self.c[x // 2]], self.w[x] = self.w[x], self.w[self.c[x // 2]]
                if self.h[self.c[x // 2] ^ 1] > self.h[x]:
                    self.h[self.c[x // 2] ^ 1], self.h[x] = self.h[x], self.h[self.c[x // 2] ^ 1]
                    self.w[self.c[x // 2] ^ 1], self.w[x] = self.w[x], self.w[self.c[x // 2] ^ 1]
            if self.h[self.c[x] // 2] > self.h[x]:
                self.h[self.c[x] // 2], self.h[x] = self.h[x], self.h[self.c[x] // 2]
                self.w[self.c[x] // 2], self.w[x] = self.w[x], self.w[self.c[x] // 2]
            if self.h[self.c[x] ^ 1 // 2] > self.h[x]:
                self.h[self.c[x] ^ 1 // 2], self.h[x] = self.h[x], self.h[self.c[x] ^ 1 // 2]
                self.w[self.c[x] ^ 1 // 2], self.w[x] = self.w[x], self.w[self.c[x] ^ 1 // 2]

    def rem(self):
        if self.sz == 0:
            return float('inf'), 0
        self.sz -= 1
        minv = self.h[1]
        self.h[1] = self.h[self.sz + 1]
        self.w[1] = self.w[self.sz + 1]
        self.pz(1)
        return minv, self.w[1]

def solve(n, edges, s, t):
    if s == t:
        return 0
    d = [float('inf')] * n
    p = [-1] * n
    d[s] = 0
    h = Heap(n * 2)
    h.ins(0, s)
    while True:
        v, i = h.rem()
        if v > d[i]:
            continue
        if i == t:
            break
        di = d[i]
        for u, ji in enumerate(edges):
            if ji[0] == i:
                j = ji[1]
                w = ji[2]
                if di + w < d[j]:
                    d[j] = di + w
                    p[j] = i
                    h.ins(d[j], j)
        for u, ji in enumerate(edges):
            if ji[0] == i:
                j = ji[1]
                w = ji[2]
                if d[j] - w >= 0 and d[j] - w < d[i]:
                    d[j] = d[i]
                    p[j] = i
                    h.ins(d[j], j)
    if d[t] == float('inf'):
        return -1
    path = []
    i = t
    while p[i] != -1:
        path.append([i, p[i], d[i] - d[p[i]]])
        i = p[i]
    path.reverse()
    ans = 0
    for u, v, w in path:
        ans += w
    return ans

