def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    start, goal = start[0] * cols + start[1], goal[0] * cols + goal[1]

    unvisited = [i * cols + j for i in range(rows) for j in range(cols) if grid[i][j] == '.']
    neighbours = {(i, j) for i in range(rows) for j in range(cols) if grid[i][j] == '.'}
