    if start == goal:
        return [goal]

    queue = deque([(start, None)])
    while queue:
        state, move = queue.popleft()

        if state == goal:
            path = []
            while state is not None:
                path.append([state // cols, state % cols])
                state = parent[state]
            return path[::-1]

        for neighbour in neighbours - {state}:
            new_state = neighbour * cols + neighbour // cols * cols + neighbour % cols
            queue.append((new_state, state))

            neighbours -= {new_state}
            grid[new_state // cols][new_state % cols] = '#'
            parent[new_state] = state

    return []

