def solve(grid, start, goal):
    def is_valid_move(cell):
        return 0 <= cell[0] < len(grid) and 0 <= cell[1] < len(grid[0]) and grid[cell[0]][cell[1]] == '.'

    def get_neighbours(cell):
        return [(cell[0]-1, cell[1]), (cell[0]+1, cell[1]), (cell[0], cell[1]-1), (cell[0], cell[1]+1)]

    def find_path_bfs_origin(start, goal):
        queue = deque([[start]])
        while queue:
            path = queue.popleft()
            cell = path[-1]
            if cell == goal:
                return path
            for neighbour in get_neighbours(cell):
                if is_valid_move(neighbour) and neighbour not in path:
                    queue.append(path + [neighbour])
        return []

    def find_path_bfs_goal(end, start):
        queue = deque([[start]])
        while queue:
            path = queue.popleft()
            cell = path[-1]
            if cell == end:
                return path[::-1]  # reverse the path
            for neighbour in get_neighbours(cell):
                if is_valid_move(neighbour) and neighbour not in path:
                    queue.append(path + [neighbour])
        return []

    if start == goal:
        return [start]
    if not is_valid_move(start) or not is_valid_move(goal):
        return []
    path = find_path_bfs_origin(start, goal)
    return path if path else find_path_bfs_goal(goal, start)

