from collections import deque

def solve(grid, start, goal):
    def is_valid(cell):
        return 0 <= cell[0] < len(grid) and 0 <= cell[1] < len(grid[0]) and grid[cell[0]][cell[1]] == '.'

    def get_neighbours(cell):
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        return [(cell[0] + d[0], cell[1] + d[1]) for d in directions]

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    frontiers = deque([(start, [start])])
    backtracking_frontiers = deque([(goal, [])])
    seen = set([start])

    while frontiers and backtracking_frontiers:
        new_path = frontiers.popleft()[1]
        cell = frontiers.popleft()[0]
        for neighbour in get_neighbours(cell):
            if neighbour not in seen and is_valid(neighbour):
                neighbour_path = new_path + [neighbour]
                neighbour_backtrack = (neighbour, reverse_path(neighbour_path))
                if neighbour_backtrack not in backtracking_frontiers:
                    backtracking_frontiers.appendleft(neighbour_backtrack)
                    seen.add(neighbour)

        new_cell = backtracking_frontiers.popleft()[0]
        new_path = backtracking_frontiers.popleft()[1]
        cell = new_cell
        for neighbour in get_neighbours(cell):
            if neighbour in seen and is_valid(neighbour):
                neighbour_path = new_path + [cell] + [neighbour]
                if neighbour in frontiers:
                    new_list = list(frontiers)[list(frontiers).index((neighbour, frontiers[0][1]))][1]
                    frontiers[frontiers.index((neighbour, frontiers[0][1]))] = (neighbour, neighbour_path if len(neighbour_path) > len(new_list) else new_list)
                else:
                    frontiers.append((neighbour, neighbour_path))
                seen.remove(neighbour)

    return frontiers[0][1] if frontiers else []

def reverse_path(path):
    return [item for item in reversed(path)]

