        node, path = queue1.popleft()
        if node not in visited:
            visited.add(node)
            for neighbor in get_neighbors(node):
                if neighbor in queue2:
                    reverse_path = queue2.queue[queue2.index((neighbor, queue2[queue2.index((neighbor, []))]))
                    for i in range(len(queue2[queue2.index((neighbor, []))]) - 1, -1, -1)]
                    path += reverse_path[1:]
                    return path + [neighbor]
