from collections import deque

def solve(grid, start, goal):
    if start == goal and '.' in grid[start[0]]: return [start]
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#': return []

    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    queue1, queue2 = deque([start]), deque([goal])
    visited1, visited2 = {start}, {goal}
    graph = {}

    while queue1 and not queue2:
        for _ in range(len(queue1)):
            x, y = queue1.popleft()
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if (0 <= nx < rows and 0 <= ny < cols and
                    grid[nx][ny] == '.' and (nx, ny) not in visited1):
                    visited1.add((nx, ny))
                    queue1.append((nx, ny))
                    if (nx, ny) in visited2:
                        path1 = []
                        while (x, y) != (nx, ny):
                            path1.append((x, y))
                            for dx, dy in directions:
                                if (x + dx, y + dy) == (nx, ny):
                                    x, y = x + dx, y + dy
                                    break
                            path1.append((nx, ny))
                            nx, ny = x, y
                        graph[start] = path1
                        graph[nx, ny] = path1 + [(nx, ny), start]
                        return path1 + [(nx, ny), start]
                    queue2.append((nx, ny))

    while queue2 and not queue1:
        for _ in range(len(queue2)):
            x, y = queue2.popleft()
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if (0 <= nx < rows and 0 <= ny < cols and
                    grid[nx][ny] == '.' and (nx, ny) not in visited2):
                    visited2.add((nx, ny))
                    queue2.append((nx, ny))
                    if (nx, ny) in visited1:
                        path2 = []
                        while (x, y) != (nx, ny):
                            path2.append((x, y))
                            for dx, dy in directions:
                                if (x + dx, y + dy) == (nx, ny):
                                    x, y = x + dx, y + dy
                                    break
                            path2.append((nx, ny))
                            nx, ny = x, y
                        graph[goal] = path2
                        graph[nx, ny] = path2 + [(nx, ny), goal]
                        return path2 + [(nx, ny), goal]

    return []

