from typing import List, Tuple

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    rows, cols = len(grid), len(grid[0])
    walls = set()
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '#':
                walls.add((i, j))

    def neighbors(cell: Tuple[int, int]) -> List[Tuple[int, int]]:
        row, col = cell
        result = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = row + dr, col + dc
            if (0 <= nr < rows) and (0 <= nc < cols) and (nr, nc) not in walls:
                result.append((nr, nc))
        return result

    parent = {start: None}
    visited = set()
    queue = [(start, [start], False)]

    while queue:
        cell, path, found_goal = queue.pop(0)
        if cell == goal:
            return path
        if cell in visited or cell in walls:
            continue
        visited.add(cell)
        for neighbor in neighbors(cell):
            queue.append((neighbor, path + [neighbor], found_goal or (neighbor == goal)))
            parent[neighbor] = cell
            if neighbor == goal:
                break

    return []

def is_valid_path(path: List[Tuple[int, int]], grid: List[str]) -> bool:
    if len(path) < 2:
        return True
    previous, current = path[-2], path[-1]
    walls = set()
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '#':
                walls.add((i, j))
    return (previous, current) in [((i+1, j), (i, j)) for i in range(len(grid)-1) for j in range(len(grid[0]))] or  \
           (previous, current) in [((i-1, j), (i, j)) for i in range(1, len(grid)) for j in range(len(grid[0]))] or  \
           (previous, current) in [((i, j+1), (i, j)) for i in range(len(grid)) for j in range(len(grid[0])-1)] or  \
           (previous, current) in [((i, j-1), (i, j)) for i in range(len(grid)) for j in range(1, len(grid[0]))] or  \
           not (previous in walls or current in walls)

def check_path(cell, path, grid):
    row, col = cell
    path.insert(0, (row, col))
    valid_path =  is_valid_path(path, grid)
    if not valid_path:
        return False
    for cell in path:
        if grid[cell[0]][cell[1]] == '#':
            return False
    return True

