def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols and grid[x][y] == '.'

    def bfs_search(start):
        queue = deque([start])
        visited = {start}
        while queue:
            x, y = queue.popleft()
            if (x, y) == goal:
                path = [(x, y)]
                while (x, y) != start:
                    for dx, dy in directions:
                        xx, yy = x + 2 * dx, y + 2 * dy
                        if (xx, yy) in visited:
                            x, y = xx, yy
                            path.append((x, y))
                            break
                return path[::-1]
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny) and (nx, ny) not in visited:
                    queue.append((nx, ny))
                    visited.add((nx, ny))
        return []

    path = bfs_search(start)
    if path:
        return path + bfs_search(goal)[1:-2][::-1]
    return []

