def is_in_bounds(grid, r, c):
    return 0 <= r < len(grid) and 0 <= c < len(grid[0])

def is_free(grid, r, c):
    return grid[r][c] == '.'

def get_neighbours(grid, r, c):
    neighbours = []
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r + dr, c + dc
        if is_in_bounds(grid, nr, nc) and is_free(grid, nr, nc):
            neighbours.append((nr, nc))
    return neighbours

def solve(grid, start, goal):
    def iddfs(max_depth):
        queue = [(start, [(start)], 0)]
        while queue:
            node, path, depth = queue.pop(0)
            if node == goal:
                return path
            for neighbour in get_neighbours(grid, *node):
                new_path = path + [neighbour]
                queue.append((neighbour, new_path, depth + 1))
            if depth == max_depth:
                return None
        return None

    best_path = None
    for max_depth in range(1, 100):
        path = iddfs(max_depth)
        if path is not None:
            if best_path is None or len(path) < len(best_path):
                best_path = path
            if path[-1] == goal:
                return path
    return []

