    rows, cols = len(grid), len(grid[0])
    queue = deque([(start, [start])])
    parents = {}

    def valid(node):
        r, c = node
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    for r, row in enumerate(grid):
        for c, cell in enumerate(row):
            if (r, c) == start:
                grid[r] = grid[r][:c] + 'S' + grid[r][c+1:]
            elif (r, c) == goal:
                grid[r] = grid[r][:c] + 'G' + grid[r][c+1:]
            elif cell == '#':
                grid[r] = grid[r][:c] + '#' + grid[r][c+1:]

    found_goal = False
    while queue:
        node, path = queue.popleft()
        r, c = node
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if valid((nr, nc)):
                new_path = path + [(nr, nc)]
                if (nr, nc) == goal:
                    parents[(nr, nc)] = (r, c)
                    new_path = parents.copy()
                    for k, (parent, _) in new_path.items():
                        new_path[k] = (k[0], k[1])
                    new_path = new_path.keys()
                    found_goal = True
                else:
                    parents[(nr, nc)] = (r, c)
                queue.append(((nr, nc), new_path))

    if found_goal:
        path = list(parents.keys())
        grid = [['.' if c == 'S' else '#' if c == '#' else c else '.' for c in row] for row in grid]
        return path
    else:
        return []

