from collections import deque

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    if start == goal:
        return [start]
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    q_start = deque([(start, [start])])
    q_end = deque([(goal, [goal])])

    seen_start = set([start])
    seen_end = set([goal])

    while q_start and q_end:
        (x, y), path_start = q_start.popleft()
        (u, v), path_end = q_end.popleft()

        if (u, v) in seen_start or (x, y) in seen_end:
            continue

        if (u, v) == start:
            return path_start + path_end[::-1]

        if (x, y) == goal:
            return path_end + path_start[::-1]

        seen_start.add((u, v))
        seen_end.add((x, y))

        for dx, dy in directions:
            nx, ny = u + dx, v + dy
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '.':
                q_start.append(((nx, ny), path_start + [(nx, ny)]))
            cx, cy = x + dx, y + dy
            if 0 <= cx < rows and 0 <= cy < cols and grid[cx][cy] == '.':
                q_end.append(((cx, cy), path_end + [(cx, cy)]))

    return []

