from collections import deque

def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    rows, cols = len(grid), len(grid[0])
    visited = set()
    queue = deque([(start, [start])])

    def neighbours(cell):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            r, c = cell[0] + dr, cell[1] + dc
            if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.':
                yield (r, c)

    def bidirectional_bfs():
        queue1 = [start]
        queue2 = [goal]
        visited1 = set()
        visited2 = set()

        if start == goal and all(grid[r][c] == '.' for r, c in zip(start, goal)):
            return deque([start])

        while queue1 and queue2:
            cell1 = queue1.pop(0)
            cell2 = queue2.pop(0)

            if cell2 in visited1:
                path = list(cell1[-1])
                for r, c in reversed(cell1[:-1]):
                    path.append((r, c))
                path.extend(cell2)
                return deque(reversed(path))

            if cell1 in visited2:
                path1 = list(cell2)
                for r, c in reversed(cell2[:-1]):
                    path1.append((r, c))
                path1.extend(cell1)
                return deque(reversed(path1))

            if cell1 not in visited1:
                visited1.add(cell1)
                queue1.extend(cell1[:-1] for cell1 in map(lambda x: (cell1[0], x), neighbours(cell1)))

            if cell2 not in visited2:
                visited2.add(cell2)
                queue2.extend(cell2[:-1] for cell2 in map(lambda x: (x, cell2[1]), neighbours(cell2)))

        return []

    return bidirectional_bfs()

