    start_pos, goal_pos = start, goal

    def valid_moves(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '.'

    def bfs(start, orientation):
        queue = deque([(start, [start])])
        visited.add(start)

        while queue:
            ((x, y), path) = queue.popleft()

            if (x, y) == goal_pos:
                return path

            neighbors = [(x+1, y) if orientation == 'down' else None,
                         (x-1, y) if orientation == 'up' else None,
                         (x, y+1) if orientation == 'right' else None,
                         (x, y-1) if orientation == 'left' else None]

            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                new_neighbors = [(x+dx, y+dy) if orientation != 'right' and orientation != 'left' else None,
