                                 (x+dy, y+dx) if orientation != 'down' and orientation != 'up' else None,
                                 (x-dy, y-dx) if orientation != 'up' and orientation != 'down' else None]

                for nx, ny in new_neighbors:
                    if valid_moves(nx, ny) and (nx, ny) not in visited:
                        queue.append(((nx, ny), path + [(nx, ny)]))
