def iterative_deepening_dfs(grid, start, goal, max_depth=float('inf')):
    def is_valid_pos(pos):
        row, col = pos
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def is_valid_move(pos1, pos2):
        dx, dy = pos2[0] - pos1[0], pos2[1] - pos1[1]
        return abs(dx) + abs(dy) == 1 and is_valid_pos(pos2)

    def dfs(pos, path, max_depth):
        if pos == goal:
            return path + [pos]
        path = path + [pos]
        if len(path) >= max_depth:
            return None
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if abs(dx) + abs(dy) == 1:
                    new_pos = pos[0] + dx, pos[1] + dy
                    if is_valid_move(path[-1], new_pos):
                        result = dfs(new_pos, path, max_depth)
                        if result is not None:
                            return result
        return None

    def iddfs(start, goal, max_depth):
        for depth in range(1, max_depth + 1):
            result = dfs(start, [start], depth)
            if result is not None:
                return result
        return []

    for depth in range(1, len(grid) * len(grid[0]) + 5):
        result = iddfs(start, goal, depth)
        if result is not None:
            return result
    return []

