def solve(grid, start, goal):
    def is_valid(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def neighbours(cell):
        row, col = cell
        return [(row-1, col), (row+1, col), (row, col-1), (row, col+1)]

    def dfs_search(grid, start, goal, visited, path):
        if start == goal:
            path.append(start)
            return path
        visited.add(start)
        for cell in neighbours(start):
            if is_valid(cell[0], cell[1]) and cell not in visited:
                result = dfs_search(grid, cell, goal, visited, path + [start])
                if result:
                    return result
        return []

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    depth = 0
    while True:
        visited = set()
        result = dfs_search(grid, start, goal, visited, [])
        if result and result[-1] == goal:
            return result
        depth += 1
        cells = set()
        for cell in result:
            cells.update(neighbours(cell))
        search_area = set(n for n in cells if dfs_search_area(grid, depth, n))
        visited.update(search_area)
        for n in set(neighbours(n) for n in visited):
            n = n[0] + 1, n[1]
            if dfs_search_area(grid, depth, n):
                search_area.add(max(list(search_area) + list(n)))
                break
        result = dfs_search(grid, search_area[0], goal, visited, [])
        if result and result[-1] == goal:
            return result


def dfs_search_area(grid, depth, cell):
    if cell in neighbours(cell):
        return grid[cell[0]][cell[1]] == '.'
    elif depth > 0:
        return any(dfs_search_area(grid, depth - 1, n) for n in neighbours(cell))
    return False

