    def is_valid_move(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[row]) and grid[row][col] != '#'

    def find_path(start, goal, depth):
        stack = [(start, [start])]
        while stack:
            (parent, path), move_index = stack.pop()
            if len(path) - 1 >= depth:
                for i in range(len(path) - 1):
                    if path[i+1][0] - path[i][0] == 1 and path[i+1][1] == path[i][1]:  # down
                        continue
                    elif path[i+1][0] - path[i][0] == -1 and path[i+1][1] == path[i][1]:  # up
                        continue
                    elif path[i+1][1] - path[i][1] == 1 and path[i+1][0] == path[i][0]:  # right
                        continue
                    elif path[i+1][1] - path[i][1] == -1 and path[i+1][0] == path[i][0]:  # left
                        continue
                    else:
                        return path
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                row, col = parent[0] + dr, parent[1] + dc
                if is_valid_move(row, col) and (row, col) != goal and (row, col) not in path:
                    stack.append(((row, col), path + [(row, col)]))
        return []

    path = find_path(start, goal, 0)
    while path and path[-1] != goal:
        path = find_path(path[-1], goal, path[-1][0] + 1)
    return path

