def solve(grid, start, goal):
    def neighbors(cell):
        x, y = cell
        yield (x - 1, y) if 0 <= x - 1 < len(grid) and grid[x - 1][y] != '#' else None
        yield (x + 1, y) if 0 <= x + 1 < len(grid) and grid[x + 1][y] != '#' else None
        yield (x, y - 1) if 0 <= y - 1 < len(grid[0]) and grid[x][y - 1] != '#' else None
        yield (x, y + 1) if 0 <= y + 1 < len(grid[0]) and grid[x][y + 1] != '#' else None

    def iterative_deepening_dfs(cell, max_depth):
        stack = [(cell, 0, [cell])]
        while stack:
            cell, depth, path = stack.pop()
            if depth > max_depth:
                max_depth += 1
                continue
            if cell == goal:
                return path
            for neighbor in neighbors(cell):
                if neighbor not in path:
                    stack.append((neighbor, depth + 1, path + [neighbor]))
        return None

    def is_valid(cell):
        return 0 <= cell[0] < len(grid) and 0 <= cell[1] < len(grid[0]) and grid[cell[0]][cell[1]] != '#'

    if start == goal and is_valid(start):
        return [start]
    if not is_valid(start) or not is_valid(goal):
        return []
    for depth in range(100):  # maximum depth is 100
        path = iterative_deepening_dfs(start, depth)
        if path:
            return path
    return []

