                if is_valid(neighbor[0], neighbor[1]) and neighbor not in path:
                    result = dfs(path + [cur], neighbor, depth + 1)
                    if result:
                        return result
            return None

        result = dfs([start], start, 0)
        return result if result else None

    if start == goal and grid[start[0]][start[1]] != '#':
        return [start]
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    result = []
    depth = 0
    while True:
        found = iddfs(depth, start, goal)
        if found:
            result = found
            break
        depth += 1
    return result if is_valid(result[-1][0], result[-1][1]) else []
