    def iterative_deepening_dfs(depth_limit, max_depth):
        for d in range(1, max_depth + 1):
            if iterative_depth_dfs(grid, start, goal, d, depth_limit):
                return True

    def iterative_depth_dfs(grid, current, goal, max_depth, depth_limit):
        if current == goal:
            return True
        if depth_limit <= 0:
            return False
        for row in range(-1, 2):
            for col in range(-1, 2):
                neighbor_row, neighbor_col = current[0] + row, current[1] + col
                if is_valid(neighbor_row, neighbor_col) and (row, col) != (0, 0):
                    if iterative_depth_dfs(grid, (neighbor_row, neighbor_col), goal, max_depth - 1, depth_limit - 1):
                        return True
        return False

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    iterative_deepening_dfs(len(grid) * len(grid[0]), len(grid) + 1)
    stack = [(start, 0)]
    path = []
    while stack:
        cell, depth = stack.pop()
        if cell == goal:
            path.append(cell)
            break
        if path and cell == path[-2]:
            path.append(cell)
