                    if is_valid(neighbor_row, neighbor_col) and (row, col) != (0, 0):
                        if (neighbor_row, neighbor_col) not in path:
                            stack.append(((neighbor_row, neighbor_col), depth + 1))
    if not path or path[-1] != goal:
        return []
    return path

