def solve(grid, start, goal):
    R, C = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    ok = lambda r, c: 0 <= r < R and 0 <= c < C and grid[r][c] != '#'

    def dfs(r, c, depth, path):
        if (r, c) == goal:
            return [path + [(r, c)]]
        if r < 0 or r >= R or c < 0 or c >= C or grid[r][c] == '#' or depth == 0:
            return []
        result = []
        for dr, dc in directions:
            r2, c2 = r + dr, c + dc
            if ok(r2, c2) and (r2, c2) not in path:
                p = dfs(r2, c2, depth - 1, path + [(r, c)])
                if p:
                    result.append(p)
        return result

    if start == goal and ok(*start):
        return [start]

    for depth in range(1, R*C):
        for r in range(R):
            for c in range(C):
                if ok(r, c) and (r, c) != start:
                    for p in dfs(r, c, depth, []):
                        yield p

    yield []

def is_valid_path(grid, path):
    if path[0] != path[-1]:
        return False
    R, C = len(grid), len(grid[0])
    for r, c in path:
        if not 0 <= r < R or not 0 <= c < C:
            return False
        if grid[r][c] == '#':
            return False
    return True

def solve(grid, start, goal):
    for path in solve(grid, start, goal):
        if is_valid_path(grid, path):
            return path
    return []

