    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]  # right, left, down, up

    def valid_move(row, col):
        if 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] != '#':
            return True
        return False

    def dfs(max_depth, current, target, seen, path):
        if (current, target) in seen:  # check for cycles in path
            return []
        seen.add((current, target))
        path.append(current)

        if current == target:
            return path

        if not seen:
            path.pop()  # backtrack
            return None

        min_row, min_col = min(seen, key=lambda x: (x[0][0], x[0][1]))
        max_row, max_col = max(seen, key=lambda x: (x[0][0], x[0][1]))

        for dr, dc in directions:
            row, col = min_row[0] + dr, min_col[1] + dc

            if valid_move(row, col):
