                if 0 <= new_row < len(grid) and 0 <= new_col < len(grid[0]) and grid[new_row][new_col] != '#':
                    for new_max_row, new_max_col in list(seen):
                        if valid_move(new_max_row + dr, new_max_col + dc) and (
                                new_row, new_col) not in seen and (
                                new_max_row + dr, new_max_col + dc) not in seen:
                            seen.add(((new_row, new_col), (new_max_row + dr, new_max_col + dc)))

                    result = dfs(max_depth + 1, (row, col), target, seen.copy(), path.copy())
                    if result:
