def solve(grid, start, goal):
    if start == goal:
        return [start]

    stack = [(start, [start])]
    max_depth = 1

    while stack:
        (x, y), path = stack.pop()

        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = x + dx, y + dy

            if (0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and
                    grid[nx][ny] != '#' and (nx, ny) not in path):
                new_depth = len(path)

                if (nx, ny) == goal or (new_depth <= max_depth and stack):
                    stack.append(((nx, ny), path + [(nx, ny)]))
                    max_depth = max(max_depth, len(path + [(nx, ny)]))
                else:
                    stack.insert(0, ((nx, ny), path + [(nx, ny)]))

        if stack:
            stack = stack[::-1]

    for cell, path in [(goal, [])]:
        if (is_valid_cell(grid, cell) and can_reach(grid, start, cell, path)):
            return path + [cell]

    return []


