               (start[0], start[1]-1)]]) and
           cell not in [(end,) + (path[:path.index(cell)] + path[path.index(cell)+1:]) for cell in 
              [(end),(end[0]+1, end[1]), (end[0]-1, end[1]), (end[0], end[1]+1), 
               (end[0], end[1]-1)]]):
            return False
    return True

