def manhattan_distance(point, goal):
    return abs(point[0] - goal[0]) + abs(point[1] - goal[1])

def heuristic(point, goal):
    return manhattan_distance(point, goal)

def get_neighbours(grid, point):
    rows, cols = len(grid), len(grid[0])
    neighbours = []
    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        x, y = point[0] + dx, point[1] + dy
        if 0 <= x < rows and 0 <= y < cols and grid[x][y] == '.':
            neighbours.append((x, y))
    return neighbours

def a_star_search(grid, start, goal):
    open_set = [(start, 0, [])]
    came_from = {}
    g_score = {start: 0}
    f_score = {start: heuristic(start, goal)}

    while open_set:
        _, current_f_score, path = min(open_set, key=lambda x: x[1])
        open_set.remove((current_f_score, path))

        if current_f_score > f_score.get(current_f_score, float('inf')):
            continue

        if current_f_score == f_score.get(current_f_score, float('inf')):
            if not path:
                path = [start]
            path += [current_f_score]

        if grid[current_f_score // len(grid[0])][current_f_score % len(grid[0])] == '.':

            if current_f_score == goal or start == goal:
                return path[1:]

            for neighbour in get_neighbours(grid, (current_f_score // len(grid[0]), current_f_score % len(grid[0]))):
                tentative_g_score = g_score[current_f_score] + 1
                if neighbour not in g_score or tentative_g_score < g_score[neighbour]:
                    came_from[neighbour] = (current_f_score, path)
                    g_score[neighbour] = tentative_g_score
                    f_score[neighbour] = tentative_g_score + heuristic(neighbour, goal)
                    open_set.append((neighbour, f_score[neighbour], []))

    return []

