from heapq import heappop, heappush
from typing import List, Tuple

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    def valid_move(x: int, y: int) -> bool:
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '.'

    neighbors = [
        (-1, 0),  # up
        (1, 0),   # down
        (0, -1),  # left
        (0, 1)    # right
    ]

    open_list = [(0, start)]
    came_from = {start: None}
    cost_so_far = {start: 0}

    while open_list:
        _, current = heappop(open_list)

        if current == goal:
            path = []
            while current is not None:
                path.append(current)
                current = came_from.get(current)
            path.reverse()
            return path

        for dx, dy in neighbors:
            x, y = current[0] + dx, current[1] + dy
            if valid_move(x, y) and (x, y) not in cost_so_far or cost_so_far[(x, y)] > cost_so_far[current] + 1:
                cost_so_far[(x, y)] = cost_so_far[current] + 1
                priority = cost_so_far[(x, y)] + abs(x - goal[0]) + abs(y - goal[1])
                heappush(open_list, (priority, (x, y)))
                came_from[(x, y)] = current

    return []

