def is_valid(grid, cell):
    return 0 <= cell[0] < len(grid) and 0 <= cell[1] < len(grid[0]) and grid[cell[0]][cell[1]] == '.'

def adjacent(grid, cell):
    return [
        (cell[0] - 1, cell[1]),
        (cell[0] + 1, cell[1]),
        (cell[0], cell[1] - 1),
        (cell[0], cell[1] + 1)
    ]

def solve(grid, start, goal):
    if start == goal:
        return [start]
    if not is_valid(grid, start) or not is_valid(grid, goal):
        return []
    open_set = [(start, 0)]
    came_from = {}
    cost_so_far = {start: 0}
    while open_set:
        current, _ = min(open_set, key=lambda x: heuristic(x[0], goal))
        if current == goal:
            return reconstruct_path(came_from, current)
        open_set.remove(current)
        for next in adjacent(grid, current):
            new_cost = cost_so_far[current] + 1
            if not is_valid(grid, next) or next in cost_so_far and new_cost >= cost_so_far[next]:
                continue
            cost_so_far[next] = new_cost
            priority = new_cost + heuristic(next, goal)
            open_set.append((next, priority))
            came_from[next] = current
    return []

def reconstruct_path(came_from, current):
    total_path = [current]
    while current in came_from:
        current = came_from[current]
        total_path.insert(0, current)
    return total_path

