def astar(grid, start, goal):
    # Helper function to check if a cell is inside the grid and is a free cell
    def inside(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '.'

    # Helper function to get the neighbours of a cell
    def get_neighbours(x, y):
        neighbours = []
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if inside(nx, ny):
                neighbours.append((nx, ny))
        return neighbours

    # Helper function to get the cost of a path from the start to a cell
    # Here, the cost is just the manhattan distance
    def heuristic(x, y):
        return abs(x - goal[0]) + abs(y - goal[1])

    # If start or goal is a wall or start equals goal, return an empty list
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#' or start == goal:
        return [start] if start == goal and grid[start[0]][start[1]] == '.' else []

    # Initialize the set of visited cells and the priority queue
    visited = set((start, 0))
    queue = [(start, 0)]

    # Initialize the dictionary to store the parent of each cell
    parent = {}

    # Loop until the queue is empty
    while queue:
        x, y = queue[0][0]
        cost = queue[0][1]
        queue = queue[1:]

        # If this is the goal, construct the path and return it
        if (x, y) == goal:
            path = []
            while (x, y) != start:
                path.append((x, y))
                x, y = parent.get((x, y))
            path.append(start)
            path.reverse()
            return path

        # Add the neighbours to the queue
        for nx, ny in get_neighbours(x, y):
            if (nx, ny) not in visited:
                queue.append(((nx, ny), cost + 1 + heuristic(nx, ny)))
                visited.add((nx, ny))
                parent[(nx, ny)] = (x, y)

    # If the loop finishes without finding the goal, return an empty list
    return []

def solve(grid, start, goal):
    # Adjust start, goal, and boundary to 1-based indexing
    start = (start[0] + 1, start[1] + 1)
    goal = (goal[0] + 1, goal[1] + 1)
    boundary = lambda row, col: row < 1 or row > len(grid) or col < 1 or col > len(grid[0])

    # Convert grid to 1-based indexing
    grid = [list(row) for row in grid]
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '#':
                grid[i][j] = 'X'

    # Define possible moves
    moves = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    # Define heuristic function
    def heuristic(cell):
        return abs(cell[0] - goal[0]) + abs(cell[1] - goal[1])

    # Run A* search
    open_list = [start]
    came_from = {}
    cost_so_far = {start: 1}
    while open_list:
        current = min(open_list, key=lambda cell: cost_so_far[cell] + heuristic(cell))
        open_list.remove(current)
        if current == goal:
            path = []
            while current in came_from:
                path.append(current)
                current = came_from[current]
            path.append(start)
            return path[::-1]

        for move in moves:
            neighbor = (current[0] + move[0], current[1] + move[1])
            if boundary(*neighbor) or grid[neighbor[0] - 1][neighbor[1] - 1] == 'X':
                continue
            new_cost = cost_so_far[current] + 1
            if neighbor in cost_so_far and new_cost >= cost_so_far[neighbor]:
                continue
            cost_so_far[neighbor] = new_cost
            priority = new_cost + heuristic(neighbor)
            open_list.append(neighbor)
            came_from[neighbor] = current

    return []

