def valid_move(grid, r, c, to_r, to_c):
    if (0 <= to_r < len(grid)) and (0 <= to_c < len(grid[0])) \
       and grid[to_r][to_c] == '.' and (to_r, to_c) != (r, c):
        return True
    return False

def heuristic(r1, c1, r2, c2):
    return abs(r1 - r2) + abs(c1 - c2)

def solve(grid, start, goal):
    start = tuple(start)
    goal = tuple(goal)
    open_list = [start]
    came_from = {}
    cost_so_far = {start: 0}
    while open_list:
        current = min(open_list, key=lambda x: cost_so_far[x] + heuristic(*x, *goal))
        if current == goal:
            path = []
            while current in came_from:
                path.append(current)
                current = came_from[current]
            path.append(start)
            path.reverse()
            return path
        open_list.remove(current)
        for r_off, c_off in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_r, new_c = current[0] + r_off, current[1] + c_off
            if valid_move(grid, *current, new_r, new_c):
                new_cost = cost_so_far[current] + 1
                if (new_r, new_c) not in cost_so_far or new_cost < cost_so_far[(new_r, new_c)]:
                    cost_so_far[(new_r, new_c)] = new_cost
                    priority = new_cost + heuristic(new_r, new_c, *goal)
                    came_from[(new_r, new_c)] = current
                    open_list.append((new_r, new_c))
    return []

