def manhattan_distance(cell1, cell2):
    return abs(cell1[0] - cell2[0]) + abs(cell1[1] - cell2[1])

def solve(grid, start, goal):
    if not grid or not grid[0] or start in [(i, j) for i, row in enumerate(grid) for j, c in enumerate(row) if c == '#'] or goal in [(i, j) for i, row in enumerate(grid) for j, c in enumerate(row) if c == '#']:
        return []
    open_list = [(0, start)]
    came_from = {}
    g_score = {start: 0}
    f_score = {start: manhattan_distance(start, goal)}
    while open_list:
        _, current = heappop(open_list)
        if current == goal:
            path = [current]
            while path[-1] in came_from:
                path.append(came_from[path[-1]])
            return path[::-1]
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            x, y = current[0] + dx, current[1] + dy
            if 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] != '#' and (x, y) not in came_from:
                new_g_score = g_score[current] + 1
                if (x, y) not in g_score or new_g_score < g_score[(x, y)]:
