def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])

    # Dictionary mapping string representations of moves to (row, col) offsets
    moves = {
        'up': (-1, 0),
        'down': (1, 0),
        'left': (0, -1),
        'right': (0, 1)
    }

    # Helper function to check if a move is valid (inside the grid, free cell, and not the reverse of the path)
    def is_valid(pos, path):
        r, c = pos
        if r < 0 or c < 0 or r >= rows or c >= cols or grid[r][c] == '#':
            return False
        return (r, c) not in path

    # Helper function to reconstruct the path from the cost heuristic (is not used here)
    def reconstruct_path(came_from, current):
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.insert(0, current)
        return path

    # A* heuristic function (in this case, just the Manhattan distance, but it's not used)
    # def heuristic(node, goal):
    #     return abs(node[0] - goal[0]) + abs(node[1] - goal[1])

    # Dictionary mapping (row, col) tuples to their cost
    came_from = {}

    # Set of (row, col) tuples
    open_set = set([start])

    def is_goal(node):
        return node == goal

    # Repeatedly select the node in open_set with the lowest cost, until the goal is reached
    while open_set:
        current = min(open_set, key=lambda x: sum(grid[r][c] != '#' for r, c in [(y + dy, x + dx) for dy, dx in moves.values() if is_valid((y + dy, x + dx), open_set)]))
        if is_goal(current):
            return reconstruct_path(came_from, current)
        open_set.remove(current)
        for move, (dr, dc) in moves.items():
            neighbor = (current[0] + dr, current[1] + dc)
            if is_valid(neighbor, open_set):
                came_from[neighbor] = current
                open_set.add(neighbor)
    return []

