from heapq import heappop, heappush

def solve(grid, start, goal):
    xstart, ystart = start
    xgoal, ygoal = goal
    if not (0 <= xstart < len(grid) and 0 <= ystart < len(grid[0]) and grid[xstart][ystart] != '#'):
        return []
    if start == goal and grid[xstart][ystart] == '.':
        return [start]
    xbound, ybound = len(grid), len(grid[0])
    cost = [{'-Up': 0, 'Down': 0, 'Left': 0, 'Right': 0} for _ in range(xbound)]
    start_cost = {'Up': 0, 'Down': 1, 'Left': 1, 'Right': 1}
    cost[xstart][ystart] = start_cost['Left'] + start_cost['Right'] + start_cost['Up'] + start_cost['Down']
    queue = [(cost[xstart][ystart], start, tp('Up', 'Down', 'Left', 'Right'))]
    while queue:
        _, (x, y), path = heappop(queue)
        if (x, y) == goal:
            return [(x,y)] + list(tp.path(path))[::-1]
        for dx, dy, direction in tp.directions(path):
            nx, ny = x + dx, y + dy
            if (0 <= nx < xbound) and (0 <= ny < ybound) and grid[nx][ny] != '#':
                new_path = path.copy()
                new_path[direction] = ''
                new_cost = cost[x][y] - start_cost[path[direction]] + cost[nx][ny]
                heappush(queue, (new_cost + 0, (nx, ny), new_path))
                cost[nx][ny] = new_cost
    return []

def tp(line):
    '''returns tuples with keys: 'Up', 'Down', 'Left', 'Right'''
    return tuple(sorted(line))

def tp_path(tp):
    '''returns list from tuples'''
    return [x for x in tp]

tp.directions = lambda self: {
        'Up': ((-1, 0), 'Up'),
        'Down': ((1, 0), 'Down'),
        'Left': ((0, -1), 'Left'),
        'Right': ((0, 1), 'Right')
    }[self[::-1].pop()]

