from heapq import heappop, heappush
from typing import List, Tuple

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    rows, cols = len(grid), len(grid[0])
    queue = [(0, list(start))]  # (cost, path)
    visited = {(start,)}
    moves = [(0, 1), (0, -1), (1, 0), (-1, 0)]  # right, left, down, up

    def valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] != '#'

    while queue:
        cost, path = heappop(queue)
        r, c = path[-1]

        if (r, c) == goal:
            return path

        for move in moves:
            new_r, new_c = r + move[0], c + move[1]
            if valid(new_r, new_c) and (new_r, new_c) not in visited:
                visited.add((new_r, new_c))
                heappush(queue, (cost + 1, path + [(new_r, new_c)]))

    return []

