    """Check if a cell is within grid bounds and not a wall."""
    return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] != '#'

def solve(grid, start, goal):
    """Find a path between two cells in a grid."""
    if start == goal or not is_valid(grid, start[0], start[1]) or not is_valid(grid, goal[0], goal[1]):
        return [start] if start == goal and is_valid(grid, start[0], start[1]) else []

    open_set = [(0, start)]
    came_from = {start: None}
    g_score = {start: 0}

    while open_set:
        current = min(open_set, key=lambda cell: (g_score[cell], cell))
        if current == goal:
            path = []
            while current:
                path.append(current)
                current = came_from[current]
            return path[::-1]

        open_set.remove(current)
        for row in [current[0] - 1, current[0] + 1, current[0], current[0]]:
            for col in [current[1] - 1, current[1] + 1]:
                neighbor = (row, col)
                if is_valid(grid, row, col) and neighbor not in g_score:
                    g_score[neighbor] = float('inf')
                if is_valid(grid, row, col) and g_score[neighbor] > g_score[current] + 1:
