from heapq import heappop, heappush

def valid_move(grid, row, col):
    return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

def solve(grid, start, goal):
    if start == goal:
        return [start]
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]

    start_row, start_col = start
    dist_from_start = [[float('inf')]*cols for _ in range(rows)]
    comes_from = [[None]*cols for _ in range(rows)]
    dist_from_start[start_row][start_col] = 0
    priority_queue = [(0, start_row, start_col)]

    while priority_queue:
        _, row, col = heappop(priority_queue)

        if (row, col) == goal:
            path = []
            while (row, col) is not None:
                path.append((row, col))
                row, col = comes_from[row][col]
            return path[::-1]

        if visited[row][col]:
            continue

        visited[row][col] = True

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            next_row, next_col = row + dr, col + dc

            if valid_move(grid, next_row, next_col):
                new_dist = dist_from_start[row][col] + 1
                if new_dist < dist_from_start[next_row][next_col]:
                    dist_from_start[next_row][next_col] = new_dist
                    comes_from[next_row][next_col] = (row, col)
                    heappush(priority_queue, (new_dist, next_row, next_col))

    return []

from heapq import heappop, heappush

def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    rows, cols = len(grid), len(grid[0])
    distances = {(i, j): float('inf') for i in range(rows) for j in range(cols)}
    distances[start] = 0
    queue = [(0, start, set())]
    while queue:
        priority, (row, col), visited = heappop(queue)
        if (row, col) == goal:
            path = [(row, col)]
            while (row, col) != start:
                if row > 0 and (row - 1, col) not in visited:
                    row -= 1
                elif col > 0 and (row, col - 1) not in visited:
                    col -= 1
                else:
                    return []
                visited.add((row, col))
                path.append((row, col))
            return path[::-1]
        if (row, col) in visited:
            continue
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            r, c = row + dr, col + dc
            if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.':
                distance = distances[(row, col)] + 1
                if distance < distances.get((r, c), float('inf')):
                    distances[(r, c)] = distance
                    heappush(queue, (distance + abs(r - goal[0]) + abs(c - goal[1]), (r, c), visited | {(row, col)}))
    return [] if distances[goal] != float('inf') else []

