def solve(grid, start, goal):
    def h(cell):
        """Heuristic function. Manhattan distance."""
        return abs(cell[0] - goal[0]) + abs(cell[1] - goal[1])

    def successors(cell):
        """Return a list of all successors of a given cell."""
        row, col = cell
        neighbours = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            r, c = row + dr, col + dc
            if (0 <= r < len(grid) and 0 <= c < len(grid[0]) and
                grid[r][c] == '.' and (r, c) != goal):
                neighbours.append((r, c))
        return neighbours

    def dijkstra(start):
        """Dijkstra's algorithm with unit weights."""
        queue = [(start, h(start))]
        explored = set()
        came_from = {start: None}
        cost_so_far = {start: 0}
        while queue:
            _, current_priority = min(queue)
            current_cell, _ = min(queue)
            queue.remove((current_cell, current_priority))
            if current_cell == goal:
                break
            if current_cell in explored:
                continue
            explored.add(current_cell)
            for successor in successors(current_cell):
                new_cost = cost_so_far[current_cell] + 1
                if successor not in cost_so_far or new_cost < cost_so_far[successor]:
                    cost_so_far[successor] = new_cost
                    priority = new_cost + h(successor)
                    queue.append((successor, priority))
                    came_from[successor] = current_cell
        if goal not in came_from:
            return []
        path = []
        current_cell = goal
        while current_cell is not None:
            path.append(current_cell)
            current_cell = came_from.get(current_cell)
        return path[::-1]

    if grid[start[0]][start[1]] != '.' or grid[goal[0]][goal[1]] != '.':
        return []
    return dijkstra(start) if start != goal else [start]
