def solve(grid, start, goal):
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    rows, cols = len(grid), len(grid[0])
    visited = set()
    came_from = {}

    def is_valid(cell):
        r, c = cell
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def get_neighbours(cell):
        r, c = cell
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid((nr, nc)):
                yield (nr, nc)

    def heuristic(cell):
        return abs(cell[0] - goal[0]) + abs(cell[1] - goal[1])

    pq = [(0, start)]
    while pq:
        _, current = min(pq)
        pq.remove(min(pq))
        if current == goal:
            path = []
            while current in came_from:
                path.append(current)
                current = came_from[current]
            path.append(start)
            return list(reversed(path))

        visited.add(current)
        for neighbour in get_neighbours(current):
            if neighbour not in visited:
                came_from[neighbour] = current
                new_node_value = 1 + heuristic(neighbour)
                flag = all(heuristic(neighbour) + 1 + heuristic(cell) < new_node_value
                           for cell in get_neighbours(neighbour) if cell in came_from)
                if flag:
                    pq.append((new_node_value, neighbour))
    return []

