import heapq

def solve(grid, start, goal):
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    directions = [(0, -1), (0, 1), (-1, 0), (1, 0)]
    rows, cols = len(grid), len(grid[0])
    visited = [[{} for _ in range(cols)] for _ in range(rows)]

    def heuristic(node):
        dr, dc = node[0] - goal[0], node[1] - goal[1]
        return dr * dr + dc * dc

    def reconstruct(path, node):
        if not path or node not in path:
            return path
        for next_node in path[node]:
            if grid[next_node[0]][next_node[1]] != '#':
                if node == start:
                    return [node] + reconstruct(path, next_node)
                else:
                    return reconstruct([node] + path[node][next_node], next_node)

    queue = [(0, start, {})]
    while queue:
        cost, node, path = heapq.heappop(queue)
        dr, dc = node[0] - start[0], node[1] - start[1]
        if node == goal:
            return reconstruct(path, node)
        if node in path:
            continue
        for dr, dc in directions:
            r, c = node[0] + dr, node[1] + dc
            if (r < 0 or c < 0 or r >= rows or c >= cols or
                    grid[r][c] == '#' or (r, c) in path):
                continue
            next_node = (r, c)
            total_cost = cost + min(visited[r][c].get(next_node, float('inf')), 1)
            visited[r][c][next_node] = total_cost
            heapq.heappush(queue, (total_cost + heuristic(next_node), next_node,
                                  {next_node: node}))
    return []

