from typing import List, Tuple
from collections import deque

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    def is_valid(row: int, col: int) -> bool:
        """Check if cell at (row, col) is within the grid and free."""
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def neighbours(cell: Tuple[int, int]) -> List[Tuple[int, int]]:
        """Return a list of all valid neighbours of a given cell."""
        row, col = cell
        neighbours = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            r, c = row + dr, col + dc
            if is_valid(r, c):
                neighbours.append((r, c))
        return neighbours

    if is_valid(*start) and is_valid(*goal) and start != goal:
        frontier = deque([start])
        came_from = {start: None}
        cost_so_far = {start: 0}
        while frontier:
            current = frontier.popleft()
            if current == goal:
                path = []
                while current:
                    path.append(current)
                    current = came_from[current]
                return path[::-1]
            for next in neighbours(current):
                new_cost = cost_so_far[current] + 1
                if next not in cost_so_far or new_cost < cost_so_far[next]:
                    cost_so_far[next] = new_cost
                    priority = new_cost + heuristic(goal, next)
                    frontier.append(next)
                    came_from[next] = current
        return []
    elif is_valid(start) and start == goal:
        return [start]
    else:
        return []

def heuristic(a: Tuple[int, int], b: Tuple[int, int]) -> int:
    """Manhattan distance heuristic (L1)."""
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

