def solve(grid, start, goal):
    assert 1 <= len(grid) <= 30 and 1 <= len(grid[0]) <= 30, "Grid size is out of range"
    assert 0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]), "Start position is out of range"
    assert 0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0]), "Goal position is out of range"
    assert grid[start[0]][start[1]] != '#' and grid[goal[0]][goal[1]] != '#', "Start or goal position is a wall"

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def valid_move(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    open_set = [(start, 0)]
    came_from = {}
    cost_so_far = {start: 0}

    while open_set:
        _, current_cost = min(open_set, key=lambda x: x[1])
        current, _ = next(x for x in open_set if x[1] == current_cost)

        if current == goal:
            path = []
            while current:
                path.insert(0, current)
                current = came_from.get(current)
            return path or [start]

        open_set.remove((current, current_cost))

        for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            neighbor = current[0] + dr, current[1] + dc

            if valid_move(*neighbor):
                new_cost = cost_so_far[current] + 1
                if neighbor not in cost_so_far or new_cost < cost_so_far[neighbor]:
                    cost_so_far[neighbor] = new_cost
                    priority = new_cost + heuristic(neighbor, goal)
                    open_set.append((neighbor, priority))
                    came_from[neighbor] = current

    return []

