from heapq import heappop, heappush

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    visited = [[False for _ in range(cols)] for _ in range(rows)]

    if start == goal:
        return [start]

    def is_valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] != '#'

    def get_distance(node):
        return node[0]

    def get_priority(node):
        return (get_distance(node), node[1], node[0])

    queue = [(get_priority(start), start)]
    parent = {start: None}
    while queue:
        distance, node = heappop(queue)
        distance -= get_distance(node)
        if node == goal:
            path = []
            while node:
                path.append(node)
                node = parent[node]
            return path[::-1]

        x, y = node
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and not visited[nx][ny]:
                visited[nx][ny] = True
                heappush(queue, (get_priority((nx, ny)), (nx, ny)))
                parent[(nx, ny)] = node

    return []

