from heapq import heappop, heappush
from typing import List, Tuple

def neigbours(coord: Tuple[int, int], grid: List[str]) -> List[Tuple[int, int]]:
    """Get all valid neigbours of a cell."""
    row, col = coord
    for dr in [-1, 0, 1]:
        for dc in [-1, 1]:
            r, c = row + dr, col + dc
            if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.':
                yield (r, c)

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    """Find a path between two cells of a grid."""
    if start == goal:
        return [start]
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    seen = {(start, 0)}
    heap = [(0, [start])]
    while heap:
        (cost, path) = heappop(heap)
        for coord in neigbours(path[-1], grid):
            if coord == goal:
                return path + [coord]
            if coord not in [p[-1] for p in seen]:
                seen.add((coord, cost + 1))
                heappush(heap, (cost + 1, path + [coord]))

    return []

