def solve(grid, start, goal):
    # helper to get the neighbors of a cell
    def get_neighbors(row, col):
        neighbors = []
        for r, c in [(row-1, col), (row+1, col), (row, col-1), (row, col+1)]:
            if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] != '#':
                neighbors.append((r, c))
        return neighbors

    # helper to calculate the heuristic value (Manhattan distance) of a cell
    def heuristic(row, col):
        return abs(row - goal[0]) + abs(col - goal[1])

    # helper to print the path
    def print_path(path):
        if path:
            print('[', end='')
            for i, (row, col) in enumerate(path):
                if i: print(', ', end='')
                print('(%d, %d)' % (row, col), end='')
            print(']')

    # helper to check if a cell can be added to the path
    def can_add(cell):
        for row, col in path[:-1]:
            if abs(row - cell[0]) + abs(col - cell[1]) != 1:
                return False
        return grid[cell[0]][cell[1]] == '.'

    # check preconditions
    if start == goal and grid[start[0]][start[1]] != '#':
        return [start]
    if start == goal or start[0] < 0 or start[0] >= len(grid) or start[1] < 0 or start[1] >= len(grid[0]) or grid[start[0]][start[1]] == '#':
        return []
    if goal[0] < 0 or goal[0] >= len(grid) or goal[1] < 0 or goal[1] >= len(grid[0]) or grid[goal[0]][goal[1]] == '#':
        return []

    # reconstruct path from goal using backtracking
    def reconstruct(path, cell):
        if cell == start:
            return path
        for neighbor in get_neighbors(cell[0], cell[1]):
            if can_add(neighbor):
                return reconstruct(path + [neighbor], neighbor)

    # simulate Dijkstra
    explored = set()
    path = [start]
    explored.add(tuple(start))
    d = {tuple(start): 0}
    pq = [(0, tuple(start))]

    while pq:
        _, cell = heappop(pq)

        if cell == goal:
            return reconstruct(path, cell)

        for neighbor in get_neighbors(cell[0], cell[1]):
            distance = d[tuple(cell)] + 1 + heuristic(neighbor[0], neighbor[1])
            if tuple(neighbor) not in d or distance < d[tuple(neighbor)]:
                d[tuple(neighbor)] = distance
                priority = distance + heuristic(neighbor[0], neighbor[1])
                heappush(pq, (priority, tuple(neighbor)))
                explored.add(tuple(neighbor))

    return []

