        for v, w in graph[u]:
            new_dist = dist[u] + w
            if new_dist < dist[v]:
                dist[v] = new_dist
                predecessor[v] = u
                heapq.heappush(pq, (new_dist, v))

    return 0 if dist[t] != float('inf') else -1

