        neighbors.append((v, w))
    return neighbors

def dijkstra_shortest_length(n, edges_from, start):
    dist = [float('inf')] * n
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if dist[u] != float('inf'):
            continue
        dist[u] = d
        for v, w in get_neighbors(u, edges_from):
            if is_valid(v, n) and dist[v] == float('inf'):
                heapq.heappush(pq, (d + w, v))
    return dist

def bidirectional_dijkstra(n, edges, s, t):
    edges_from, edges_to = [], []
    for u, v, w in edges:
        edges_from.append((u, v, w))
        edges_to.append((v, u, w))

    dist_from_s, dist_to_t = dijkstra_shortest_length(n, edges_from, s), dijkstra_shortest_length(n, edges_to, t)
    i, j = s, t
    min_dist = 0
    while i >= 0 and j >= 0:
        if dist_from_s[i] + dist_to_t[j] < min_dist:
            min_dist = dist_from_s[i] + dist_to_t[j]
        if dist_from_s[i] <= dist_to_t[j]:
            j -= 1
        else:
            i += 1
    return min_dist if min_dist <= 100 * n else -1

