def solve(n, edges, s, t):
    class Graph:
        def __init__(self, n):
            self.reverse = [[] for _ in range(n)]
            self.adj = [[] for _ in range(n)]
            self.inf = float('inf')

        def add_edge(self, u, v, w):
            self.adj[u].append((v, w))
            self.reverse[v].append((u, w))

        def distance(self, node):
            return [self.inf] * n

        def optimized_dijkstra(self, s):
            d = self.distance(s)
            pq = [(0, s)]
            while pq:
                distि, u = heapq.heappop(pq)
                if dist_ < d[u]:
                    continue
                d[u] = dist_
                for v, w in self.adj[u]:
                    if d[v] > d[u] + w:
                        d[v] = d[u] + w
                        heapq.heappush(pq, (d[v], v))
            rev_d = [float('inf')] * n
            pq = [(0, s)]
