import heapq

def solve(n, edges, s, t):
    distance_to = [-1] * n
    distance_from = [-1] * n
    distance_to[s] = 0

    que_to = [(0, s)]
    que_from = [(distance_to[s], s)]

    while que_to:
        d, u = heapq.heappop(que_to)
        if distance_to[u] != d: continue
        for v, w in edges:
            if v == u:
                continue
            new_d = d + w
            if distance_to[v] == -1 or new_d < distance_to[v]:
                distance_to[v] = new_d
                heapq.heappush(que_to, (new_d, v))

    while que_from:
        d, u = heapq.heappop(que_from)
        if distance_from[u] != -1 and distance_from[u] != d: continue
        if u == t:
            return d
        distance_from[u] = d
        for v, w in reversed(edges):
            if v == u:
                continue
            new_d = d + w
            prev_w = -1
            for i, (x, y, q) in enumerate(edges):
                if y == v and x == u:
                    prev_w = q
                    edges[i] = (v, x, q)
                    break
            if prev_w == -1:
                return -1
            new_d -= prev_w
            if distance_from[v] == -1 or new_d < distance_from[v]:
                distance_from[v] = new_d
                heapq.heappush(que_from, (new_d, v))

    return -1

