import heapq
from collections import defaultdict

def solve(n, edges, s, t):
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = [float('inf')] * n
    prev = [None] * n
    dist[s] = 0

    pq = [(0, s)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                prev[v] = u
                heapq.heappush(pq, (dist[v], v))

    if dist[t] == float('inf'):
        return -1
    dist tempt = dist

    dist = [float('inf')] * n
    dist[t] = 0

    pq = [(0, t)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                prev[v] = u
                heapq.heappush(pq, (dist[v], v))

    for i in range(n):
        if i != t and dist[i] < tempt[i]:
            return -1

    path = [t]
    while path[-1] != s:
        path.append(prev[path[-1]])
    return sum(graph[path[i]][0][1] for i in range(len(path) - 1))

