import heapq

def solve(n, edges, s, t):
    def add_edge(graph, u, v, w):
        graph[u].append((v, w))
        graph[v].append((v, float('inf')))
    def dijkstra(graph, s):
        dist = [float('inf')] * n
        dist[s] = 0
        pq = [(0, s)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            for v, w in graph[u]:
                if d + w < dist[v]:
                    dist[v] = d + w
                    heapq.heappush(pq, (dist[v], v))
        return dist

    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        add_edge(graph, u, v, w)

    # Base case: s equals t
    if s == t:
        return 0

    dist1 = dijkstra(graph, s)  # From s to all nodes
    add_edge(graph, t, s, 0)   # Add edge from t to s
    dist2 = dijkstra(graph, t)  # From t to all nodes
    reverse_graph = [[] for _ in range(n)]
    for u, edge in enumerate(graph):
        for v, w in edge:
            reverse_graph[v].append((u, w))

    # Remove edge from t to s
    reverse_graph[s] = [(v, w) for v, w in reverse_graph[s] if v != t]

    dist2[t] = 0  # Add s to 0 to pretend to have a neg weight path
    dist3 = dijkstra(reverse_graph, t)  # From t to all nodes

    res = float('inf')
    for node in range(n):
        if node == t:
            continue
        res = min(res, dist1[s] + dist2[node] + dist3[node])

    return -1 if res == float('inf') else res

