def solve(n, edges, s, t):
    INF = float('inf')
    directs = [[] for _ in range(n)]
    indirects = [[] for _ in range(n)]

    for u, v, w in edges:
        directs[u].append((w, v))

    for u, v, w in edges:
        indirects[v].append((w, u))

    def dijkstra(Original, Incrmb):
        pq = [(0, s)]
        distance = [[INF]*(n+1) for _ in range(2)]
        explored = [False]*n

        distance[0][s] = 0
        newnode = [False] * n
        while pq:
            d, u = heapq.heappop(pq)
            if not explored[u]:
                explored[u] = True
                newnode[u] = True
                for d, v in Original[u]:
                    if not explored[v]:
                        heapq.heappush(pq, (d+distance[0][u], v))
                        distance[1][v] = distance[0][u] + d
                        if newnode[v]:
