        while pq:
            d, u = heapq.heappop(pq)
            if d < dist[u]:
                while edges[u]:
                    v, w = edges[u].pop(0)
                    if dist[u] + w < dist[v]:
                        dist[v] = dist[u] + w
                        prev[v] = u
                        heapq.heappush(pq, (dist[v], v))
                dist[u] = inf
                edges[u].clear()

    forward_heap(graph, forward_dist, forward_prev)

