from heapq import heappop, heappush

class Dijkstra:
    def __init__(self, n):
        self.n = n
        self.distance = [float('inf')] * n
        self.in_queue = [True] * n

    def solve(self, edges, s, t):
        heap = [(0, s)]
        while heap:
            dist, node = heappop(heap)
            if self.in_queue[node]:
                self.in_queue[node] = False
                if node == t:
                    return dist
                if dist < self.distance[node]:
                    self.distance[node] = dist
                    for u, v, w in edges:
                        if u == node:
                            heappush(heap, (dist + w, v))
        return -1

def solve(n, edges, s, t):
    dijkstra = Dijkstra(n)
    return dijkstra.solve(edges, s, t)

