        neighbors = get_neighbors(current_node)

        for neighbor, edge in neighbors.items():
            edge_distances = [d + ww for d, (_, ww) in enumerate(edge)]
            shortest_ww = min(edge_distances, key=lambda x: shortest_path_lengths.get((current_node, neighbor), x))
