    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    dijkstra = [(0, s, [])]
    seen = set()
    shortest_dist = [float('inf')] * n
    shortest_path = [None] * n

    while dijkstra:
