import heapq

def solve(n, edges, s, t):
    path_length_from_s = [ float('inf') ] * n
    path_length_from_t = [ float('inf') ] * n

    path_length_from_s[s] = 0
    queue1 = [(0, s)]
    while queue1:
        length, node = heapq.heappop(queue1)
        if node == t:
            break
        while node < n and length < path_length_from_s[node]:
            neighbors = [(w, i, node, i) for w, i, node, _ in edges if i == node]
            for w, neighbor, _, _ in neighbors:
                if path_length_from_s[neighbor] > path_length_from_s[node] + w:
                    path_length_from_s[neighbor] = path_length_from_s[node] + w
                    heapq.heappush(queue1, (path_length_from_s[neighbor], neighbor))

    if path_length_from_s[t] == float('inf'):
        return -1

    path_length_from_t[t] = 0
    queue2 = [(0, t)]
    while queue2:
        length, node = heapq.heappop(queue2)
        if node == s:
            break
        while node < n and length < path_length_from_t[node]:
            neighbors = [(w, i, node, i) for w, i, node, _ in edges if i == node]
            for w, neighbor, _, _ in neighbors:
                if path_length_from_t[neighbor] > path_length_from_t[node] + w:
                    path_length_from_t[neighbor] = path_length_from_t[node] + w
                    heapq.heappush(queue2, (path_length_from_t[neighbor], neighbor))

    return path_length_from_s[t]

def get_reverse_stop	node, u, v):
    if u in (v, node):
	  return v
    elif v in (node, u):
	 return u
    return None

def edges_total_weight(edges):
    return sum((w for u, v, w in edges), 0)

def edges_offsets(edges):
    offsets = [0] * (max(max(u, v) for u, v, w in edges) + 1)
    for u, v, w in edges:
        offsets[u] += 1
        offsets[v + 1] -= 1
    for i in range(1, len(offsets)):
        offsets[i] += offsets[i - 1]
    return offsets

def get_graph(edges):
    offsets = edges_offsets(edges)
    graph = [ [] for _ in range(len(offsets) - 1) ]
    for u, v, w in edges:
        for i in range(offsets[u], offsets[u + 1]):
            graph[i].append((v, w))
    return graph

