def solve(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = [float('inf')] * n
    dist[s] = 0

    pq = [(0, s)]
    seen = set()

    while pq:
        cur_dist, cur_node = heapq.heappop(pq)

        if cur_node in seen:
            continue
        seen.add(cur_node)

        if cur_node == t:
