import sys
import heapq

def solve(n, edges, s, t):
    INF = sys.maxsize>>1
    dist = [INF]*n
    dist[s] = 0

    pq = [(0, s)]  # (weight, node)
    seen = [False]*n

    while pq:
        d, u = heapq.heappop(pq)
        if seen[u]: continue
        seen[u] = True
        for v, w in edges:
            if v == u:
                heapq.heappush(pq, (d+w, v))
            elif v in edges[u]:
                if d+w < dist[v]:
                    dist[v] = d+w
                    heapq.heappush(pq, (dist[v], v))

    return dist[t] if seen[t] else -1

