    def add_edge(edges, s, t, w):
        for edge in edges:
            if edge[0] == s and edge[1] == t:
                edge[2] = min(edge[2], w)
                return
        edges.append((s, t, w))

    def popsورن_not_push(edges, u):
        for i in range(len(edges) - 1, -1, -1):
            if edges[i][0] == u:
                edges.pop(i)
                return

    def popsورن_push(edges, u):
        for i in range(len(edges) - 1, -1, -1):
            if edges[i][0] == u:
                popped = edges.pop(i)
                edges.append(popped)
                return

    shortest_distances = [float('inf')] * n
    shortest_distances[s] = 0

    in_bucket = set()
    edges_in_bucket = []

    edges.sort(key = lambda x: x[2])

    pq = queue.PriorityQueue()
    pq.put((0, s))

    while not pq.empty():
        d, u = pq.get()

        if d > shortest_distances[u]:
            continue
        for v, w in ((v, w) for u_, v, w in edges if u_ == u):
            if shortest_distances[v] > shortest_distances[u] + w:
                shortest_distances[v] = shortest_distances[u] + w
                if v not in in_bucket:
                    adds = [edge for edge in edges if edge[1] == v]
                    popsورن_not_push(edges, u)
                    edges_in_bucket.append(adds)
                    in_bucket.add(v)
                    pq.put((shortest_distances[v], v))
        in_bucket.remove(u)

        for add in edges_in_bucket:
            for edge in add:
                popsورن_push(edges, u)
                add_twice = (edge[1], edge[0], edge[2])
                if add_twice not in edges:
                    add_edge(edges, edge[1], edge[0], edge[2])
        edges_in_bucket.clear()

    return shortest_distances[t] if shortest_distances[t] != float('inf') else -1

