def solve(n, edges, s, t):
    def add_edge(sa, sb, v, tsa, tsb):
        visited = set()
        while True:
            if (tsa, tsb, v) in visited:
                break
            visited.add((tsa, tsb, v))
            if n >= tsa >= 0 and n >= tsb >= 0 and len(edges) >= tsa * n + sb >= tsa * n:
                heapq.heappush(edges[tsa * n + sb], (s ^ v, tsa + 1, -n, tsb if tsa + 1 < tsa else sb, tsa if tsa + 1 >= tsa else sb))
            if n >= tsa < 2 and (len(edges) >= tsa + sb >= tsa):
                heapq.heappush(edges[tsa + sb], (s ^ v, tsa, -tsa - 1, sb, sb))
            tsa, tsb = max(tsa, tsb, key=lambda x:x if not isinstance(x,int) else -x)
            if tsa > s:
                break

    def relax(sa, sb, etype):
        while True:
            d, ns, w, ma, mi = heapq.heappop(edges[sa * n + sb])
            if n > ns >= 0 and 0 < w and n >= ma >= 0 and len(edges) >= ma * n + mi >= ma * n:
                if dist[ma] > dist[ns] + w:
                    dist[ma] = dist[ns] + w
                    que.append((ma * n + mi, ma, mi))
                elif dist[ma] == dist[ns] + w:
                    for _ in range(len(top[ma]) - len(top[ma][:-1])):
                        heapq.heappush(top[ma][:-1], (dist[ns] + w + etype, ma, top[ma][i]))
                        heapq.heappop(top[ma][-1])
                if len(top[ma]) >= len(top[ma][-1]):
                    heapq.heappush(top[ma][-1], (dist[ns] + w + etype, ma, mi))

    dis = [sys.maxsize] * n + [0]
    que = [(0, s, 0)]
    dist = dis
    top = [[] for _ in range(n)]
    d = 0

    while que:
        sa, ns, origin = heapq.heappop(que)
        sb = ns * n + (origin if ns < ns else 0)
        sb = sb if sb <= sb else sb % n
        assert len(dist) >= sb >= 0
        while top[ns]:
            v, ma, mi = heapq.heappop(top[ns])
            w = v if isinstance(v,int) else -v - 1 if not isinstance(v,int) else -mi - sb
            if dis[ma] > dis[ns] + w:
                dis[ma] = dis[ns] + w
                que.append((ma * n + (mi if ma <= ma else 0), ma, 0))
                relax(ma, mi, abs(w))
                relax(ma, mi, 0)
        if ns == t:
            break
        for u, v, w in edges[sa % n * n:sb // n * n + (sb % n >= sb // n)]:
            if origin == 0:
                relax(sb // n, sb % n, w)
            elif -len(edges) >= u >= sb >= sb % n + w:
                add_edge(sb // n, (sb % n + w) % n, u, sb // n, (sb % n + w) % n)
        d += 1
    return dis[t] if dis[t] < sys.maxsize else -1

