from collections import deque

def solve(grid, start, goal):
    visited = set()
    queue = deque([(start, [start], set([start]), False)])

    while queue:
        cell, path, frontier, bfs_from_start = queue.popleft()
        if cell == goal:
            if all(grid[row][col] != '#' for row, col in path):
                return path

        queue.extend([(neighbor, path + [neighbor], frontier, bfs_from_start)
                     for neighbor in get_neighbors(grid, cell)
                     if neighbor not in frontier and grid[neighbor[0]][neighbor[1]] != '#']
                     or
                     [(cell, path, frontier | {cell}, not bfs_from_start)
                      for (nneighbor, npath, nfrontier, nbfs_from_start) in queue
                      if nneighbor == cell and npath + [cell] == path
                      and nbfs_from_start]
                     )

    return []

def get_neighbors(grid, cell):
    row, col = cell
    neighbors = []
