def solve(grid, start, goal):
    R, C = len(grid), len(grid[0])

    def is_valid(r, c):
        return 0 <= r < R and 0 <= c < C and grid[r][c] == '.'

    def get_neighbors(cell):
        r, c = cell
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            r2, c2 = r + dr, c + dc
            if is_valid(r2, c2):
                neighbors.append((r2, c2))
        return neighbors

    def get_frontier(start, visited, premising):
        frontier = [start]
        path = {}
        while frontier:
            cell = frontier.pop(0)
            if cell not in visited:
                visited.add(cell)
                premising.add(cell)
                path[premising.pop()] = cell
                for neighbor in get_neighbors(cell):
                    if neighbor not in visited:
                        frontier.append(neighbor)
                        premising.add(neighbor)
                        path[neighbor] = cell
        return path, visited

    if start == goal:
        return [start]

    start_visited, start_premising = set(), set()
    goal_visited, goal_premising = set(), set()

    start_path, start_visited = get_frontier(start, start_visited, start_premising)
    goal_path, goal_visited = get_frontier(goal, goal_visited, goal_premising)

    if start_path is None or goal_path is None:
        return []

    intersection = set(start_path.keys()) & set(goal_path.keys())
    if not intersection:
        return []

    start_cell, goal_cell = next(iter(intersection))
    end_path = [goal_cell]
    while end_path[-1] != start_cell:
        end_path.append(goal_path[end_path[-1]])
    end_path = end_path[::-1]
    return end_path

