def solve(grid, start, goal):
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    rows, cols = len(grid), len(grid[0])
    start, goal = tuple(start), tuple(goal)

    def is_valid(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def bfs(start, end):
        frontier = deque([start])
        visited = set([start])

        while frontier:
            pos = frontier.popleft()
            if pos == end:
                path = [pos]
                while path[-1] != start:
                    path.append(list(path[-1] - offset + start))
                return path[::-1]
            for dr, dc in directions:
                r, c = pos[0] + dr, pos[1] + dc
                if is_valid((r, c)) and (r, c) not in visited:
                    frontier.append((r, c))
                    visited.add((r, c))

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    if start == goal or goal == '.' or start == '.':
        return []

    if not grid[start[0]][start[1]] == '.' or not grid[goal[0]][goal[1]] == '.':
        return []

    offset = (start[0], start[1])
    if bfs(start, goal) and bfs(goal, start):
        intersection = set(bfs(start, goal)) & set(bfs(goal, start))
        if intersection:
            s_path = bfs(start, goal)
            goal_pos = s_path[s_path.index(tuple(intersection.pop())) + 1]
            g_path = bfs(goal, start)
            start_pos = g_path[g_path.index(tuple(intersection.pop())) - 1]
            return s_path + [tuple(path) for path in g_path[g_path.index(start_pos):]]

