    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] != '#'):
        return []
    if start == goal:
        return [start]
    rows, cols = len(grid), len(grid[0])
    frontiers = [set([start]), set([goal])]
    visited = {start}
    while frontiers[0] and frontiers[1]:
        start_frontier = list(frontiers[0]).pop()
        del frontiers[0]
        frontiers.append(list(frontiers[1]).pop())
        del frontiers[1]
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            r, c = start_frontier[0] + dr, start_frontier[1] + dc
            if (0 <= r < rows and 0 <= c < cols and grid[r][c] != '#' and (r, c) not in visited):
                if (r, c) in frontiers[1]:
                    path = get_path(start_frontier, (r, c))
                    return [(r, c)] + path
                visited.add((r, c))
                frontiers[0].add((r, c))
    return []

def get_path(node, goal):
    path = []
    while node != goal:
        path.append(node)
        node = get_parent(goal, node)
    path.append(goal)
    return path[::-1]

def get_parent(node, child):
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        r, c = node[0] + dr, node[1] + dc
        if (r, c) in children and children[(r, c)].pop() == child:
            children[(r, c)].add(node)
            return (r, c)
    return None

children = {}
for r in range(len(grid)):
    for c in range(len(grid[0])):
