from collections import deque

def get_neighbours(grid, row, col):
    rows, cols = len(grid), len(grid[0])
    for r, c in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        new_row, new_col = row + r, col + c
        if 0 <= new_row < rows and 0 <= new_col < cols and grid[new_row][new_col] == '.':
            yield new_row, new_col

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])

    # Checks for passability
    if start in get_neighbours(grid, *goal) or goal in get_neighbours(grid, *start) or start == goal:
        return [start] if start == goal else [start, goal]
    if start == goal or grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # Bidirectional BFS
    seen1, seen2 = set([start]), set([goal])
    explorers = [(deque([start]), get_neighbours(grid, *start)), (deque([goal]), get_neighbours(grid, *goal))]
    while explorers[0][0] and explorers[1][0]:
        new_frontiers = []
        for front, neighbours in zip(explorers, explorers[::-1]):
            if front[0]:
                new_frontiers.append((front[0].popleft(), neighbours))
            if front[0]:
                v = front[0].popleft()
                if v not in seen1:
                    for u in neighbours:
                        if u not in seen1 and u not in seen2:
                            seen1.add(v)
                            seen1.add(u)
                            it = iter(neighbours)
                            next(it)
                            new_frontiers += [(deque([u]), it)]
                    return list(path | path[::-1][::-1]) if (path := front[0]) and (pathb := next(explorers[1][0])) and v == pathb[0].popleft() else []
        new_frontiers = list(zip(*new_frontiers))
        explorers = new_frontiers
    return []

