from collections import deque

def solve(grid, start, goal):
    if start == goal:
        return [start]
    num_rows, num_cols = len(grid), len(grid[0])
    walls = set((r, c) for r, row in enumerate(grid) for c, val in enumerate(row) if val == '#')
    if start in walls or goal in walls:
        return []

    def neighbors(pos):
        r, c = pos
        return [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]

    def frontier_pos(frontier, visited, pos, step, path):
        return not frontier[pos]

    def expand(left_frontier, right_frontier):
        if not left_frontier:
            return right_frontier
        if not right_frontier:
            return left_frontier
        new_left_frontier = {}
        for pos, path in left_frontier.items():
            new_left_frontier[pos] = path
            for next_pos in neighbors(pos):
                if next_pos not in right_frontier and next_pos not in new_left_frontier and not frontier_pos(right_frontier, set(), next_pos, 1, path + [next_pos]):
                    new_left_frontier[next_pos] = path + [next_pos]
        new_right_frontier = {}
        for pos, path in right_frontier.items():
            new_right_frontier[pos] = path
            for next_pos in neighbors(pos):
                if next_pos not in left_frontier and next_pos not in new_right_frontier and not frontier_pos(left_frontier, set(), next_pos, 1, path + [next_pos]):
                    new_right_frontier[next_pos] = path + [next_pos]
        return expand(new_left_frontier, new_right_frontier)

    def bfs(start_pos):
        frontier = {start_pos: [start_pos]}
        visited = set([start_pos])
        while frontier:
            new_frontier = {}
            for pos, path in frontier.items():
                for next_pos in neighbors(pos):
                    if next_pos == goal:
                        return path + [next_pos]
                    if (next_pos not in visited and next_pos not in new_frontier and frontier_pos(frontier, visited, next_pos, step := step + 1, path + [next_pos])):
                        new_frontier[next_pos] = path + [next_pos]
            frontier = new_frontier
            visited.update(frontier.keys())
        return None

    left_frontier = {start: [start]}
    right_frontier = {goal: [goal]}
    result = bfs(start)
    if result:
        return result
    return expand(left_frontier, right_frontier)

