from collections import deque

def solve(grid, start, goal):
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if start == goal or grid[start[0]][start[1]] == '#':
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    queue1 = deque([[*start]])
    queue2 = deque([list(goal)])
    frontier1 = set([tuple(start)])
    frontier2 = set([tuple(goal)])

    while queue1 and queue2:
        new_queue1, new_queue2 = deque(), deque()
        for x, y in queue1:
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if not (1 <= nx < rows and 1 <= ny < cols and grid[nx][ny] == '.'):
                    continue
                if (nx, ny) not in frontier2:
                    new_queue1.append([nx, ny])
                    frontier1.add((nx, ny))
        for x, y in queue2:
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if not (1 <= nx < rows and 1 <= ny < cols and grid[nx][ny] == '.'):
                    continue
                if (nx, ny) not in frontier1:
                    new_queue2.append([nx, ny])
                    frontier2.add((nx, ny))
        if frontier1.intersection(frontier2):
            path1, path2 = find_path(grid, start, frontier1, frontier2, set(), [*goal])
            return combine_paths(path1, path2)
        queue1, queue2 = new_queue1, new_queue2

    return []

def find_path(grid, start, valid1, valid2, visited, direction):
    if direction == start:
        return [direction], []
    for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
        x, y = direction[0] - dx, direction[1] - dy
        if (x, y) in valid1 and (x, y) not in visited:
            visit = (x, y)
            visited.add(visit)
            path = find_path(grid, start, valid1, valid2, visited, visit)
            if path:
                return [visit] + path[0], path[1] + [visit]
    return [], []

def combine_paths(path1, path2):
    i, j = 0, 0
    while i < len(path1) and j < len(path2) and path1[i] == path2[j]:
        i += 1
        j += 1
    return path1[:i] + path2[j:][::-1]

