from collections import deque

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    if start == goal or grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return [start] if grid[start[0]][start[1]] == '.' else []

    def valid_pos(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def bfs(start, end):
        frontier = deque([[start]])
        visited = set([tuple(start)])
        while frontier:
            path = frontier.popleft()
            r, c = path[-1]
            if (r, c) == end:
                return path
            for nr, nc in [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]:
                if valid_pos(nr, nc) and (nr, nc) not in visited:
                    frontier.append(path + [(nr, nc)])
                    visited.add((nr, nc))
        return []

    forward_path = bfs(start, goal)
    back_path = bfs(goal, start)
    if not back_path:
        return []
    for i in range(len(back_path) - 1):
        r, c = back_path[i]
        if valid_pos(*forward_path[len(back_path) - 1 - i - 1]) and valid_pos(r, c):
            return forward_path[len(back_path) - 1 - i - 1::-1] + back_path[i+1:]
