from collections import deque

def is_valid(grid, move):
    """Check if a move is valid within the grid."""
    return (0 <= move[0] < len(grid) and
            0 <= move[1] < len(grid[0]) and
            grid[move[0]][move[1]] != '#')

def get_neighbours(start):
    """Get all four orthogonal neighbours of a cell."""
    neighbours = [(start[0] - 1, start[1]), (start[0] + 1, start[1]),
                  (start[0], start[1] - 1), (start[0], start[1] + 1)]
    return [n for n in neighbours if is_valid(start, n)]

def solve(grid, start, goal):
    """Find a path between two cells using bidirectional BFS."""
    if start == goal or not is_valid(grid, start) or not is_valid(grid, goal):
        return [start] if start == goal and is_valid(grid, start) else []

    start_frontier = deque([start])
    goal_frontier = deque([goal])
    start_visited = {start}
    goal_visited = {goal}
    best_meeting_cell = None

