from collections import deque

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])

    def is_valid(cell):
        return 0 <= cell[0] < rows and 0 <= cell[1] < cols and grid[cell[0]][cell[1]] == '.'

    def get_neighbours(cell):
        return [(cell[0] - 1, cell[1]), (cell[0] + 1, cell[1]), (cell[0], cell[1] - 1), (cell[0], cell[1] + 1)]

    def bfs(start):
        queue = deque([start])
        visited = set([start])
        frontier = set(get_neighbours(start))

        while queue:
            cell = queue.popleft()
            if cell == goal:
                return [cell]
            for neighbour in get_neighbours(cell):
                if is_valid(neighbour) and neighbour not in visited:
                    queue.append(neighbour)
                    visited.add(neighbour)
                    frontier.add(neighbour)

        return None

    frontier_start = set([start])
    frontier_goal = set([goal])
    paths = set()

    while frontier_start and frontier_goal:
        solution = bfs(next(iter(frontier_start)))
        if solution:
            path_start = solution
            for cell in reversed(path_start):
                if cell in frontier_goal:
                    path_goal = path_start + solution[path_start.index(cell):]
                    paths.add(tuple(path_start + solution[path_start.index(cell):]))
                    break
        solution = bfs(next(iter(frontier_goal)))
        if solution:
            path_goal = solution
            for cell in reversed(path_goal):
                if cell in frontier_start:
                    path_start = path_goal + solution[:path_goal.index(cell)]
                    paths.add(tuple(path_goal + solution[:path_goal.index(cell)]))

        frontier_start -= frontier_start.intersection(frontier_goal)
        frontier_goal -= frontier_goal.intersection(frontier_start)

    max_len = max([len(path) for path in paths]) if paths else 0
    for path in paths:
        if len(path) == max_len:
            return path
    return []

