def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    free = set((i, j) for i in range(rows) for j in range(cols) if grid[i][j] == '.')

    if start in [[0, 0], [rows - 1, cols - 1]] and start[0] == 0 and start[0] == goal[0] and start in free: 
        return [start]

    visited_free = set()
    visited_wall = set()

    def neighbors(cell):
        r, c = cell
        return [(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)]

    def valid(cell):
        return (0 <= cell[0] < rows and 0 <= cell[1] < cols and grid[cell[0]][cell[1]] != '#')

    def bfs(start):
        frontier = deque([(start, [start])])
        while frontier:
            (cell, path) = frontier.popleft()
            if cell in visited_free:
                continue
            visited_free.add(cell)
            if cell == goal:
                return path
            for neighbor in neighbors(cell):
                if valid(neighbor) and neighbor not in visited_wall:
                    frontier.append((neighbor, path + [neighbor]))
                    visited_wall.add(neighbor)

    def bfs_free(start):
        frontier = deque([(start, [start])])
        while frontier:
            (cell, path) = frontier.popleft()
            if cell in visited_free:
                continue
            visited_free.add(cell)
            if cell == start:
                return path
            for neighbor in neighbors(cell):
                if valid(neighbor) and neighbor not in free:
                    frontier.append((neighbor, path + [neighbor]))

    path = bfs(start) or bfs_free(goal)
    return path if path else []

