from collections import deque

def iterdeepening(grid, start, goal, max_depth=float('inf')):
    """Iterative Deepening Depth-First Search."""
    for depth in range(1, max_depth + 1):
        visited = set()
        queue = deque([(start, [start], 0)])

        while queue:
            (x, y), path, d = queue.popleft()
            if (x, y) == goal:
                return path
            if d < depth and grid[x][y] == '.' and (x, y) not in visited:
                visited.add((x, y))
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < len(grid)) and (0 <= ny < len(grid[0])) and grid[nx][ny] == '.':
                        queue.append(((nx, ny), path + [(nx, ny)], d + 1))
        if len(visited) == len([cell for row in grid for cell in row if cell == '.']):
            return []

def solve(grid, start, goal):
    """Find a path between two cells of a grid."""
    if grid[start[0]][start[1]] == '#':
        return []
    if start == goal:
        return [start] if grid[start[0]][start[1]] == '.' else []
    for d in range(max(len(grid), len(grid[0]))):
        path = iterdeepening(grid, start, goal, d)
        if path:
            return path
    return []

