def solve(grid, start, goal):
    if not grid or not grid[0] or grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    queue1, queue2 = deque([start]), deque([goal])
    visited1, visited2 = set([start]), set([goal])

    while queue1 and queue2:
        x = queue1.popleft()
        y = queue2.popleft()

        if x in visited2 or y in visited1:
            continue

        if x == y:
            path1, path2 = [], []
            while x != start:
                path1.append(x)
                x = list(queue1)[0]
                queue1.popleft()
            while y != goal:
                path2.append(y)
                y = list(queue2)[0]
                queue2.popleft()
            path = path2 + list(reversed(path1))
            return path

        astar1 = [x]
        for m, n in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            t = tuple((x[0] + m, x[1] + n))
            if 0 <= t[0] < len(grid) and 0 <= t[1] < len(grid[0]) and grid[t[0]][t[1]] == '.' and t not in visited1:
                queue1.append(t)
                visited1.add(t)

        astar2 = [y]
        for m, n in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            t = tuple((y[0] + m, y[1] + n))
            if 0 <= t[0] < len(grid) and 0 <= t[1] < len(grid[0]) and grid[t[0]][t[1]] == '.' and t not in visited2:
                queue2.append(t)
                visited2.add(t)

    return []
