        if target == x == y:
            return path + [(x, y)]
        if len(path) >= max_depth:
            return None
        for neighbor in neighbors((x, y)):
            if is_valid_move(*neighbor) and neighbor not in path:
                result = dfs(max_depth, *neighbor, path + [(x, y)], target)
                if result is not None:
                    return result
        return None

    if start == goal and grid[start[0]][start[1]] == '.':
