from collections import deque

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    visited = {start}

    q1 = deque([start])
    q2 = deque([goal])
    step1, step2 = 0, 0

    while q1 and q2:
        while x := q1[-1]:
            q1.pop()
            x1, y1 = x
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x1 + dx, y1 + dy
                if not 0 <= nx < rows or not 0 <= ny < cols or grid[nx][ny] == '#' or (nx, ny) in visited:
                    continue
                if (nx, ny) in q2:
                    return [(nx, ny)] + [p for p in q2 if p != (nx, ny)] + [(x1, y1)] + [p for p in reversed(q1) if p != (x1, y1)]
                visited.add((nx, ny))
                q1.append((nx, ny))
            step1 += 1
            if not q1: q1, q2 = q2, q1; step1, step2 = step2, step1

        while x := q2[-1]:
            q2.pop()
            x2, y2 = x
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x2 + dx, y2 + dy
                if not 0 <= nx < rows or not 0 <= ny < cols or grid[nx][ny] == '#' or (nx, ny) in visited:
                    continue
                if (nx, ny) in q1:
                    return [(nx, ny)] + [p for p in q1 if p != (nx, ny)] + [(x2, y2)] + [p for p in reversed(q2) if p != (x2, y2)]
                visited.add((nx, ny))
                q2.append((nx, ny))
            step2 += 1
            if not q2: q1, q2 = q2, q1; step1, step2 = step2, step1

    return []

def solve(grid, start, goal):
    def is_valid(cell):
        return 0 <= cell[0] < len(grid) and 0 <= cell[1] < len(grid[0]) and grid[cell[0]][cell[1]] == '.'

    def neighbours(cell):
        return [(cell[0] - 1, cell[1]), (cell[0] + 1, cell[1]), (cell[0], cell[1] - 1), (cell[0], cell[1] + 1)]

    def is_final(cell):
        return cell == goal

    def iiddfs_limited(depth, max_depth):
        stack = [(start, [])]
        while stack:
            cell, path = stack.pop()
            if is_valid(cell) and not is_final(cell) and len(path) < depth:
                for neighbour in neighbours(cell):
                    if is_valid(neighbour) and neighbour not in path:
                        stack.append((neighbour, path + [cell]))
            elif is_final(cell):
                return path + [cell]
            if not stack and max_depth <= depth:
                return []
        return []

    def limit_to_depth(p, depth):
        stack = list(p)
        while stack and len(stack[-1][1]) > depth:
            stack.pop()
        return stack

    for d in range(len(grid) + len(grid[0]) + 1):
        result = iiddfs_limited(d, d)
        if result:
            result = limit_to_depth(result, d - 1)
            return result
    return []

