def is_valid(grid, row, col):
    """Check if a cell is within the grid boundaries and is a free cell."""
    return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

def get_neighbours(grid, row, col):
    """Get the 4 orthogonal neighbours of a cell."""
    neighbours = []
    if is_valid(grid, row-1, col): neighbours.append((row-1, col))
    if is_valid(grid, row+1, col): neighbours.append((row+1, col))
    if is_valid(grid, row, col-1): neighbours.append((row, col-1))
    if is_valid(grid, row, col+1): neighbours.append((row, col+1))
    return neighbours

def solve(grid, start, goal):
    """Find a path between two cells of a grid using iterative deepening DFS."""
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    max_depth = 0
    while True:
        path = dfs(grid, start, goal, max_depth)
        if path:
            return path
        max_depth += 1

def dfs(grid, start, goal, max_depth, path=None, depth=0):
    """Perform a depth-limited DFS."""
    if path is None: path = [start]
    if path[-1] == goal: return path
    if depth == max_depth: return None
    for neighbour in get_neighbours(grid, *path[-1]):
        if neighbour not in path:
            path.append(neighbour)
            result = dfs(grid, start, goal, max_depth, path, depth+1)
            if result: return result
            path.pop()
    return None

