    rows, cols = len(grid), len(grid[0])

    left, right = set([start]), set([goal])
    found = False

    while left and right:
        new_left = set()
        for cell in left:
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                x, y = cell[0] + dx, cell[1] + dy
                if 0 <= x < rows and 0 <= y < cols and grid[x][y] == '.' and (x, y) not in right:
                    new_left.add((x, y))
        left = new_left

        new_right = set()
        for cell in right:
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                x, y = cell[0] + dx, cell[1] + dy
                if 0 <= x < rows and 0 <= y < cols and grid[x][y] == '.' and (x, y) not in left:
                    new_right.add((x, y))
        right = new_right

        if left & right:
            found = True
            break

    return list(left | right) if found else []

