def is_valid(grid, r, c):
    """Check if a position in the grid is valid."""
    return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

def neighbors(grid, r, c):
    """Generate the 4 orthogonal neighbors of a cell."""
    yield from (
        (r-1, c) if is_valid(grid, r-1, c) else None,
        (r+1, c) if is_valid(grid, r+1, c) else None,
        (r, c-1) if is_valid(grid, r, c-1) else None,
        (r, c+1) if is_valid(grid, r, c+1) else None
    )

def solve(grid, start, goal, depth=1):
    """Find a path between two cells using iterative deepening DFS."""
    stack = [(start, [start], depth)]
    while stack:
        (r, c), path, d = stack.pop()
        if (r, c) == goal:
            return path
        for nr, nc in neighbors(grid, r, c):
            if not any((nr, nc) in path for path in stack + [path[:i] + [nr, nc] + path[i:] for i in range(len(path))]):
                stack.append(((nr, nc), path + [(nr, nc)], min(d + 1, len(grid))))
    return []

