from collections import deque

def solve(grid, start, goal):
    def valid(x, y):
        "Check if a pair of coordinates is on grid boundaries or not."
        return 0 <= x < len(grid) and 0 <= y < len(grid[0])

    def is_wall(coord):
        "Check if a cell is a wall."
        return grid[coord[0]][coord[1]] == '#'

    def neighbours(coord):
        "Get the grid coordinates of neighbours of a cell."
        neighbours = []
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = coord[0] + dx, coord[1] + dy
            if valid(nx, ny) and not is_wall((nx, ny)):
                neighbours.append((nx, ny))
        return neighbours

    if start == goal:
        if not is_wall(start):
            return [start]
        return []

    max_depth = len(grid) * len(grid[0])  # with max steps if walked through wall
    def dfs_search(start, goal, depth, visited=set()):
        queue = deque([(start, [start])])
        while queue:
            current, path = queue.popleft()
            if current == goal:
                return path
            if depth > 0:
                for neighbour in neighbours(current):
                    if neighbour not in visited:
                        new_path = path + [neighbour]
                        queue.append((neighbour, new_path))
                        visited.add(neighbour)
            depth -= 1
        return []

    for depth in range(max_depth):
        path = dfs_search(start, goal, depth)
        if path:
            return path

    return []

