        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] != '#'

    def distance(point1, point2):
        (x1, y1) = point1
        (x2, y2) = point2
        return abs(x1-x2) + abs(y1-y2)

    def iddfs(start, goal, max_depth):
        stack = [(start, [])]
        while stack:
            (node, path) = stack.pop()
            if node == goal:
                return path + [node]
            if len(path) + distance(start, node) - distance(node, node) > max_depth:
                continue
            for dx, dy in directions:
                x, y = node[0] + dx, node[1] + dy
                if valid(x, y) and (x,y) not in path:
                    stack.append(((x, y), path + [node]))
        return []

    def classical_dfs(start, goal):
        stack = [(start, [])]
        visited = {start}
        while stack:
            (node, path) = stack.pop()
            if node == goal:
                return path + [node]
            for dx, dy in directions:
                x, y = node[0] + dx, node[1] + dy
                if valid(x, y) and (x,y) not in visited:
                    stack.append(((x, y), path + [node]))
                    visited.add((x, y))
        return []

    if start == goal or grid[start[0]][start[1]] == '#':
        return [start]
    if grid[goal[0]][goal[1]] == '#':
        return []
    max_depth = distance(start, goal) + 1
    return iddfs(start, goal, max_depth) or iddfs(start, goal, max_depth - 1) or iddfs(start, goal, max_depth - 2) or classical_dfs(start, goal)
