from heapq import heappop, heappush

def solve(grid, start, goal):
    N = len(grid)
    M = len(grid[0])
    ok = lambda r, c: 0 <= r < N and 0 <= c < M and grid[r][c] != '#'

    def neighbors(r, c):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            yield (r + dr, c + dc)

    def cost(r, c):
        return len(grid)

    def heuristic(r, c):
        return abs(r - goal[0]) + abs(c - goal[1])

    closed = [[False]*M for _ in range(N)]
    pq = [(0 if start == goal else heuristic(*start), 0 if start == goal else cost(*start), *start)]
    came_from = {}

    while pq:
        _, _, r, c = heappop(pq)

        if (r, c) == goal:
            path = []
            while (r, c) != start:
                path.append((r, c))
                r, c = came_from[(r, c)]
            path.append(start)
            path.reverse()
            return path

        if not ok(r, c) or closed[r][c]:
            continue

        closed[r][c] = True
        for nr, nc in neighbors(r, c):
            if not ok(nr, nc):
                continue
            if (nr, nc) in came_from:
                continue
            came_from[(nr, nc)] = (r, c)
            heappush(pq, (cost(r, c) + heuristic(nr, nc), cost(r, c), nr, nc))

    return []

