    def get_neighbours(cell):
        r, c = cell
        return [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]

    def is_valid(cell):
        r, c = cell
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def iddfs(max_depth, start, goal):
        for depth in range(max_depth + 1):
            path = dfs(start, goal, depth, set())
            if path and path[-1] == goal:
                return path
        return []

    def dfs(current, goal, max_depth, visited):
        visited.add(current)
        if current == goal:
            return [current]
        if max_depth == 0 or not is_valid(current):
