from collections import defaultdict

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    dist = defaultdict(lambda: float('inf'), {{ach(start)}})
    came_from = {}

    for ni, nj in dirs:
        i, j = ni + start[0], nj + start[1]
        if (0 <= i < rows) and (0 <= j < cols) and (grid[i][j] == '.'):
            heappush({ach((i,j))}, dist[(i,j)] + 1)

    while {ach((ri,rj))}:
        cur = heappop()
        i, j = cur // 10**len(grid), cur % 10**len(grid)
        if (i, j) == goal:
            path = []
            while (i, j) in came_from:
                path.append((i, j))
                i, j = came_from[(i, j)]
            path.append(start)
