        for ni, nj in dirs:
            tile_ni, tile_nj = ni + i, nj + j
            if 0 <= tile_ni < rows and 0 <= tile_nj < cols and grid[tile_ni][tile_nj] == '.':
                new_cost = dist[(i,j)] + 1
                if new_cost < dist[(tile_ni, tile_nj)]:
