def iterate(grid):
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    path_lengths = []
    for depth in range(rows + cols):
        for r in range(rows):
            for c in range(cols):
                if r == start[0] and c == start[1]:
                    path_lengths[r][c] = depth
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == '.' and path_lengths[r][c] == depth:
                    for dr, dc in directions:
                        nr, nc = r + dr, c + dc
                        if (0 <= nr < rows) and (0 <= nc < cols) and (grid[nr][nc] == '.'):
                            path_lengths[nr][nc] = depth + 1
    return path_lengths


def range_depth(grid, path_lengths, start, goal, max_depth):
    if start == goal:
        return True
    depth = path_lengths[start[0]][start[1]]
    if depth >= max_depth:
        return False
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    for dr, dc in directions:
        r, c = start[0] + dr, start[1] + dc
        if (0 <= r < len(grid)) and (0 <= c < len(grid[0])) and (grid[r][c] == '.') and (path_lengths[r][c] == depth + 1):
            if _valid(grid, start, goal, (r, c), depth + 1):
                return True
            if range_depth(grid, path_lengths, (r, c), goal, max_depth):
                return True
    return False


def _valid(grid, current_path, goal, new_point, depth):
    r, c = new_point
    if grid[r][c] == '#':
        return False
    if r == goal[0] and c == goal[1]:
        if len(current_path) and current_path[-1] != goal and depth in [len(current_path), len(current_path) + 1]:
            return True
        return False
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    valid = True
    for dr, dc in directions:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.':
            if (nc, nr) not in current_path:
                valid = valid and _valid(grid, current_path + [(r, c)], goal, (nr, nc), depth)
            else:
                valid = False
                break
    return valid


def solve(grid, start, goal):
    grid_rows = [list(row) for row in grid]  # copy grid
    start_row = start[0]
    start_col = start[1]
    goal_row = goal[0]
    goal_col = goal[1]
    if grid_rows[start_row][start_col] == '#':
        return []
    if grid_rows[goal_row][goal_col] == '#':
        return []
    if start == goal and grid Rows[start_row][start_col] == ".":
        return [start]
    path_lengths = [[0 for _ in range(len(grid[0]))] for _ in range(len(grid))]
    path_lengths = iterate(grid_rows)
    max_depth = max(max(row) for row in path_lengths)
    for cur_depth in range(1, max_depth + 1):
        if range_depth(grid_rows, path_lengths, start, goal, cur_depth):
            directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
            current_path = [start]
            r, c = start
