from collections import deque

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    queue = deque([(start, [start])])
    visited = set([start])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    cost = lambda x, y: 1

    while queue:
        (x, y), path = queue.popleft()
        if (x, y) == goal:
            return path
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if (1 <= nx < rows and 1 <= ny < cols and grid[nx][ny] == '.' and (nx, ny) not in visited):
                queue.append(((nx, ny), path + [(nx, ny)]))
                visited.add((nx, ny))

    return []

def is_valid(grid, x, y):
    rows, cols = len(grid), len(grid[0])
    return 1 <= x < rows and 1 <= y < cols

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def successors(cell):
        for dx, dy in directions:
            x, y = cell[0] + dx, cell[1] + dy
            if 0 <= x < rows and 0 <= y < cols and grid[x][y] == '.':
                yield (x, y)

    def heuristic(cell):
        return abs(cell[0] - goal[0]) + abs(cell[1] - goal[1])

    queue = [(start, None)]  # (cell, path so far)
    visited = set()
    c = 0  # constant weight
    while queue:
        cell, path = queue.pop()
        c += 1
        if cell == goal and path is not None:
            return [goal] + path[::-1]
        if cell in visited:
            continue
        visited.add(cell)
        for next in successors(cell):
            d = heuristic(cell) / c
            queue.insert(0, (next, [next] + (path if path else [])))
        if any(next in visited for next in successors(cell)):
            break

    return []

