def squeeze(uv):
    return uv[0] * 31 + uv[1]

def undo_squeeze(s):
    return s % 31, s // 31

def move_v(uv, v):
    return (uv[0], uv[1] + v)

def move_h(uv, h):
    return (uv[0] + h, uv[1])

def is_valid(uv, grid):
    x, y = uv
    return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '.'

def cost(u, v):
    return 1

def heuristic(uv, goal):
    return abs(uv[0] - goal[0]) + abs(uv[1] - goal[1])

def solve(grid, start, goal):
    if not is_valid(start, grid) or not is_valid(goal, grid):
        return []

    start_score = squeeze(start) + heuristic(start, goal)
    queue = [(start_score, start)]
    visited = {squeeze(start)}

    while queue:
        _, current = min(queue)
        queue.remove((min(queue)[0], min(queue)[1]))

        if current == goal:
            path = [current]
            while current != start:
                values = [undo_squeeze(i) for i in visited if i > squeeze(current)]
                values = max(values, key=lambda i: squeeze(is_valid(i, grid)) or (
                    0,0))
                current = values[0]
                path.append(current)
            return path[::-1]

        for neighbor in [move_v(current, -1), move_v(current, 1), move_h(current, -1), move_h(current, 1)]:
            if is_valid(neighbor, grid) and squeeze(neighbor) not in visited:
                score = squeeze(neighbor) + heuristic(neighbor, goal)
                queue.append((score, neighbor))
                visited.add(squeeze(neighbor))

    return []

