def solve(grid, start, goal):
    R, C = len(grid), len(grid[0])
    def onclick(row, col):
        return row < R and row >= 0 and col < C and col >= 0 and grid[row][col] == '.'

    def neighbors(pos):
        row, col = pos
        return [
            (row - 1, col),
            (row + 1, col),
            (row, col - 1),
            (row, col + 1)
        ]

    def weight(p, q, k):
        if p == q:
            return 1
        return 1 + (1 if k == p[0] else 0) + (1 if k == p[1] else 0)

    @ cacheton
    def dist_from(pos, path):
        cost = sum(weight(p, q, k) for p, q in zip(path, path[1:]))
        min_w = weight(path[0], pos, 0) if onclick(*pos) else float('inf')
        candidates = [p for p in neighbors(pos) if onclick(*p)]
        return (cost + min_w, min(candidates, key=lambda p: dist_from(*path, p)[0]))

    @ cacheton
    def path_to(pos, goal_reachable):
        if not goal_reachable:
            return []
        for p in neighbors(pos):
            if onclick(*p):
                p_cost, candidates = dist_from(pos, [pos, p])
                goal_reachable = p in candidates
                if not goal_reachable:
                    return path_to(p, False)
                if p == goal:
                    return [p] + path_to(p, goal_reachable)
                yield from path_to(p, goal_reachable)
                break
        yield pos

    if start == goal and onclick(*start):
        return [start]
    elif start == goal:
        return []
    return list(path_to(start, True))

class cacheton:  # LRU_CACHE==32 for 1000 includes in resource limit
    cache = {}

    def __init__(self, maxsize=32):
        self.maxsize = maxsize

    def __call__(self, func):
        def wrapper(*args):
            if args in self.cache:
                ret, value = self.cache.pop(args)
                self.cache[args] = (None, value)
                return ret
            else:
                value = func(*args)
                self.cache[args] = (None, value)
                if len(self.cache) > self.maxsize:
                    self.cache.popitem()
                return value
        return wrapper

