from heapq import heappop, heappush

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    walls = {(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == '#'}
    is_wall = lambda r, c: (r, c) in walls
    neighbors = [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]
    queue = [(0, start)]
    distances = {start: 0}
    paths = {start: [start]}

    while queue:
        main_distance, (r, c) = heappop(queue)

        if (r, c) == goal:
            return paths[goal]

        if distances[(r, c)] < main_distance:
            continue

        for dr, dc in neighbors:
            R, C = r + dr, c + dc

            if not (0 <= R < rows and 0 <= C < cols):
                continue

            if is_wall(R, C):
                continue

            d = distances[(r, c)] + 1
            if d < distances.get((R, C), d):
                distances[(R, C)] = d
                heappush(queue, (d, (R, C)))
                paths[(R, C)] = paths[(r, c)] + [(R, C)]

    return []

