from collections import defaultdict

def solve(n, edges, s, t):
    g = defaultdict(dict)
    r_g = defaultdict(dict)
    for u, v, w in edges:
        g[u][v] = w
        r_g[v][u] = w

    def dijkstra(graph, start):
        queue = [(0, start)]
        dist = {start: 0}
        while queue:
            d, u = heapq.heappop(queue)
            if u not in dist or d < dist[u]:
                dist[u] = d
                for v, w in graph[u].items():
                    if v not in dist or d + w < dist[v]:
                        heapq.heappush(queue, (d + w, v))
        return dist

    dist_from_s = dijkstra(g, s)
    if s == t:
        return 0
    if t not in dist_from_s:
        return -1

    dist_to_t = dijkstra(r_g, t)
    if t != s and s not in dist_to_t:
        return -1

    return dist_from_s[s] + dist_to_t[t]

