    queue = [(0, start)]
    closed = set()
    came_from = {}
    cost_so_far = {start: 0}

    while queue:
        _, current = heappop(queue)
        if current == goal:
            path = []
            while current in came_from:
                path.append(current)
                current = came_from[current]
                if current is None:
                    break
            path.append(start)
            return path[::-1]
        if current in closed:
            continue
