            r, c = current[0] + dr, current[1] + dc
            if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.':
                new_cost = cost_so_far[current] + internal_distance(current, (r, c))
                if (r, c) not in cost_so_far or new_cost < cost_so_far[(r, c)]:
