import heapq

def reverse_graph(n, edges):
    graph = [[] for _ in range(n)]
    reversed_graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))
        reversed_graph[v].append((u, w))
    return graph, reversed_graph

def dijkstra(graph, start):
    distances = [float('inf')] * len(graph)
    distances[start] = 0
    pq = [(0, start)]
    visited = set()
    while pq:
        distance, node = heapq.heappop(pq)
        if node in visited:
            continue
        visited.add(node)
        for neighbor, weight in graph[node]:
            if distances[neighbor] > distances[node] + weight:
                distances[neighbor] = distances[node] + weight
                heapq.heappush(pq, (distances[neighbor], neighbor))
    return distances

def solve(n, edges, s, t):
    if s == t:
        return 0
    graph, reversed_graph = reverse_graph(n, edges)
    forward_distances = dijkstra(graph, s)
    backward_distances = dijkstra(reversed_graph, t)
    common_nodes = set(range(n))
    for i in range(n):
        common_nodes.discard(i)
        if forward_distances[i] < float('inf') and backward_distances[i] < float('inf'):
            break
    max_distance = 0
    for u in common_nodes:
        if forward_distances[u] + backward_distances[u] > max_distance:
            max_distance = forward_distances[u] + backward_distances[u] - backward_distances[u]
    return max_distance

