        config_scores[position] = (config_map[position][0] + len(config_map))

        for i in config_map.keys():
            runningconfigsacorepenalties[i] = (config_scores[i] + (len(config_queue) - config_scores[i]))

        neighbors = passiveNeighbors(grid, position[0], position[1])
        neighbors = prioritize(neighbors, active)
        for neighbor in neighbors:
            newconfig = (neighbor[1], neighbor[0]) #x, y
            if newconfig not in config_map:
                active.add(newconfig)
                config_map[newconfig] = config_map[position] + (neighbor,)
                config_scores[newconfig] = (config_map[newconfig][0] + len(config_map))
                config_queue.append((config_scores[newconfig], newconfig))
        del config_queue[0]
    seen=set()
    nodeset = config_map[goal]
    route=[]
