def passiveNeighbors(grid, row, col):
    neighbors = []
    if row > 0 and grid[row-1][col] == '.':
        neighbors.append((row-1, col))
    if row < len(grid)-1 and grid[row+1][col] == '.':
        neighbors.append((row+1, col))
    if col > 0 and grid[row][col-1] == '.':
        neighbors.append((row, col-1))
    if col < len(grid[0])-1 and grid[row][col+1] == '.':
        neighbors.append((row, col+1))
    return neighbors

def prioritize(neighbors, active):
    new = []
    for neighbor in neighbors:
        if neighbor not in active:
            new.append((neighbor[0] + len(active), neighbor[1] + len(active)))
        else:
            new.append((active.index(neighbor) + len(active), active.index(neighbor) + len(active)))
    return new

