from collections import deque
import math.inf
import heapq

def solve(n, edges, s, t):
    def dijkstra():
        queue = [(0, s, None)]
        distances = {i: math.inf for i in range(n)}
        distances[s] = 0
        predecessor = {s: None}
        while queue:
            curr_dist, curr_node, prev_node = heapq.heappop(queue)
            if curr_node == t:
                path = []
                while curr_node is not None:
                    path.append(curr_node)
                    curr_node = predecessor[curr_node]
                path.reverse()
                return [distances[node] for node in path] if prev_node is not None else 0
            if curr_dist > distances[curr_node]:
                continue
            for u, v, w in edges:
                if u == curr_node:
                    d = curr_dist + w
                    if d < distances[v]:
                        distances[v] = d
                        predecessor[v] = curr_node
                        heapq.heappush(queue, (d, v, curr_node))
        return -1

    edges_reversed = [(v, u, w) for u, v, w in edges]
    forward_path = dijkstra()
    if forward_path == -1:
        return -1
    backward_path = dijkstra(edges_reversed)
    if backward_path == -1:
        return -1
    if backward_path[-1] != 0:
        return -1
    return forward_path[0] + backward_path[-1]

