def solve(n, edges, s, t):
    forward_adj = [[] for _ in range(n)]
    backward_adj = [[] for _ in range(n)]

    for u, v, w in edges:
        forward_adj[u].append((v, w))
        backward_adj[v].append((u, w))

    forward_frontier = [(0, s)]
    forward_distances = [sys.maxsize] * n
    forward_distances[s] = 0

    backward_frontier = [(0, t)]
    backward_distances = [sys.maxsize] * n
    backward_distances[t] = 0

    while forward_frontier and backward_frontier:
        forward_dist, forward_node = heapq.heappop(forward_frontier)
        backward_dist, backward_node = heapq.heappop(backward_frontier)

        if forward_node == backward_node:
            return forward_dist + backward_dist

        if forward_dist < forward_distances[forward_node] or backward_dist < backward_distances[backward_node]:
            if forward_dist < forward_distances[forward_node]:
                forward_distances[forward_node] = forward_dist
                for neighbor, weight in forward_adj[forward_node]:
                    heapq.heappush(forward_frontier, (forward_dist + weight, neighbor))

            if backward_dist < backward_distances[backward_node]:
                backward_distances[backward_node] = backward_dist
                for neighbor, weight in backward_adj[backward_node]:
                    heapq.heappush(backward_frontier, (backward_dist + weight, neighbor))

    return -1 if forward_frontier or backward_frontier else 0

import heapq

def solve(n, edges, s, t):
    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w))

    forward_queue = [(0, s, {})]
    forward_cost = {s: 0}

    backward_queue = [(0, t, {})]
    backward_cost = {t: 0}

    while forward_queue and backward_queue:
        forward_dist, u, forward_path = heapq.heappop(forward_queue)
        if u in backward_cost:
            return forward_dist + backward_cost[u]

        if forward_dist > forward_cost.get(u, float('inf')):
            continue

        for v, w in graph[u]:
            if v not in forward_cost:
                heapq.heappush(forward_queue, (forward_dist + w, v, {**forward_path, u: w}))
                forward_cost[v] = forward_dist + w

        backward_dist, u, backward_path = heapq.heappop(backward_queue)
        if u in forward_cost:
            continue

        for v, w in graph_u_to_v if hasattr(graph, 'graph_u_to_v') else ((v, u) for u, v in graph.items() for __ in []):
            if v not in backward_cost:
                heapq.heappush(backward_queue, (backward_dist + w, v, {**backward_path, u: w}))
                backward_cost[v] = backward_dist + w

        graph_u_to_v = graph
        for k in graph:
            graph.update({v: ((u, v) for u, _, _ in graph[v]) for v in graph[k]})

    return -1

def reverse_graph(n, edges):
    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w))
    return graph

