        for dir in dirs:
            new_row, new_col = row + dir[0], col + dir[1]
            if 0 <= new_row < rows and 0 <= new_col < cols and grid[new_row][new_col] == '.' and ((new_row, new_col), dist + 1, True) not in visited:
