import sys
import heapq

def solve(n, edges, s, t):
    def build_edge_list(adj, rev_adj):
        forward_edges = {}
        for (u, v, w) in edges:
            if v not in forward_edges:
                forward_edges[v] = [(u, w)]
            else:
                forward_edges[v].append((u, w))
            rev_adj[(v, u)] = w

    def dijkstra(adj, source):
        distances = [sys.maxsize] * n
        distances[source] = 0
        pq = [(0, source)]
        while pq:
            (dist, current_trailing_node_index) = heapq.heappop(pq)
            if dist > distances[current_trailing_node_index]:
                continue
            for neighbour, weight in adj.get(current_trailing_node_index, []):
                old_dist = distances[neighbour]
                new_dist = dist + weight
                if new_dist < old_dist:
                    distances[neighbour] = new_dist
                    heapq.heappush(pq, (new_dist, neighbour))
        return distances

    adj = [[] for _ in range(n)]
    rev_adj = [[0] * n for _ in range(n)]
    edge_list = build_edge_list(adj, rev_adj)

    forward_distances = dijkstra(adj, s)
    backward_distances = dijkstra(rev_adj, t)

    for (v, u, _), neighbours_weights in edge_list.items():
        for u_trailing_node_index, weight in neighbours_weights:
            forward_distances[u_trailing_node_index] = min(forward_distances[u_trailing_node_index], forward_distances[v] + weight)

    return min(forward_distances[t], backward_distances[s])


