import heapq

def solve(n, edges, s, t):
    forwardGraph = [[] for _ in range(n)]
    reverseGraph = [[] for _ in range(n)]

    for u, v, w in edges:
        forwardGraph[u].append((v, w))
        reverseGraph[v].append((u, w))

    def forwardDijkstra(s):
        distances = [float('inf')] * n
        distances[s] = 0
        priorityQueue = [(0, s)]

        while priorityQueue:
            d, u = heapq.heappop(priorityQueue)
            if d > distances[u]:
                continue
            for v, w in forwardGraph[u]:
                if distances[u] + w < distances[v]:
                    distances[v] = distances[u] + w
                    heapq.heappush(priorityQueue, (distances[v], v))

        return distances

    def backwardDijkstra(t):
        distances = [float('inf')] * n
        distances[t] = 0
        priorityQueue = [(0, t)]

        while priorityQueue:
            d, u = heapq.heappop(priorityQueue)
            if d > distances[u]:
                continue
            for v, w in reverseGraph[u]:
                if distances[u] + w < distances[v]:
                    distances[v] = distances[u] + w
                    heapq.heappush(priorityQueue, (distances[v], v))

        return distances

    forwardDistances = forwardDijkstra(s)
    backwardDistances = backwardDijkstra(t)

    for i in range(n):
        if forwardDistances[i] != float('inf') and backwardDistances[i] != float('inf'):
            return forwardDistances[i] + backwardDistances[i]

    return -1

