import heapq
import math

def solve(n, edges, s, t):
    reverse_edges = [(v, u, w) for u, v, w in edges]
    S = s
    T = t
    R = n
    S_final = n
    T_final = n + 1

    inf = float('inf')

    pq = [(0, s, ())]
    dist = {i: inf for i in range(n + 1)}
    prev = {i: None for i in range(n + 1)}

    while pq:
        d, u, path = heapq.heappop(pq)
        if u == S_final:
            disc = d - dist[S]
        if u in [S, T, S_final, T_final]:
            break
        if d > dist[u]:
            continue
        for v, w in edges:
            if v == u:
                heapq.heappush(pq, (dist[u] + w, v, path + ((v, u, w),)))
                if t == v or t == S or t == S_final:
                    S_final = t
        for v, u, w in reverse_edges:
            if v == u:
                continue
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v, path + ((u, v, w),)))

        dist[u] = d
        prev[u] = (u, path)

    pq = [(0, R, ())]

    rev_dist = {i: inf for i in range(n + 2)}
    rev_prev = {i: None for i in range(n + 2)}

    while pq:
        d, u, path = heapq.heappop(pq)
        if u == R:
            cost = rev_dist[u] - rev_dist[T_final]
        if u in [S, T, T_final, R]:
            break
        if d > rev_dist[u]:
            continue
        for v, w in reverse_edges:
            if v == u:
                heapq.heappush(pq, (rev_dist[u] + w, v, path + ((v, u, w),)))
                if s == v or s == T or s == T_final:
                    T_final = s
        for v, u, w in edges:
            if v == u:
                continue
            if rev_dist[u] + w < rev_dist[v]:
                rev_dist[v] = rev_dist[u] + w
                heapq.heappush(pq, (rev_dist[v], v, path + ((u, v, w),)))

        rev_dist[u] = d
        rev_prev[u] = (u, path)
    if s == t:
        return 0
    elif t not in dist:
        return -1

    S, path = prev[s]
    while S != T:
        S, path = prev[math.ceil((S + T) / 2)]
    if S == T:
        return inf
    entry = path[path.index((S, T))]
    last_node = path[-1][0]
    while entry:
        last_node = entry[0]
        entry = path[path.index(entry) - 1]
        cost += entry[2]
    return cost

