from collections import deque

def solve(n, edges, s, t):
    adj, rev_adj = [[] for _ in range(n)], [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
        rev_adj[v].append((u, w))

    q, dist = [(0, s, False)], [float('inf')] * n
    dist[s] = 0
    forward_changed = set((s,))

    q2, rev_dist = [(-float('inf'), t, False)], [float('inf')] * n
    rev_dist[t] = 0
    back_changed = set((t,))

    while q:
        d, u, f = heapq.heappop(q)
        if f:
            if (u, True) in forward_changed:
                points = [(a, d + b) for a, b in q]
                points.sort(key=lambda x: (x[0], -x[1]))
                return abs(points[0][1])
        else:
            forward_changed.add((u, f))
            for v, w in adj[u]:
                if d + w < dist[v]:
                    dist[v] = d + w
                    heapq.heappush(q, (dist[v], v, f))
        if u in back_changed:
            continue
        if dist[u] == rev_dist[u]:
            return dist[u]
        rev_changed.add((u, f))
        for v, w in rev_adj[u]:
            if d - w > rev_dist[v]:
                rev_dist[v] = d - w
                heapq.heappush(q2, (-rev_dist[v], v, f))

    if dist[t] != float('inf'):
        return dist[t]
    return -1

