import heapq

def fix_edge(edges):
    fixed_edges = []
    for u, v, w in edges:
        fixed_edges.append((u, v, w))
        fixed_edges.append((v, u, float('inf')))  # assuming distance to other nodes in reversed graph is infinity
    return fixed_edges

def distance_to(u, dist, edges):
    visited = set()
    pq = [(0, u)]
    while pq:
        d, v = heapq.heappop(pq)
        if v not in visited:
            visited.add(v)
            if v == u:
                return dist[v]
            for e in edges:
                w = e[0]
                if w == v and dist[w] > d + e[2]:
                    dist[w] = d + e[2]
                    heapq.heappush(pq, (dist[w], w))
    return float('inf')

def solve(n, edges, s, t):
    edges = fix_edge(edges)
    forward_dist = [float('inf')] * n
    backward_dist = [float('inf')] * n

    forward_dist[s] = 0
    for _ in range(n):
        max_backward_dist = 0
        for v in range(n):
            if forward_dist[v] < float('inf'):
                max_backward_dist = max(max_backward_dist, backward_dist[v])
        for u in range(n):
            if forward_dist[u] < float('inf'):
                for e in edges:
                    w = e[1]
                    if forward_dist[w] > forward_dist[u] + e[2]:
                        forward_dist[w] = forward_dist[u] + e[2]
        for v in range(n):
            if forward_dist[v] < float('inf'):
                distance = distance_to(v, backward_dist, edges)
                if distance < max_backward_dist:
                    break
        else:
            for v in range(n):
                if forward_dist[v] < float('inf'):
                    max_backward_dist = max(max_backward_dist, backward_dist[v])
            if max_backward_dist < float('inf'):
                backward_dist = [(float('inf') if v in range(n) and forward_dist[v] == float('inf') else backward_dist[v]) for v in range(n)]
                for u in reversed(edges):
                    if backward_dist[u[1]] > backward_dist[u[0]] - u[2]:
                        backward_dist[u[1]] = backward_dist[u[0]] - u[2]
            else:
                break
        if forward_dist[t] == float('inf'):
            break

    return forward_dist[t] if forward_dist[t] != float('inf') else -1

