    dist_from_s = [sys.maxsize] * n
    dist_from_s[s] = 0
    pq_from_s = [(0, s)]

    # Dijkstra's algorithm backward
    reversed_graph = [[] for _ in range(n)]
    for u, v, w in edges:
        reversed_graph[v].append((u, w))
    dist_from_t = [sys.maxsize] * n
    dist_from_t[t] = 0
    pq_from_t = [(0, t)]

    while pq_from_s or pq_from_t:
        if pq_from_s:
            d, u = heapq.heappop(pq_from_s)
            if d > dist_from_s[u]:
                continue
            for v, w in graph[u]:
                if dist_from_s[v] > dist_from_s[u] + w:
                    dist_from_s[v] = dist_from_s[u] + w
                    heapq.heappush(pq_from_s, (dist_from_s[v], v))
        if pq_from_t:
            d, v = heapq.heappop(pq_from_t)
            if d > dist_from_t[v]:
                continue
            for u, w in reversed_graph[v]:
                if dist_from_t[u] > dist_from_t[v] + w:
                    dist_from_t[u] = dist_from_t[v] + w
                    heapq.heappush(pq_from_t, (dist_from_t[u], u))

        # meeting rule
        if dist_from_s[t] < sys.maxsize and dist_from_t[s] < sys.maxsize:
            return dist_from_s[t]
