import heapq
from collections import deque, defaultdict

def solve(n, edges, s, t):
    graph = defaultdict(list)
    rev_graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        rev_graph[v].append((u, w))

    def dijkstra(graph, s, t, rev=False):
        dist = {i: float('inf') for i in range(n)}
        parent = {i: None for i in range(n)}
        dist[s] = 0
        pq = [(0, s)]
        while pq:
            curr_dist, curr_node = heapq.heappop(pq)
            if rev and curr_dist <= dist[curr_node]:
                continue
            if curr_node == t:
                break
            for neighbor, weight in graph[curr_node]:
                new_dist = curr_dist + weight
                if new_dist < dist[neighbor]:
                    dist[neighbor] = new_dist
                    parent[neighbor] = curr_node
                    if rev:
                        prev_node = neighbor
                        new_weight = curr_dist - weight
                        while prev_node is not None:
                            heapq.heappush(pq, (-new_weight, prev_node))
                            new_weight += weight
                            prev_node = parent.get(prev_node)
                    else:
                        heapq.heappush(pq, (new_dist, neighbor))
        return dist

    forward_dist = dijkstra(graph, s, t)
    if t not in forward_dist:
        return -1
    if forward_dist[t] == float('inf'):
        return -1
    backward_dist = dijkstra(rev_graph, t, s, rev=True)
    if s not in backward_dist:
        return -1
    return forward_dist[t] + backward_dist[s]

