def solve(n, edges, s, t):
    forward = {i: [] for i in range(n)}
    backward = {i: [] for i in range(n)}

    for u, v, w in edges:
        forward[u].append((v, w))
        backward[v].append((u, w))

    distance_forward = {i: float('inf') for i in range(n)}
    distance_backward = {i: float('inf') for i in range(n)}
    distance_forward[s] = 0
    distance_backward[t] = 0
    visited_forward = set()
    visited_backward = set()

    queue_forward = [(0, s)]
    queue_backward = [(0, t)]

    while queue_forward and queue_backward:
        d_forward, u = heapq.heappop(queue_forward)
        d_backward, v = heapq.heappop(queue_backward)
        if u in visited_forward or v in visited_backward:
            continue
        visited_forward.add(u)
        visited_backward.add(v)

        for v2, w2 in forward[u]:
            if distance_forward[v2] > distance_forward[u] + w2:
                distance_forward[v2] = distance_forward[u] + w2
                heapq.heappush(queue_forward, (distance_forward[v2], v2))
        for u2, w2 in backward[v]:
            if distance_backward[u2] > distance_backward[v] + w2:
                distance_backward[u2] = distance_backward[v] + w2
                heapq.heappush(queue_backward, (distance_backward[u2], u2))

    if (s != t and distance_forward[t] == float('inf')) or (s != t and distance_backward[s] == float('inf')):
