from heapq import heappop, heappush

def solve(n, edges, s, t):
    graph = [[] for _ in range(n)]
    rgraph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))
        rgraph[v].append((u, w))

    def bidirectional_dijkstra(source, target, graph, rgraph):
        start_relaxed = [float('inf')] * n
        stop_relaxed = [float('inf')] * n
        potential = [0] * n

        source_queue = [(0, source, 0)]
        target_queue = [(0, target, 0)]

        while source_queue and target_queue:
            s_weight, s_node, s_potential = heappop(source_queue)
            t_weight, t_node, t_potential = heappop(target_queue)
            if s_weight != s_potential and s_weight != stop_relaxed[s_node]:
                start_relaxed[s_node] = s_weight
                heappush(source_queue, (s_weight, s_node, s_potential))
                for v, w in graph[s_node]:
                    if potential[v] <= s_potential + w:
                        continue
                    potential[v] = s_potential + w
                    heappush(source_queue, (s_weight + w, v, potential[v]))
            if t_weight != t_potential and t_weight != stop_relaxed[t_node]:
                stop_relaxed[t_node] = t_weight
                heappush(target_queue, (t_weight, t_node, t_potential))
                for v, w in rgraph[t_node]:
                    if potential[v] <= t_potential + w:
                        continue
                    potential[v] = t_potential + w
                    heappush(target_queue, (t_weight + w, v, potential[v]))
            if s_node == t_node:
                return s_weight
        return -1

    return bidirectional_dijkstra(s, t, graph, rgraph)

