    def relax(adj, bucket, distance):
        changed = False
        for u in bucket:
            for v, w in adj[u]:
                new_distance = distance[u] + w
                if v not in bucket or new_distance < distance[v]:
                    distance[v] = new_distance
                    changed = True
        return changed

    adj = convert_graph(edges)
    bucket = [s]
    distance = {s: 0}
    visited = [False]*n
    while bucket:
        dist = math.inf if not bucket else min(distance[u] for u in bucket)
        new_bucket = [u for u in bucket if distance[u] == dist]
