import heapq

def solve(n, edges, s, t):
    sentinels = [-1] * n
    distances = [sys.maxsize] * n
    distances[s] = 0
    buckets = [[] for _ in range(n + 1)]
    heapq.heappush(buckets[0], (0, s))

    while buckets[0]:
        min_distance, u = heapq.heappop(buckets[distances[u] + 1])
        if distances[u] != min_distance:
            continue
        sentinels[u] = len(buckets[min_distance])
        for v, w in edges:
            if v == u:
                continue
            new_distance = distances[u] + w
            if new_distance < distances[v]:
                distances[v] = new_distance
                heapq.heappush(buckets[new_distance], (new_distance, v))

    max_sentinel = sentinels[t]
    if max_sentinel == -1:
        return -1
    path_distance = sys.maxsize
    for i in range(max_sentinel - 1, -1, -1):
        path_distance = min(path_distance, distances[sentinels[i]])
        u = sentinels[i]
        for v, w in edges:
            if v == u:
                continue
            new_distance = distances[u] + w
            if distances[u] + w == distances[v]:
                path_distance = min(path_distance, new_distance)
    return path_distance

