            if len(bucket[d]) == len(bucket[d-1]) == len(bucket[d-2]): break
            for v, w in bucket[d]:
                if dist[v] > dist[cur_dist] + w:
                    dist[v] = dist[cur_dist] + w
                    done = True
        cur_dist += 1

        # relax all edges
        if not done:
            break

