import sys
import collections

def solve(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))
    short_distances = [float('inf')] * n
    short_distances[s] = 0

    # Create the bucket queue
    buckets = [[] for _ in range(n * 2)]
    for i, dist in enumerate(short_distances):
        if 0 <= dist <= n * 2:
            buckets[dist].append(i)

    while True:
        # Get the next bucket
        d = min(i for i, bucket in enumerate(buckets) if bucket)
        if d >= n * 2:
            break
        distance = d
        while buckets[distance]:
            u = buckets[distance].pop(0)
            for v, w in graph[u]:
                alt = distance + w
                if short_distances[v] > alt:
                    short_distances[v] = alt
                    buckets[alt].append(v)
        # Clear "fully processed" buckets
        if buckets[distance]:
            buckets[distance - 1] += buckets[distance]
            buckets[distance] = []

    return short_distances[t] if short_distances[t] != float('inf') else -1

