import sys
from typing import List, Tuple

def solve(n: int, edges: List[Tuple[int, int, int]], s: int, t: int) -> int:
    def distance(candidates: List[int], done: Set[int]):
        results = []
        for i in range(len(candidates)):
            c = candidates[i]
            if c not in done:
                results.append(c)
        if results:
            results.sort()
        return results

    def relax(distances: List[int], onbucket: List[Tuple[int, int]], bucket: int) -> None:
        newonbucket, changed = [], False
        for u, d in onbucket:
            for v, w in edges:
                if v == u:
                    if d + w < distances[v]:
                        distances[v] = d + w
                        newonbucket.append((v, d + w))
                        changed = True
        return newonbucket, changed

    INF = sys.maxsize
    distances = [INF] * n
    with_DEFINITIONS = [(INF, [])] * n
    onbucket = [(s, 0)]

    for _ in range(n):
        onbucket, changed = relax(distances, onbucket, n - 1)
        onbucket = distance(onbucket, set())
        while changed and n - 1 < len(onbucket) and onbucket[-1][1] == INF:
            n -= 1
            newonbucket, changed = relax(distances, onbucket, n - 1)
            onbucket = distance(newonbucket, set())
        with_DEFINITIONS[n] = (distances[t], onbucket)

    return distances[t] if distances[t] != INF else -1

