def solve(n: int, edges: List[Tuple[int, int, int]], s: int, t: int) -> int:
    DIST_INF = 10**9
    buckets = [[] for _ in range(n)]
    dist = [DIST_INF] * n
    dist[s] = 0
    in_queue = [False] * n

    def add_bucket(k: int):
        for i in range(n):
            if dist[i] == k:
                buckets[i].append(i)
                buckets[k].append(i)

    for _ in range(n):
        add_bucket>(_ for _ in range(n) if dist[_] == -1 else dist[_])

    add_bucket(0)

    while True:
        k = (i for b in buckets for i in b).next()  # gets the first node in each non-empty bucket, corresponding to the biggest (or smallest) distance of its bucket

        if not any(buckets[i] for i in range(n)):
            break

        for u in buckets[k]:
            in_queue[u] = True
            for v, w in edges:
                if v == u:
                    if dist[u] + w < dist[v]:
                        dist[v] = dist[u] + w
                        add_bucket(dist[v])
                elif v not in [x[0] for x in buckets]:
                    if dist[u] + w < dist[v]:
                        dist[v] = dist[u] + w
                        add_bucket(dist[v])

        for i in range(n):
            buckets[i] = [x for x in buckets[i] if not in_queue[x]]
            in_queue[i] = False

    return dist[t] if 0 <= dist[t] <= 10**9 else -1

