def shortest_path_length(n, edges, s, t):
    def relate_nodes(n, edges):
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
        return graph

    def dijkstra_usage(graph, s, t):
        inf = float('inf')
        buckets = [[] for _ in range(n+1)]
        for u in range(n):
            if u != s and u != t: 
                buckets[0].append((u, inf))
        buckets[0].append((s, 0))
        while buckets:
            for bucket in buckets:
                bucket.sort(key=lambda pair: pair[1])
            i = 0
            while i < n and buckets[i]:
                if t in [node for node, weight in buckets[i]]:
                    dijkstra_path = [node for node, weight in buckets[i] if node == t][0]
                    dijkstra_weight = [weight for weight, node in buckets[i] if node == t][0]
                    return dijkstra_weight if dijkstra_weight != inf else -1
                distance = buckets[i].pop(0)[1]
                for node, weight in graph[i]:
                    new_distance = distance + weight
                    if bucket_index:=new_distance + 1 < n and [node for node, new_weight in buckets[bucket_index] if node == node][-1] > new_distance:
                        j = len(buckets[bucket_index]) - 1
                        while (new_distance < [weight for node, weight in buckets[bucket_index] if node == node][j] or
                                new_distance == [weight for node, weight in buckets[bucket_index] if node == node][j] and
                                len(buckets[bucket_index]) == j+1):
                            j -= 1
                        buckets[bucket_index].insert(j+1, (node, new_distance))
                i += 1
            i -= 1
            if i < 0:
                return inf
            while i >= 0 and not buckets[i]:
                i -= 1
                n -= 1
        return -1

    return dijkstra_usage(*relate_nodes(n, edges), s, t)

