class PriorityQueue:
    def __init__(self, max_size):
        self.max_size = max_size
        self.n = 0
        self.q = [None] * max_size

    def is_empty(self):
        return self.n == 0

    def is_full(self):
        return self.n == self.max_size

    def enqueue(self, item, priority):
        if self.is_full():
            raise Exception("Priority queue is full")
        self.n += 1
        i = self.n - 1
        self.q[i] = (item, priority)
        while i > 0:
            p = (i - 1) // 2
            if priority > self.q[p][1]:
                self.q[i] = self.q[p]
                i = p
            else:
                break
        self.q[i] = (item, priority)

    def dequeue(self):
        if self.is_empty():
            return None
        result = self.q[0]
        self.q[0] = self.q[self.n - 1]
        self.n -= 1
        i = 0
        while i * 2 + 1 < self.n:
            l = i * 2 + 1
            if l + 1 < self.n and self.q[l + 1][1] < self.q[l][1]:
                l += 1
            if self.q[i][1] >= self.q[l][1]:
                break
            self.q[i] = self.q[l]
            i = l
        self.q[i] = result
        return result

def solve(n, edges, s, t):
    distances = [float('inf')] * n
    distances[s] = 0

    for dist in range(n):
        info = distances[dist] if dist == 0 else None
        queue_by_distance = [None] + [{] for _ in range(dist)]
        for u in range(n):
            if distances[u] == info:
                for item in edges:
                    if item[0] == u:
                        queue_by_distance[dist + item[2] + 1][item[1], item[2]] = dist + item[2] + 1
        while not queue_by_distance[dist + 1] and dist + 1 < len(queue_by_distance):
            dist += 1
            queue_by_distance = queue_by_distance[:dist+1]

        while not queue_by_distance[dist + 1] and dist < len(queue_by_distance) -1 :
            dist += 1

        for i in range(dist, len(queue_by_distance)):
            info = queue_by_distance[i]
            if info:
                for (v, w) in info.items():
                    if distances[v] > i:
                        distances[v] = i
        for item in edges:
            if item[0] == s and item[2] + 1 == dist + 1:
                return item[2]
    return distances[t] if distances[t] != float('inf') else -1

