        return (
            (max(0, r - 1), c) if r > 0 and grid[r - 1][c] != '#' else (),
            (r, max(0, c - 1)) if c > 0 and grid[r][c - 1] != '#' else (),
            (min(rows - 1, r + 1), c) if r < rows - 1 and grid[r + 1][c] != '#' else (),
            (r, min(cols - 1, c + 1)) if c < cols - 1 and grid[r][c + 1] != '#' else (),
        )

    def is_goal(position):
        return position == goal

    while queue:
        position, path = queue.popleft()

        if is_goal(position):
            return path

        for r, c in get_neighbors(*position):
            queue.append(((r, c), path + [(r, c)]))

