    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if grid[start[0]][start[1]] == '#':
        return []
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([start])
    visited = {start}

    while queue:
        x, y = queue.popleft()
        if (x, y) == goal:
            path = [(x, y)]
            while (x, y) != start:
                for dx, dy in directions:
                    if 0 <= x + dx < rows and 0 <= y + dy < cols and grid[x + dx][y + dy] == '.' and (x + dx, y + dy) in visited:
                        x += dx
                        y += dy
                        break
                path.insert(0, (x, y))
            return path
        for dx, dy in directions:
            if 0 <= x + dx < rows and 0 <= y + dy < cols and grid[x + dx][y + dy] == '.' and (x + dx, y + dy) not in visited:
                queue.append((x + dx, y + dy))
                visited.add((x + dx, y + dy))
    return []
