def solve(grid, start, goal):
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def is_valid(move):
        r, c = move
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and not visited[r][c]

    def dfs(current, path):
        if current == goal:
            return path + [current]
        visited[current[0]][current[1]] = True
        for dr, dc in directions:
            next_move = (current[0] + dr, current[1] + dc)
            if is_valid(next_move):
                res = dfs(next_move, path + [current])
                if res:
                    return res
        return None

    if not is_valid(start) or grid[start[0]][start[1]] == '#':
        return []

    return dfs(start, [])

