from typing import List, Tuple

def valid_move(row: int, col: int) -> bool:
    """Check if a move is within the grid bounds and the cell is free"""
    return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

def solve(start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    """Find a path between two cells in a grid"""
    queue = deque([(start, [start])])
    visited = {start}

    while queue:
        (row, col), path = queue.popleft()

        if (row, col) == goal:
            return path

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            r, c = row + dr, col + dc
            if valid_move(r, c) and (r, c) not in visited:
                queue.append(((r, c), path + [(r, c)]))
                visited.add((r, c))

    return []

