from collections import deque

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    moves = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def is_valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.'

    def get_adjacent_cells(cell):
        return [(cell[0] + dr, cell[1] + dc) for dr, dc in moves if is_valid(cell[0] + dr, cell[1] + dc)]

    queue = deque([start])
    paths = {start: [start]}

    while queue:
        cell = queue.popleft()
        if cell == goal:
            return paths[cell]

        for adjacent_cell in get_adjacent_cells(cell):
            if adjacent_cell not in paths:
                paths[adjacent_cell] = paths[cell] + [adjacent_cell]
                queue.append(adjacent_cell)

    return []

