        return [
            (row-1, col) if is_valid(row-1, col) else None,
            (row+1, col) if is_valid(row+1, col) else None,
            (row, col-1) if is_valid(row, col-1) else None,
            (row, col+1) if is_valid(row, col+1) else None
        ]

    paths = set()
    stack = [(starts[0], [''])]

    while stack:
        (row, col), path = stack.pop()
        if (row, col) == goal:
            paths.add(tuple(sorted(path + [(row, col)], key=lambda elem: (elem[0], elem[1]))))
        for neighbour in get_neighbours(row, col):
            if neighbour is None:
                continue
            if (neighbour[0], neighbour[1], path + [(row, col)]) not in paths:
                stack.append((neighbour, path + [(row, col)]))

    if goal in starts:
        paths.add((tuple(sorted([start, goal])))
    return [list(path) for path in paths if path]

