def find_empty(grid, visited, position):
    """Check if a cell is empty and not visited yet."""
    return 0 <= position[0] < len(grid) and 0 <= position[1] < len(grid[0]) and grid[position[0]][position[1]] == '.' and position not in visited

def neighbors(position):
    """Generate all four orthogonal neighbours of a position."""
    return [(position[0] - 1, position[1]), (position[0] + 1, position[1]), (position[0], position[1] - 1), (position[0], position[1] + 1)]

def dfs(grid, start, goal):
    """Depth-first search to find a random path between two cells."""
    visited = set()
    stack = [(start, [start])]

    while stack:
        position, path = stack.pop()
        if position == goal:
            return path

        visited.add(position)
        for neighbor in neighbors(position):
            if find_empty(grid, visited, neighbor):
                stack.append((neighbor, path + [neighbor]))

    return []

