import heapq

def solve(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    heap = [(0, s)]
    visited = set()
    while heap:
        weight, u = heapq.heappop(heap)
        if u == t:
            return weight
        if u in visited:
            continue
        visited.add(u)
        for v, w in graph[u]:
            heapq.heappush(heap, (w + weight, v))

    return -1

