def dijkstra(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    distance = [float('inf')] * n
    distance[s] = 0
    pq = [(0, s)]

    while pq:
        d, u = heapq.heappop(pq)
        if u == t:
            return d
        if d > distance[u]:
            continue
        for v, w in graph[u]:
            new_d = d + w
            if new_d < distance[v]:
                distance[v] = new_d
                heapq.heappush(pq, (new_d, v))

    return -1

def solve(n, edges, s, t):
    if s == t:
        return 0

    shortest_paths = [float('inf')] * n
    for u in range(n):
        graph = [[] for _ in range(n)]
        for v in range(n):
            if v != u:
                graph[v].append((u, float('inf')))

        for a, b, w in edges:
