import sys

def add_edge(parent, edge):
    """Add an edge to the parent dictionary."""
    node, child, weight = edge
    if child not in parent:
        parent[child] = [node, weight]
    else:
        while parent[child] and parent[child][1] > weight:
            heapq.heappop(parent[child])
        if parent[child]: heapq.heappush(parent[child], weight)
        heapq.heappush(parent[child], weight)

def solve(n, edges, s, t):
    """Returns the length of the shortest path from node s to node t."""
    parent = {}
    for edge in edges:
        heapq.heappush(parent.get(edge[1], []), (edge[0], edge[2]))

    dist = [sys.maxsize] * n
    dist[s] = 0
    pq = [[0, s]]

    while pq:
        cur_dist, cur_node = heapq.heappop(pq)
        if cur_node == t: return cur_dist
        if cur_node not in parent: continue
        for parent_node, weight in parent[cur_node]:
            if cur_dist + weight < dist[parent_node]:
                dist[parent_node] = cur_dist + weight
                heapq.heappush(pq, [dist[parent_node], parent_node])

    return -1

