import heapq

def topological_sort(edges):
    graph = [[] for _ in range(len(edges) + 1)]
    indegree = [0] * (len(edges) + 1)

    for u, v, w in edges:
        graph[u].append((v, w))
        indegree[v] += 1

    queue = [i for i in range(len(edges) + 1) if indegree[i] == 0]
    sorted_order = []

    while queue:
        node = queue.pop(0)
        sorted_order.append(node)

        for neighbor, cost in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    return sorted_order

def dijkstra(n, edges, s, t):
    graph = [[] for _ in range(n)]
    dist = [float('inf')] * n
    dist[s] = 0

    for u, v, w in edges:
        graph[u].append((v, w))

    pq = [(0, s)]

    while pq:
        d, u = heapq.heappop(pq)

        if u == t:
            return d

        if d > dist[u]:
            continue

        for v, w in graph[u]:
            new_dist = d + w

            if new_dist < dist[v]:
                dist[v] = new_dist
                heapq.heappush(pq, (new_dist, v))

    return -1 if dist[t] == float('inf') else dist[t]

def solve(n, edges, s, t):
    sorted_order = topological_sort(edges)

    for _ in range(n - 1):
        _, v, _ = edges.pop(0)
        edges.extend((v, u, w) for u, w in graph[v])

    return dijkstra(n, edges, s, t)

