            if u in visited: continue
            visited.add(u)
            for v, w in edges:
                if v == u:
                    if dist[v] > dist[u] + w:
                        dist[v] = dist[u] + w
                        parent[v] = u
                        heappush(heap, (dist[v], v))
                elif v not in visited:
                    if dist[v] > dist[u] + w:
                        dist[v] = dist[u] + w
                        parent[v] = u
                        heappush(heap, (dist[v], v))
