import heapq

def solve(n, edges, s, t):
    def find(u, p):
        if parent[u] != u:
            parent[u] = find(parent[u], p)
        return parent[u]

    parent = list(range(n))
    rank = [0]*n
    size = [1]*n
    edges = [(w, u, v) for u, v, w in edges]
    edges.sort()

    def Union(u, v):
        u_root = find(u, n)
        v_root = find(v, n)
        if u_root == v_root:
            return
        if rank[u_root] < rank[v_root]:
            parent[u_root] = v_root
            size[v_root] += size[u_root]
        else:
            parent[v_root] = u_root
            size[u_root] += size[v_root]
            if rank[u_root] == rank[v_root]:
                rank[u_root] += 1

    MST = []
    for d, u, v in edges:
        if find(u, n) != find(v, n):
            MST.append((u, v))
            Union(u, v)
    if find(s, n) != find(t, n):
        return -1
    parent[s] = s
    distance = [float('inf')]*n
    distance[s] = 0
    queue = [(0, s)]

    while queue:
        du, u = heapq.heappop(queue)
        if du > distance[u]:
            continue
        for v in range(n):
            if parent[v] == parent[u]:
                continue
            parent[v] = u
            if distance[v] > du + edges[0][0]+n:
                distance[v] = du + edges[0][0] + n
                heapq.heappush(queue, (distance[v], v))
                while v - 1 >= 0 and parent[v-1] == u:
                    v -= 1
                w = min(v, n-1)
                while w + 1 < n and parent[w+1] == u:
                    w += 1
                edges[0] = (edges[0][0]+n, u, w+1)
                edges[0:0] = [(edges[0][0]-w-1, u, i) for i in range(w, u, -1) if i in [x[1] for x in MST]]
                heapq.heapify(edges)
            elif distance[v] > du + edges[0][0]:
                distance[v] = du + edges[0][0]
                heapq.heappush(queue, (distance[v], v))
    return min(distance)

