def solve(n, edges, s, t):
    def build_graph(n, edges):
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
        return graph

    def dijkstra(graph, start):
        pq = [(0, start)]
        dist = [float('inf')] * len(graph)
        parent = [None] * len(graph)

        while pq:
            curr_dist, u = heapq.heappop(pq)
            if curr_dist > dist[u]:
                continue
            for v, w in graph[u]:
                alt = curr_dist + w
                if alt < dist[v]:
                    dist[v] = alt
                    parent[v] = u
                    heapq.heappush(pq, (alt, v))
        return dist, parent

    graph = build_graph(n, edges)
    if s == t:
        return 0
    dist, parent = dijkstra(graph, s)
    if dist[t] == float('inf'):
        return -1
    path_len = 0
    v = t
    while v is not None:
        path_len += 1
        v = parent[v]
        if v == s:
            break
    return dist[t] if path_len == n else -1

