def solve(n, edges, s, t):
    res = sys.maxsize
    if s == t:
        return 0
    dist = [[sys.maxsize] * n for _ in range(n)]
    edges = list(set(edges))  # Remove parallel edges
    for u, v, w in edges:
        dist[u][v] = w
    for i in range(n):
        dist[i][i] = 0
    for u, v in edges:
        if dist[u][v] < 0:
            raise ValueError("Negative edge weight is not allowed")

    for u in range(n):
        for v in range(n):
            dist[u][v] = min(dist[u][v], sys.maxsize)
            if u == v and 1 <= u <= n - 1:
                dist[u][v] = 0
    for v in range(n):
        for u in range(n):
            for k in range(n):
                if dist[u][k] + dist[k][v] < dist[u][v]:
                    dist[u][v] = dist[u][k] + dist[k][v]
    if t < 0 or t >= n:
        raise ValueError("Invalid node index")
    return dist[s][t] if dist[s][t] < sys.maxsize else -1

