    prev_len = distances[u]
    distances[u] = -float('inf')
    for v, w in graph[u]:
        if not used[v] and dfs(v, graph, used, distances):
            distances[u] = max(distances[u], prev_len + w)
            return True
    used[u] = False
    return False

def bellman_ford(n, graph, s):
    distances = [float('inf')] * n
    distances[s] = 0
    cut = False
    for _ in range(n - 1):
        for u in range(n):
            for v, w in graph[u]:
                if distances[u] != float('inf') and distances[u] + w < distances[v]:
                    distances[v] = distances[u] + w
                    cut = True
    if cut:
        for u in range(n):
            for v, w in graph[u]:
                if distances[u] != float('inf') and distances[u] + w < distances[v]:
                    raise ValueError("Graph contains a negative-weight cycle")
    return distances

def dijkstra(n, graph, s):
    distances = [float('inf')] * n
    distances[s] = 0
    priority_queue = [(0, s)]
    while priority_queue:
        dis, u = heapq.heappop(priority_queue)
        if dis > distances[u]:
            continue
        for v, w in graph[u]:
            if distances[u] + w < distances[v]:
                distances[v] = distances[u] + w
                heapq.heappush(priority_queue, (distances[v], v))
    return distances

