            if dist[v] > new_dist:
                dist[v] = new_dist
                heapq.heappush(pq, (new_dist, v))

    return dist[t] ifdist[t] != float('inf') else -1

def min_cost_max_flow(n, sources, sinks, cap, cost):
    parent = [-1] * n
    d = [float('inf')] * n
    match = [0] * n

    for s in sources:
        d[s] = 0

    pq = [(0, 0)]
    while pq:
        d_val, u = heapq.heappop(pq)

        if d_val != d[u]:
            continue

        for v, c in cap[u]:
            if c > 0:
                v_value = d_val + cost[u][v] + match[u] - match[v]
                if d[v] > v_value:
                    d[v] = v_value
                    match[v] = match[u] + c
                    heapq.heappush(pq, (v_value, v))

    total_flow = 0
    total_cost = 0
    for s, t in zip(sources, sinks):
        flow, cost = cost_max_flow(s, t, cap, match, n)
        total_flow += flow
        total_cost += flow * cost

    return total_cost, total_flow

def cost_max_flow(s, t, cap, match, n):
    parent = [-1] * n
    dist = [float('inf')] * n
    dist[s] = 0

    pq = [(0, s)]
    while pq:
        d_val, u = heapq.heappop(pq)

        if d_val != dist[u]:
            continue

        for v, c in cap[u]:
            if c > 0 and v not in parent:
                parent[v] = u
                v_value = d_val + match[u] - match[v]
                if dist[v] > v_value:
                    dist[v] = v_value
                    heapq.heappush(pq, (v_value, v))

    path = []
    v = t
    u = parent[v]
    while u != -1:
        path.append((u, v))
        v = u
        u = parent[v]

        if u == s:
            break

    if not path:
        return 0, 0

    flow = float('inf')
    cost = 0
    for u, v in path:
        flow = min(flow, cap[u][v])
        cost += (match[u] - match[v]) * cap[u][v]

    for u, v in path:
        cap[u][v] -= flow
        cap[v][u] += flow
        match[u] += flow
        match[v] -= flow

