def parent(u, tree):
    if u == tree[u]:
        return u
    return parent(u, tree)

def solve(n, edges, s, t):
    if s == t:
        return 0

    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((v, -sys.maxsize))  # Negative infinity for going through parallel edges

    tree = list(range(n))
    nick = [0] * n

    seen = [False] * n
    h = []

    total = [None] * n
    for u in range(n):
        seen[u] = True
        heapq.heappush(h, (0, u, u))
        count = 0

        while h:
            dist, par, u = heapq.heappop(h)
            if par == u or seen[u]:
                continue
            seen[u] = True
            while u != par:
                count += 1
                if count > n:
                    return len(graph[u])
                elif u == s and (count < nick[u] or dist + 1 > total[u]):
                    total[u] = dist + 1
                    nick[u] = count
                    heapq.heappush(h, (total[u] - nick[u], u, u))
                tree[u] = parent(u, graph[u])
                u = par

        if total[t] is None:
            return -1

