from heapq import heappop, heappush

def solve(n, edges, s, t):
    hash_edges = {}
    for u, v, w in edges:
        if (u, v) not in hash_edges:
            hash_edges[(u, v)] = w
        else:
            hash_edges[(u, v)] = min(hash_edges[(u, v)], w)

    hashes = set(hash_edges.keys())
    for u, v in hashes:
        hashes.add((v, u))
    max_hashes = len(hashes)

    dist = [float('inf')] * n
    pq = [(0, s)]
    dist[s] = 0

    # Process all edges
    for i in range(max_hashes):
        nq = []
        while pq:
            d, x = heappop(pq)
            if x == t:
                return d
            if d > dist[x]:
                continue
            for y in range(n):
                if y in hashes:  # Edges of the current type
                    u, v = list(hashes)[y]
                    if dist[u] > dist[x] + hash_edges[(u, v)]:
                        dist[v] = d = dist[u] = dist[x] + hash_edges[(u, v)]
                        heappush(nq, (d, v))
                else:  # Rev edges of the previous type
                    u, v = list(hashes)[y - n]
                    if dist[v] > dist[x] + hash_edges[(v, u)]:
                        dist[u] = d = dist[v] = dist[x] + hash_edges[(v, u)]
                        heappush(nq, (d, u))
        pq = nq

