        visited[node] = True
        for next_node, weight in graph[node]:
            if not visited[next_node] and dist + weight < dists[next_node]:
                dists[next_node] = dist + weight
                dists[next_node] = dfs(next_node, dists[next_node])
        visited[node] = False
        return dists[t]

    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))
