    visited = [False] * n
    result = dfs(s, 0)
    return -1 if math.isinf(result) else result

def binary_search(g, max_dist, min_dist):
    while max_dist >= min_dist:
        mid = (max_dist + min_dist) // 2
        explored = set()
        queue = [(0, 0)]
        dists = [math.inf] * len(g)
        dists[0] = 0
        while queue:
            d, u = heapq.heappop(queue)
            if dists[u] < d:
                continue
            if u in explored:
                continue
            explored.add(u)
            for v, cost in g[u]:
                if dists[v] > d + cost:
                    dists[v] = d + cost
                    heapq.heappush(queue, (d + cost, v))
        if dists[-1] <= mid:
            max_dist = mid - 1
        else:
            min_dist = mid + 1
    return -1 if math.isinf(dists[-1]) else dists[-1]

def bellman_ford(g, s):
    dists = [math.inf] * len(g)
    dists[s] = 0
    for _ in range(len(g) - 1):
        for u, neighbors in enumerate(g):
            for v, cost in neighbors:
                if dists[v] > dists[u] + cost:
                    dists[v] = dists[u] + cost
    for u, neighbors in enumerate(g):
        for v, cost in neighbors:
            if dists[v] > dists[u] + cost:
                return -1
    return dists[-1]

def dijkstra(g):
    dists = [math.inf] * len(g)
    dists[0] = 0
    queue = [(0, 0)]
    explored = set()
    while queue:
        _, u = heapq.heappop(queue)
        if u in explored:
            continue
        explored.add(u)
        for v, cost in g[u]:
            if dists[v] > dists[u] + cost:
                dists[v] = dists[u] + cost
                heapq.heappush(queue, (dists[v], v))
    return dists[-1]
